window.__BUNDLE = {"body": "<div class=\"wrap\">\n\n  <section id=\"intro\" class=\"stack\" style=\"gap:28px\">\n    <div data-greeting></div>\n    <div id=\"testStart\" class=\"stack\" style=\"gap:28px\" hidden>\n      <div class=\"stack\">\n        <div class=\"eyebrow\">Для себя · путеводитель и тест</div>\n        <h1>Ступени устойчивости</h1>\n        <p class=\"slogan\">Чтобы стать своей и чувствовать себя в новой стране как дома</p>\n        <p class=\"lead\">После переезда жизнь приходится строить заново, как дом: снизу вверх. Сначала земля под ногами, потом очаг и свои люди, потом голос, порядок, дело, смысл. Здесь можно узнать, что это за ступени, и проверить, какие из них уже держат тебя, а какая поскрипывает.</p>\n      </div>\n      <div class=\"st-resume\" id=\"stResume\" hidden></div>\n      <div class=\"st-tiles\" id=\"stTiles\"></div>\n      <div id=\"stAB\"></div>\n      <div data-reportfan></div>\n      <div class=\"st-entries\">\n        <button type=\"button\" class=\"st-entry\" id=\"goGuide\"><span class=\"st-eh\">Узнать ступени</span><span>Путеводитель по восьми ступеням: что это за ступени, как они выглядят после переезда, и вопросы, чтобы узнать себя.</span><span class=\"st-go\">Читать →</span></button>\n        <button type=\"button\" class=\"st-entry main\" id=\"goTest\"><span class=\"st-eh\">Пройти тест «7 ступеней устойчивости»</span><span>Какие ступени держат тебя в новой стране, а какая поскрипывает, и с чего начать именно тебе. Около 20 минут.</span><span class=\"st-go\">Пройти тест →</span></button>\n      </div>\n\n      <section id=\"guide\" class=\"stack\" style=\"gap:18px\" hidden></section>\n\n      <section id=\"testPrep\" class=\"stack\" style=\"gap:24px\" hidden>\n        <div class=\"card stack\">\n          <div class=\"eyebrow\">Тест · около 20 минут</div>\n          <h2>7 ступеней устойчивости</h2>\n          <p>Представь лестницу в доме, который ты строишь в новой стране. Семь ступеней: от земли под ногами до вида на всю свою жизнь с холма. Какие-то ступени под тобой уже крепкие, а какая-то, может быть, поскрипывает, и из-за неё трудно подниматься выше, сколько ни старайся. Тест поможет услышать этот скрип.</p>\n          <p>В нём три небольшие части. <b>О тебе</b>: два вопроса о твоей истории. <b>Опора</b>: короткие фразы о твоей жизни, отмечай, насколько каждая про тебя. <b>Ситуации</b>: двенадцать жизненных сценок, в каждой нужно распределить 10 баллов между четырьмя вариантами.</p>\n          <p>Налей себе чаю и найди тихий уголок: это время только для тебя. Здесь нет правильных и неправильных ответов. Отвечай не «как должно быть», а как есть, за последние четыре недели.</p>\n          <div class=\"scale-legend\"><span><b>0</b> совсем не про меня</span><span><b>1</b> скорее нет</span><span><b>2</b> отчасти</span><span><b>3</b> скорее да</span><span><b>4</b> точно про меня</span></div>\n          <p class=\"note\">Это не оценка и не проверка «нормальная ли я». Почти все, кто переехал, заново проходят нижние ступени: это не слабость, а цена переезда. Тест не является диагнозом.</p>\n        </div>\n        <div data-testinfo></div>\n        <div class=\"stack\">\n          <h3>Как тебя зовут?</h3>\n          <div class=\"row\" style=\"align-items:stretch\">\n            <div class=\"field\"><label for=\"nameMe\">Твоё имя</label><input id=\"nameMe\" maxlength=\"30\" autocomplete=\"given-name\" placeholder=\"Например, Анна\"></div>\n          </div>\n          <p class=\"note\">Имя нужно только для красивого разбора.</p>\n        </div>\n        <div><button class=\"btn\" id=\"startBtn\">Начать тест</button></div>\n        <div data-share=\"compact\" style=\"margin-top:8px\"></div>\n      </section>\n    </div>\n  </section>\n\n  <section id=\"quiz\" class=\"stack\" hidden style=\"gap:20px\">\n    <div class=\"stack\" style=\"gap:10px\">\n      <div class=\"row\" style=\"justify-content:space-between\">\n        <span class=\"eyebrow\" id=\"stepLabel\"></span>\n        <span class=\"eyebrow\" id=\"countLabel\"></span>\n      </div>\n      <div class=\"progress\"><i id=\"prog\" style=\"width:0\"></i></div>\n    </div>\n    <div class=\"stack\" style=\"gap:6px\">\n      <div><span class=\"part-tag\" id=\"partTag\"></span></div>\n      <h2 id=\"roleTitle\"></h2>\n      <p class=\"muted\" id=\"roleSub\"></p>\n    </div>\n    <div class=\"card\" id=\"qlist\" style=\"padding-block:6px\"></div>\n    <div class=\"row\" style=\"justify-content:space-between\">\n      <button class=\"btn ghost\" id=\"back\">Назад</button>\n      <button class=\"btn\" id=\"next\" disabled>Дальше</button>\n    </div>\n  </section>\n\n  <section id=\"result\" hidden>\n    <div class=\"rep\" id=\"report\"></div>\n    <div data-share style=\"margin-top:18px\"></div>\n    <div data-lead></div>\n  </section>\n\n  <div data-disclaimer style=\"margin-top:28px\"></div>\n</div>\n<div class=\"pdf-stage\" id=\"stage\" aria-hidden=\"true\"></div>\n", "scripts": ["/* Настройки сайта, общие для всех тестов */\n// Ссылка веб-приложения Google Apps Script (заканчивается на /exec). Одна на все тесты.\nconst ENDPOINT = 'https://script.google.com/macros/s/AKfycbyizp1XjzNdrUj4WHgj4Vyj81QhjY2D7puqyeY3LaweWB4mePxPhfHCx5fIsfaJy9hV/exec';\n// Адрес сайта после размещения, например 'https://irina-tests.netlify.app/' (нужен для ссылок в PDF)\nconst SITE_URL = 'https://irynawiederkehr-cmd.github.io/tests/';\n// Ссылки на тесты, пока сайт не размещён (используются для кнопки «Поделиться» и блока «Пройди также»).\n// После размещения сайта достаточно заполнить SITE_URL — эти ссылки больше не понадобятся.\nconst TEST_LINKS = {\n  'roza-lyubvi': 'https://claude.ai/artifact/6Nv7pCtqpAd9xoWUkvEwS1',\n  'kompas': 'https://claude.ai/artifact/5TPCgkiVSZEr8H2g8d1UkY'\n};\n// Деловой почтовый адрес и e-mail для «Выходных данных» и «Политики конфиденциальности».\n// ЛИЧНЫЙ АДРЕС ИРИНЫ НЕ УКАЗЫВАТЬ. Пока поля пустые, на страницах стоит временная строка «скоро появятся».\n// address — строки через \\n, например 'Musterstrasse 1\\n8000 Zürich'.\nconst LEGAL = { address: '', email: '', since: '02.10.2026' };\n", "const BRAND = 'coach';\nconst TEST_META = { id: 'stupeni', name: 'Ступени устойчивости', slogan: 'Чтобы стать своей и чувствовать себя в новой стране как дома' };\nconst TEST_INFO = {\n  why: 'Я разработала этот опросник, чтобы помочь тебе бережно посмотреть на свою жизнь в новой стране как на дом, который строится снизу вверх. После переезда почти все заново проходят нижние ступени: сон и силы, свои люди, свой голос, понятные правила. Опросник показывает, какие ступени под тобой уже крепкие, а какая поскрипывает, и подсказывает, с чего начать именно тебе.',\n  from: [\n    'Ты живёшь в новой стране, и вроде бы всё идёт своим чередом, но что-то не так. Сил меньше, чем хотелось бы. Кажется, что браться нужно за всё сразу: язык, работу, друзей, документы, детей, и непонятно, с чего начать.',\n    'Иногда кажется, что другие справляются, а ты нет. И от этого становится ещё тяжелее.'\n  ],\n  to: [\n    'Ты видишь свою жизнь как дом, который строится снизу вверх, и знаешь, какие ступени под тобой уже крепкие. Это твоя опора, и её больше, чем казалось.',\n    'Ты знаешь одну ступень, с которой стоит начать, и понимаешь, почему именно с неё. Видишь, где именно трещина: в том, что ты чувствуешь, что делаешь, что есть вокруг тебя или во что ты веришь. Слышишь, что громче всего звучит в твоём сердце, и отличаешь мечту от опоры.',\n    'И уходишь с одним маленьким шагом на эту неделю.'\n  ],\n  key: 'Не нужно чинить всё сразу. Достаточно укрепить одну ступень, и всё, что выше, станет легче. А усталость и растерянность после переезда не слабость, а цена, которую платят почти все.',\n  next: [\n    'Отнесись к результату бережно: это снимок последних 4 недель, а не оценка тебя.',\n    'Начинай с самой нижней ступени, которая поскрипывает, даже если хочется сразу наверх.',\n    'Опирайся на крепкие ступени: они уже твои.',\n    'Прочитай про свою ступень в путеводителе и ответь себе на вопросы в конце.',\n    'Через 4–6 недель пройди тест снова и посмотри, что изменилось.',\n    'Если становится очень тяжело, поговори с близким человеком или со специалистом.'\n  ]\n};\nconst TEST_DISCLAIMER = [\n  'Путеводитель и тест «Ступени устойчивости» — инструменты самопознания. Они не являются психологической или медицинской диагностикой, психотерапевтическим заключением и не заменяют консультацию специалиста. Тест не является диагнозом.',\n  'Результаты теста отражают твоё личное восприятие за последние 4 недели и могут меняться.',\n  'Вопросы жилья, документов, статуса и денег решают социальные службы, юристы и государственные учреждения. Коучинг их не заменяет.',\n  'Если ты переживаешь кризис, насилие или угрозу своей безопасности, обратись к специалисту или в экстренные службы своей страны.'\n];\n\n/* превью отчёта веером на стартовой странице (картинки — src/stupeni/preview/1..5.jpg) */\nconst REPORT_FAN = {\n \"pages\": \"12\",\n \"title\": \"Каким будет твой разбор\",\n \"lead\": \"Личный разбор на 12 страницах соберётся из твоих ответов и останется у тебя в PDF. К нему прилагается бланк для записей. Вот несколько страниц из примера: так выглядит разбор Анны, которая недавно переехала.\",\n \"items\": [\n  {\n   \"t\": \"Твоя лестница\",\n   \"d\": \"Какая ступень держит крепко, какая поскрипывает и с какой лучше начать. Главное видно уже на первой странице.\"\n  },\n  {\n   \"t\": \"Три колеса\",\n   \"d\": \"Где ты сейчас, куда тебе хочется и насколько далеко одно от другого. Разницу видно без лишних слов.\"\n  },\n  {\n   \"t\": \"Где именно трещина\",\n   \"d\": \"Твоя ступень по четырём граням: что ты чувствуешь, что делаешь, что думаешь и что вокруг тебя. И твои собственные слова.\"\n  },\n  {\n   \"t\": \"Куда ты движешься\",\n   \"d\": \"Хочешь ли ты остаться, в каком ты сейчас состоянии и что именно тебя останавливает.\"\n  },\n  {\n   \"t\": \"Следующий шаг\",\n   \"d\": \"Приглашение на встречу-знакомство: 30 минут онлайн, чтобы познакомиться, проговорить твой запрос и понять, насколько я могу быть тебе полезна.\"\n  },\n  {\n   \"t\": \"Бланк для записей\",\n   \"d\": \"Отдельный файл со всеми вопросами и шагами из разбора. Распечатай его и ответь своей рукой: так ответы честнее, а шаги ближе.\"\n  }\n ]\n};\n", "/* язык страницы: задаёт загрузчик (ru, uk, de, en) */\nconst DATE_LOCALE = ({ ru:'ru-RU', uk:'uk-UA', de:'de-CH', en:'en-GB' })[(typeof LANG !== 'undefined') ? LANG : 'ru'] || 'ru-RU';\n/* =====================================================================\n   Общие тексты и блоки для всех тестов Ирины Вознесенской.\n   Меняешь здесь — меняется во всех тестах сразу.\n   ===================================================================== */\n\n/* ---------- Обо мне и контакты ---------- */\nconst AUTHOR = {\n  name: 'Ирина Вознесенская',\n  about: 'Коуч ICF в Швейцарии и психолог в Украине.',\n  coach: { place: 'Швейцария · Цюрих', title: 'Коуч', badge: 'Трансформационный коуч и нейрокоуч ICF',\n           text: ['Я помогаю тем, кто по разным причинам покинул свою страну и теперь заново строит жизнь на новом месте. Я знаю, сколько сил это забирает: стресс, который не отпускает даже после получения документов, чужие правила, язык, на котором пока не получается сказать самое важное, и тихое чувство, что вместе с домом ты оставила часть себя.',\n                  'В нашей работе мы идём на глубину, через эмоциональный интеллект, туда, где рождаются твои реакции и решения. Поэтому перемены происходят изнутри и остаются с тобой. Шаг за шагом ты начинаешь чувствовать себя своей в чужой стране, находишь своё место, бережно пересобираешь себя и словно рождаешься здесь заново, чтобы жить свою счастливую жизнь.'],\n           legal: 'В Швейцарии работаю только как коуч. Коучинг не является психотерапией и не заменяет психологическую или медицинскую помощь.',\n           instagram: 'https://www.instagram.com/iryna.voznesenskaya/', telegram: 'https://t.me/IrynaNeuroCoach_channel' },\n  psy:   { place: 'Украина · Киев', title: 'Психолог в Украине', badge: 'Психолог · аналитическая психология К. Г. Юнга',\n           text: ['Я работаю с теми, кому важны живые, тёплые отношения. Часто любовь никуда не уходит, просто её становится не слышно за усталостью, обидами и бытом, и каждый остаётся со своей болью наедине.',\n                  'Я работаю на глубине бессознательных процессов: через глубокий диалог, метафору, образы и символы, опираясь на аналитическую психологию Карла Юнга. Так становится видно то, о чём трудно сказать словами, и у пары появляется возможность снова услышать друг друга, вернуть близость и тепло.'],\n           legal: 'Как психолог работаю только с клиентами в Украине, на основании украинской квалификации.',\n           instagram: 'https://www.instagram.com/voznesenskayairyna.psy/', telegram: 'https://t.me/IrynaVoznesenska_psy' }\n};\n\n/* ---------- Все тесты (для главной и блока «Пройди также») ---------- */\nconst TESTS = [\n  { id: 'kompas', path: 'kompas/', name: 'Компас адаптации', slogan: 'Где ты сейчас в новой стране и куда идти дальше', brand: 'coach', tag: 'Для себя · 10 минут', pages: 11,\n    door: 'Я переехала и хочу понять, где я сейчас',\n    text: 'Где ты сейчас после переезда: шесть сфер новой жизни, твой путь между двумя культурами и следующий маленький шаг.' },\n  { id: 'stupeni', path: 'stupeni/', name: 'Ступени устойчивости', slogan: 'Чтобы стать своей и чувствовать себя в новой стране как дома', brand: 'coach', tag: 'Для себя · путеводитель и тест · 20 минут', pages: 12,\n    door: 'Хочу понять, почему не получается двигаться к цели',\n    text: 'Жизнь в новой стране строится как дом, снизу вверх. Узнай, какие из семи ступеней уже держат тебя, а какая поскрипывает, и с чего начать именно тебе.' },\n  { id: 'blizost', path: 'blizost/', name: 'Быть рядом и быть собой', slogan: 'Близость, в которой не нужно терять себя', brand: 'psy', tag: 'Тест-рефлексия о паре · 20 минут', pages: 14,\n    door: 'Хочу понять, насколько мы близки на самом деле',\n    text: 'Четыре опоры пары: близость, страсть, обязательство и умение оставаться собой. Узнай, где у вас подлинная близость, а где слияние, и что удерживает тебя от того, чтобы подойти ближе.' },\n  { id: 'roza-lyubvi', path: 'roza-lyubvi/', name: 'Роза любви', slogan: 'Чтобы снова услышать друг друга и вернуть в пару тепло', brand: 'psy', tag: 'Для пары · 15 минут', pages: 12,\n    door: 'Хочу понять, что происходит в нашей паре',\n    text: 'Три роли в паре: притяжение, близость и ответственность. Узнай, какие роли звучат ярко, а какие стали тише, и как вы встречаетесь друг с другом.' }\n];\n\nconst handle = url => '@' + url.replace(/\\/+$/, '').split('/').pop();\nconst pickOne = arr => arr[Math.floor(Math.random() * arr.length)];\nconst BASE = (typeof SITE_BASE !== 'undefined') ? SITE_BASE : '../';\n\nfunction practiceHtml(key){\n  const p = AUTHOR[key];\n  const links = [\n    p.instagram ? `<a href=\"${p.instagram}\" target=\"_blank\" rel=\"noopener\">Instagram ${handle(p.instagram)}</a>` : '',\n    p.telegram ? `<a href=\"${p.telegram}\" target=\"_blank\" rel=\"noopener\">Telegram-канал</a>` : ''\n  ].filter(Boolean).join('');\n  return `<div class=\"practice ${key}\"><span class=\"place\">${p.place}</span><h4>${p.title}</h4>${p.badge ? `<span class=\"pbadge\">${p.badge}</span>` : ''}${[].concat(p.text).map(t => `<p>${t}</p>`).join('')}${p.legal ? `<p class=\"plegal\">${p.legal}</p>` : ''}<div class=\"links\">${links}</div></div>`;\n}\nfunction authorHtml(label = 'Об авторе теста'){\n  const order = BRAND === 'coach' ? ['coach','psy'] : ['psy','coach'];\n  return `<div class=\"blk author\"><div class=\"eyebrow\">${label}</div>\n    <div class=\"who\"><div class=\"mono\">ИВ</div><div><b>${AUTHOR.name}</b><span>${AUTHOR.about}</span></div></div>\n    <div class=\"practices\">${order.map(practiceHtml).join('')}</div></div>`;\n}\nfunction footerLine(){\n  return '© ' + new Date().getFullYear() + ' · ' + (typeof TEST_META !== 'undefined' ? '«' + TEST_META.name + '» · ' : '') + (BRAND === 'coach' ? 'Ирина Вознесенская · коуч ICF (Швейцария) · психолог (Украина)' : 'Ирина Вознесенская · психолог (Украина) · коуч ICF (Швейцария)');\n}\n\n/* ---------- Приветствие и обязательный мини-опрос ---------- */\nconst SURVEY = {\n  heard: { q: 'Откуда ты обо мне знаешь?', opts: ['Instagram','Telegram','Рекомендация друзей или знакомых','Поиск в Google','Facebook','Другое'] },\n  interest: { q: 'Что тебе интересно?', opts: ['Психология: отношения в паре','Коучинг: адаптация после переезда и поиск себя','Пока просто интересно'] }\n};\nconst GREET = {\n  head: ['Привет! Я {A}','Рада тебе! Меня зовут {A}','Добро пожаловать! Я {A}','Здравствуй! Я {A}'],\n  about: ['Коуч ICF в Швейцарии и психолог в Украине.','Работаю на две страны: коуч ICF в Швейцарии и психолог в Украине.','Помогаю людям находить себя и строить тёплые отношения: как коуч ICF в Швейцарии и как психолог в Украине.'],\n  ask: ['Перед тестом ответь, пожалуйста, на три коротких вопроса. Так я лучше пойму, чем могу быть тебе полезна.',\n        'Три коротких вопроса перед началом, и сразу переходим к тесту.',\n        'Мне важно знать, кто приходит на мои тесты. Ответь, пожалуйста, на три коротких вопроса.']\n};\nfunction greetingHtml(){\n  const order = BRAND === 'coach' ? ['coach','psy'] : ['psy','coach'];\n  const group = key => `<fieldset class=\"survey\"><legend>${SURVEY[key].q} *</legend>${SURVEY[key].opts.map((o, i) =>\n    `<label class=\"check\"><input type=\"checkbox\" id=\"sv-${key}-${i}\" data-sv=\"${key}\" value=\"${o}\"> <span>${o}</span></label>`).join('')}</fieldset>`;\n  return `<div class=\"blk author greet\">\n    <div class=\"who\"><div class=\"mono\">ИВ</div><div><b>${pickOne(GREET.head).replace('{A}', AUTHOR.name)}</b><span>${pickOne(GREET.about)}</span></div></div>\n    <div class=\"practices\">${order.map(practiceHtml).join('')}</div>\n    <div class=\"stack\" style=\"gap:10px\"><p class=\"note\">${pickOne(GREET.ask)} Можно отметить несколько вариантов.</p>\n      <div class=\"surveys\">${group('heard')}${group('interest')}</div>\n      <p class=\"err\" id=\"svErr\" hidden></p>\n      <div><button class=\"btn\" type=\"button\" id=\"svGo\">Перейти к тестированию</button></div></div></div>`;\n}\nfunction surveyAnswers(){\n  const pick = key => [...document.querySelectorAll(`input[data-sv=\"${key}\"]:checked`)].map(i => i.value);\n  return { heard: pick('heard'), interest: pick('interest') };\n}\n\n/* ---------- Живое приглашение в работу (тексты каждый раз собираются заново) ---------- */\nconst INVITES = {\n  psy: {\n    open: ['{N}, спасибо за честные ответы.',\n           '{N}, ты уже делаешь важный шаг: честно смотришь на свою пару.',\n           '{N}, этот разбор — только начало разговора.',\n           '{N}, тест показывает картину, а настоящие изменения начинаются в разговоре.',\n           '{N}, за каждой цифрой в этом разборе стоит твоя история.'],\n    body: ['Цифры показывают, где в паре стало тихо. Но за ними всегда есть что-то своё: усталость, обиды, привычки, непроговорённые ожидания. На встрече мы бережно разберём твою ситуацию и найдём первые шаги, чтобы {F}.',\n           'Иногда достаточно одного точного вопроса, чтобы пара снова услышала друг друга. Если тебе хочется {F}, приглашаю на встречу: спокойно, бережно, без оценок.',\n           'Отношения меняются не от знаний, а от новых действий. Я помогаю парам найти эти действия и не бросить их через неделю. Давай вместе посмотрим, как {F}.',\n           'К изменениям можно идти в одиночку, а можно с поддержкой. На встрече мы обсудим твой треугольник и наметим, как {F}.',\n           'Многие пары годами живут с одним и тем же напряжением, потому что не знают, с чего начать разговор. Я помогу начать его так, чтобы {F}.'],\n    cta:  ['Запишись на встречу-знакомство 30 минут онлайн. Мы познакомимся, проговорим твой запрос и поймём, насколько я могу быть тебе полезна.',\n           'Встреча-знакомство длится 30 минут. Ты рассказываешь, что происходит в паре, я слушаю и задаю вопросы. За это время мы проговорим твой запрос и поймём, насколько я могу быть полезна вам.',\n           'Первая встреча — 30 минут онлайн, чтобы познакомиться, проговорить твой запрос и понять, насколько я могу быть тебе полезна.'],\n    title: ['Приглашаю на встречу 30 минут','Давай поговорим о твоей паре','Следующий шаг — разговор'],\n    legal: 'Консультации психолога проводятся онлайн для клиентов в Украине.'\n  },\n  coach: {\n    open: ['{N}, спасибо, что находишь время на себя.',\n           '{N}, ты уже делаешь важный шаг: смотришь на себя честно и бережно.',\n           '{N}, этот разбор — только начало пути.',\n           '{N}, иногда один тест открывает больше вопросов, чем ответов. И это хорошо.',\n           '{N}, всё, что ты сейчас видишь, можно превратить в опору.'],\n    body: ['Переезд меняет всё: язык, привычки, роли в семье и даже то, как мы видим себя. В коучинге мы ищем твои опоры в новом мире и шаг за шагом помогаем тебе {F}.',\n           'Когда меняется страна, меняемся и мы. Иногда это ощущается как потеря себя. Я помогаю найти себя заново, чтобы {F}.',\n           'За твоими плечами уже большой путь. Коучинг помогает собрать этот опыт в силу и {F}.',\n           'Ответы уже есть внутри тебя, но их трудно услышать в суете новой жизни. В работе со мной ты найдёшь свои ответы и решишь, как {F}.',\n           'Адаптация — это не только документы и язык. Это поиск своего места. Давай вместе посмотрим, как {F}.'],\n    cta:  ['Запишись на встречу-знакомство 30 минут онлайн. Мы познакомимся, проговорим твой запрос и поймём, насколько я могу быть тебе полезна.',\n           'Встреча-знакомство длится 30 минут. Ты рассказываешь, что для тебя сейчас важно, я слушаю и задаю вопросы. За это время мы проговорим твой запрос и поймём, насколько я могу быть тебе полезна.',\n           'Первая встреча — 30 минут онлайн, чтобы познакомиться, проговорить твой запрос и понять, насколько я могу быть тебе полезна.'],\n    title: ['Приглашаю на встречу 30 минут','Давай поговорим о тебе','Следующий шаг — разговор'],\n    legal: 'Коучинг не является психотерапией и не заменяет психологическую или медицинскую помощь.'\n  }\n};\nconst INVITE_HUMAN = {\n  coach: 'Тест даёт карту, но не видит тебя целиком. На личной встрече, когда мы работаем с твоим собственным запросом и под твою задачу, работа становится гораздо продуктивнее и даёт ощутимые результаты. Машина не может увидеть то, что заметит живой человек с профессиональными навыками: паузу перед ответом, интонацию, то, о чём ты молчишь, и то, что тебе на самом деле важно. Я работаю на глубине, через эмоциональный интеллект: мы смотрим не только на то, что ты делаешь, но и на то, что ты чувствуешь и что тобой движет. Поэтому изменения происходят на глубинном уровне, а не остаются красивым планом на бумаге.',\n  psy: 'Тест даёт карту, но не видит вашу пару целиком. На личной встрече, когда мы работаем с вашим собственным запросом и под вашу задачу, работа становится гораздо продуктивнее и даёт ощутимые результаты. Машина не может увидеть то, что заметит живой человек с профессиональными навыками: паузу перед ответом, интонацию, то, о чём молчат, и то, что на самом деле важно каждому из вас. Я работаю на глубине бессознательных процессов: через глубокий диалог, метафору и образы, опираясь на аналитическую психологию Карла Юнга. Так становится видно то, что движет парой изнутри и о чём словами сказать трудно.'\n};\nconst INVITE_FOCUS_DEFAULT = { psy: 'в отношениях стало больше тепла и понимания', coach: 'найти своё место в новом мире' };\nlet inviteSeed = null;\nfunction resetInvite(){ inviteSeed = null; }\nfunction invitePractice(country){\n  // как психолог Ирина работает только с клиентами в Украине; остальных приглашаем в коучинг\n  if (BRAND === 'psy' && country && country !== 'Украина') return 'coach';\n  return BRAND;\n}\nfunction inviteHtml(ctx){\n  if (!inviteSeed) inviteSeed = Array.from({length:6}, () => Math.random());\n  const key = invitePractice(ctx.country);\n  const P = INVITES[key], A = AUTHOR[key];\n  const pick = (arr, i) => arr[Math.floor(inviteSeed[i] * arr.length)];\n  const N = ctx.name || '';\n  const F = (ctx.focus && ctx.focus[key]) || INVITE_FOCUS_DEFAULT[key];\n  const fill = t => { let s = N ? t.replace('{N}', N) : t.replace('{N}, ', ''); s = s.replace('{F}', F); return s.charAt(0).toUpperCase() + s.slice(1); };\n  const links = [A.telegram ? `<a href=\"${A.telegram}\" target=\"_blank\" rel=\"noopener\">Telegram: ${A.telegram.replace('https://','')}</a>` : '',\n                 A.instagram ? `<a href=\"${A.instagram}\" target=\"_blank\" rel=\"noopener\">Instagram: ${handle(A.instagram)}</a>` : ''].filter(Boolean);\n  const other = key === 'psy' ? 'coach' : 'psy';\n  const wantsOther = (ctx.interest || []).some(x => other === 'coach' ? /Коучинг/.test(x) : /Психология/.test(x));\n  const otherLine = wantsOther && !(other === 'psy' && ctx.country && ctx.country !== 'Украина')\n    ? `<p class=\"note\">Тебе интересно и направление «${AUTHOR[other].title.replace(/^./, c => c.toLowerCase())}». Об этой работе можно узнать здесь: <a href=\"${AUTHOR[other].telegram}\" target=\"_blank\" rel=\"noopener\">${AUTHOR[other].telegram.replace('https://','')}</a></p>` : '';\n  const word = 'ВСТРЕЧА';\n  const ig = A.instagram ? 'https://ig.me/m/' + handle(A.instagram).slice(1) : '';\n  return `<div class=\"blk invite ${key}\">\n    <div class=\"inv-letter\">\n      <div class=\"eyebrow\">${key === 'psy' ? 'Работа над отношениями' : 'Работа над собой'}</div>\n      <h2>${pick(P.title, 0)}</h2>\n      <p class=\"inv-open\">${fill(pick(P.open, 1))}</p>\n      <p>${fill(pick(P.body, 2))}</p>\n      <p class=\"inv-human\">${key === 'psy' ? INVITE_HUMAN.psy : INVITE_HUMAN.coach}</p>\n      <p>${fill(pick(P.cta, 3))}</p>\n      <p class=\"inv-sign\">${AUTHOR.name.split(' ')[0]}</p>\n    </div>\n    <div class=\"inv-ticket\">\n      <div class=\"inv-facts\"><span><b>30</b>минут</span><span><b>онлайн</b>из дома</span><span><b>1:1</b>только мы</span></div>\n      <div class=\"inv-how\">\n        <p>Чтобы записаться, напиши мне одно слово:</p>\n        <div class=\"inv-word\"><span>«${word}»</span><button type=\"button\" class=\"inv-copy\" data-copy=\"${word}\">Скопировать</button></div>\n        <p class=\"inv-small\">и я предложу удобное время.</p>\n      </div>\n      <div class=\"inv-links\">\n        ${ig ? `<a class=\"inv-btn main\" href=\"${ig}\" target=\"_blank\" rel=\"noopener\">Написать в Instagram</a>` : ''}\n        ${A.telegram ? `<a class=\"inv-btn\" href=\"${A.telegram}\" target=\"_blank\" rel=\"noopener\">Telegram</a>` : ''}\n      </div>\n    </div>\n    ${otherLine}\n    <p class=\"note inv-legal\">${P.legal}</p></div>`;\n}\n\ndocument.addEventListener('click', async ev => {\n  const b = ev.target.closest('.inv-copy'); if (!b) return;\n  try { await navigator.clipboard.writeText(b.dataset.copy); b.textContent = 'Скопировано ✓'; }\n  catch(e){ const r = document.createRange(); r.selectNodeContents(b.previousElementSibling); const sel = getSelection(); sel.removeAllRanges(); sel.addRange(r); b.textContent = 'Выделено'; }\n  setTimeout(() => b.textContent = 'Скопировать', 2500);\n});\n\n/* ---------- Колесо-лепестки (общее для всех тестов) ----------\n   fill — закрашенные лепестки (0–100), outline — пунктир второй точки (0–100), sec — [{label, fill, line}] */\nlet __wheelN = 0;\nfunction petalWheelSVG(sec, fill, outline, size, turn){\n  const n = sec.length, a0 = -Math.PI / 2 + (turn || 0) * 2 * Math.PI / n, da = 2 * Math.PI / n;\n  const sideLen = Math.max(0, ...sec.map((q, k) => Math.abs(Math.cos(a0 + (k + .5) * da)) > .3 ? q.label.length : 0));\n  const W = size || 340, c = W / 2, R0 = W / 2 - Math.max(66, 16 + sideLen * 6.8), h = da / 2 * .9, id = 'pw' + (++__wheelN);\n  const P = (r, a) => `${(c + r * Math.cos(a)).toFixed(1)} ${(c + r * Math.sin(a)).toFixed(1)}`;\n  const petal = (r, th) => { r = Math.max(r, 10); const e = h * .8;\n    return `M${c} ${c}C${P(r * .45, th - h * 1.12)} ${P(r * .86, th - h * 1.12)} ${P(r * .97, th - e)}A${r} ${r} 0 0 1 ${P(r * .97, th + e)}C${P(r * .86, th + h * 1.12)} ${P(r * .45, th + h * 1.12)} ${c} ${c}Z`; };\n  let s = `<svg viewBox=\"0 0 ${W} ${W}\" role=\"img\" aria-label=\"Колесо\"><defs><filter id=\"${id}\" x=\"-5%\" y=\"-5%\" width=\"110%\" height=\"110%\"><feTurbulence type=\"fractalNoise\" baseFrequency=\".035\" numOctaves=\"2\" seed=\"${__wheelN % 7 + 2}\"/><feDisplacementMap in=\"SourceGraphic\" scale=\"4\"/></filter></defs>`;\n  s += `<circle cx=\"${c}\" cy=\"${c}\" r=\"${R0 + 6}\" fill=\"#FFFCF8\"/>`;\n  [.25, .5, .75, 1].forEach(f => s += `<circle cx=\"${c}\" cy=\"${c}\" r=\"${(R0 * f).toFixed(1)}\" fill=\"none\" stroke=\"#E2D6C6\" stroke-width=\"${f === 1 ? 1 : .7}\" ${f < 1 ? 'stroke-dasharray=\"1.5 4\"' : ''}/>`);\n  sec.forEach((q, k) => {\n    const th = a0 + (k + .5) * da;\n    if (fill) { const d = petal(R0 * fill[k] / 100, th); s += `<path d=\"${d}\" fill=\"${q.fill}\" fill-opacity=\".92\" filter=\"url(#${id})\"/><path d=\"${d}\" fill=\"none\" stroke=\"${q.line}\" stroke-width=\"1.3\" stroke-linejoin=\"round\"/>`; }\n    if (outline) s += `<path d=\"${petal(R0 * outline[k] / 100, th)}\" fill=\"none\" stroke=\"${q.line}\" stroke-width=\"2\" stroke-dasharray=\"4 4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>`;\n    const [lx, ly] = P(R0 + 18, th).split(' ').map(Number), anchor = Math.abs(lx - c) < 12 ? 'middle' : lx > c ? 'start' : 'end';\n    s += `<text x=\"${(anchor === 'start' ? lx - 2 : anchor === 'end' ? lx + 2 : lx).toFixed(1)}\" y=\"${(ly + 4).toFixed(1)}\" text-anchor=\"${anchor}\" font-family=\"Manrope, sans-serif\" font-size=\"12\" font-weight=\"700\" fill=\"${q.line}\">${q.label}</text>`;\n  });\n  return s + `<circle cx=\"${c}\" cy=\"${c}\" r=\"4\" fill=\"#8C7F71\"/></svg>`;\n}\nconst WHEEL_LEGEND = `<div class=\"st-legend\"><span><i class=\"f\"></i>где ты сейчас</span><span><i class=\"d\"></i>куда тебе хочется</span></div>`;\n\n/* ---------- Остаться или нет (для тестов про жизнь после переезда) ---------- */\nconst STAY_Q = 'Ты хочешь остаться здесь жить?';\nconst STAY_OPTS = ['Да, я решила остаться', 'Скорее да, но иногда сомневаюсь', 'Пока не знаю, думаю', 'Скорее нет: хочу вернуться или переехать дальше', 'Это решаю не только я'];\n\n/* ---------- Telegram-канал: приглашение подписаться ---------- */\n// Украина → канал психолога (украинская аудитория); любая другая страна или не указана → канал коуча (швейцарская аудитория)\nfunction channelHtml(country){\n  const ua = country === 'Украина' || (!country && BRAND === 'psy'), P = AUTHOR[ua ? 'psy' : 'coach'];\n  return `<div class=\"blk channel\"><div class=\"eyebrow\">Telegram-канал</div><h2>Присоединяйся к моему каналу</h2>\n    <p>Канал совсем новый. Здесь собирается наша ${ua ? 'украинская' : 'швейцарская'} аудитория: ${ua ? 'те, кому важны тёплые и живые отношения' : 'те, кто живёт в Швейцарии и строит здесь свою жизнь'}. В планах делиться нужной информацией, находить поддержку и единомышленников. Буду рада, если ты будешь среди первых.</p>\n    <div class=\"invite-links\"><a href=\"${P.telegram}\" target=\"_blank\" rel=\"noopener\">Подписаться: ${P.telegram.replace('https://', '')}</a></div></div>`;\n}\n\n/* ---------- Пройди также ---------- */\nfunction testUrl(t){\n  if (typeof SITE_URL !== 'undefined' && SITE_URL) return SITE_URL.replace(/\\/?$/, '/') + t.path;\n  if (typeof TEST_LINKS !== 'undefined' && TEST_LINKS[t.id]) return TEST_LINKS[t.id];\n  return BASE + t.path;\n}\nfunction moreTestsHtml(currentId){\n  const list = TESTS.filter(t => t.id !== currentId);\n  if (!list.length) return '';\n  return `<div class=\"blk more\"><div class=\"eyebrow\">Пройди также</div>\n    <div class=\"tcards\">${list.map(t => `<a class=\"tcard ${t.brand}\" href=\"${testUrl(t)}\" target=\"_blank\" rel=\"noopener\">\n      <span class=\"ttag\">${t.tag}</span><b>${t.name}</b><span class=\"tslogan\">${t.slogan}</span><span>${t.text}</span><span class=\"tgo\">Пройти тест →</span></a>`).join('')}</div></div>`;\n}\n\n/* ---------- Об этом опроснике + дисклеймер ---------- */\nconst DISCLAIMER = [\n  'Этот опросник — инструмент самопознания и разговора. Он не является психологической или медицинской диагностикой, психотерапевтическим заключением и не заменяет консультацию специалиста.',\n  'Результаты отражают твоё личное восприятие за последние 4 недели и могут меняться.',\n  'Если ты переживаешь кризис, насилие или угрозу своей безопасности, обратись к специалисту или в экстренные службы своей страны.'\n];\n/* Точка А → точка Б: если в TEST_INFO есть from / to / key — показываем, с чем человек приходит и с чем уходит. */\nfunction abHtml(){\n  if (typeof TEST_INFO === 'undefined' || !TEST_INFO.from) return '';\n  const ps = a => [].concat(a).map(x => `<p>${x}</p>`).join('');\n  return `<div class=\"ab\"><div class=\"ab-a\"><span class=\"ab-l\">Точка А · с чем ты приходишь</span>${ps(TEST_INFO.from)}</div>\n    <div class=\"ab-arrow\" aria-hidden=\"true\"><svg viewBox=\"0 0 40 24\" width=\"40\" height=\"24\"><path d=\"M2 12h32M26 4l8 8-8 8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></div>\n    <div class=\"ab-b\"><span class=\"ab-l\">Точка Б · с чем ты уходишь</span>${ps(TEST_INFO.to)}</div></div>\n    ${TEST_INFO.key ? `<div class=\"ab-key\"><b>Главное понимание</b><p>${TEST_INFO.key}</p></div>` : ''}`;\n}\nfunction testInfoHtml(){\n  if (typeof TEST_INFO === 'undefined') return '';\n  if (TEST_INFO.from) return `<div class=\"blk testinfo\"><div class=\"eyebrow\">Зачем проходить</div>\n    <p class=\"lead\">${TEST_INFO.why}</p>${abHtml()}\n    <div class=\"ti-cols\"><div><h3>Что с этим делать</h3><ul class=\"clean\">${TEST_INFO.next.map(x => `<li>${x}</li>`).join('')}</ul></div></div></div>`;\n  return `<div class=\"blk testinfo\"><div class=\"eyebrow\">Об этом опроснике</div>\n    <p class=\"lead\">${TEST_INFO.why}</p>\n    <div class=\"ti-cols\">\n      <div><h3>Что даёт прохождение</h3><ul class=\"clean\">${TEST_INFO.gives.map(x => `<li>${x}</li>`).join('')}</ul></div>\n      <div><h3>Что с этим делать</h3><ul class=\"clean\">${TEST_INFO.next.map(x => `<li>${x}</li>`).join('')}</ul></div>\n    </div></div>`;\n}\n/* Текст «Важно» сверяется по смыслу с каждым тестом: свой вариант — TEST_DISCLAIMER в meta.js (null = общая строка). */\nfunction disclaimerHtml(list){\n  const D = list || (typeof TEST_DISCLAIMER !== 'undefined' ? TEST_DISCLAIMER.map((x, i) => x || DISCLAIMER[i]).filter(Boolean) : DISCLAIMER);\n  return `<div class=\"disclaimer\"><b>Важно</b>${D.map(x => `<p>${x}</p>`).join('')}</div>`;\n}\n\n/* ---------- Поделиться тестом ---------- */\nconst SHARE_TEXT = {\n  'roza-lyubvi': ['Прошла тест «Роза любви» для пары — интересно и очень точно. Пройди и ты, потом сравним:',\n                  'Нашла тест «Роза любви»: 15 минут, и видно, какие роли в паре звучат ярко, а какие стали тише. Попробуй:'],\n  'kompas':      ['Прошла тест «Компас адаптации» для тех, кто живёт в новой стране. Очень помогает понять, где ты сейчас. Попробуй:',\n                  'Нашла тест «Компас адаптации»: 10 минут, и видно, что уже стало опорой в новой стране, а где пока тихо. Попробуй:'],\n  'blizost':     ['Прошла тест-рефлексию «Быть рядом и быть собой» — про то, насколько мы близки на самом деле. Очень глубокий. Попробуй:',\n                  'Нашла тест «Быть рядом и быть собой»: 20 минут честно о близости, страсти и о том, как не терять себя в паре. Пройди:'],\n  'stupeni':     ['Прошла тест «Ступени устойчивости» — очень тёплый и точный, про то, как заново строишь жизнь после переезда. Попробуй:',\n                  'Нашла «Ступени устойчивости»: путеводитель и тест для тех, кто живёт в новой стране. Видно, какие ступени держат, а какая поскрипывает. Пройди:',\n                  'Если ты тоже живёшь не в своей стране — пройди «Ступени устойчивости». Мне помогло понять, с чего начинать:']\n};\nconst SHARE_ICON = {\n  share: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 3v12M7 8l5-5 5 5M5 13v6a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>',\n  wa: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 20l1.2-4A8 8 0 1 1 8 18.8z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"M9 9.5c0 3 2.5 5.5 5.5 5.5l1-1.5-2-1-1 1c-1-.5-1.5-1-2-2l1-1-1-2z\" fill=\"currentColor\"/></svg>',\n  tg: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M21 4 3 11l6 2 2 6 3-4 5 4z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"m9 13 8-6\" stroke=\"currentColor\" stroke-width=\"2\"/></svg>',\n  copy: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"8\" y=\"8\" width=\"12\" height=\"12\" rx=\"2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/></svg>'\n};\nfunction shareData(){\n  const t = TESTS.find(x => typeof TEST_META !== 'undefined' && x.id === TEST_META.id) || TESTS[0];\n  return { url: testUrl(t), text: pickOne(SHARE_TEXT[t.id] || ['Попробуй этот тест:']), title: t.name };\n}\nfunction shareHtml(compact){\n  if (typeof TEST_META === 'undefined') return '';\n  const head = compact\n    ? `<p class=\"note\">Знаешь, кому этот тест тоже может быть полезен? Перешли ссылку.</p>`\n    : `<div class=\"eyebrow\">Поделиться</div><h3>Перешли тест друзьям</h3><p>Если тест оказался полезным, отправь его тем, кому он тоже может помочь. ${TEST_META.id === 'roza-lyubvi' || TEST_META.id === 'blizost' ? 'А ещё лучше — предложи пройти партнёру и сравните, как каждый из вас видит вашу пару.' : 'Особенно тем, кто тоже недавно переехал.'}</p>`;\n  return `<div class=\"${compact ? 'share compact' : 'blk share'}\">${head}\n    <div class=\"share-btns\">\n      ${navigator.share ? `<button type=\"button\" class=\"main\" data-share-act=\"native\">${SHARE_ICON.share}Поделиться</button>` : ''}\n      <button type=\"button\" data-share-act=\"wa\">${SHARE_ICON.wa}WhatsApp</button>\n      <button type=\"button\" data-share-act=\"tg\">${SHARE_ICON.tg}Telegram</button>\n      <button type=\"button\" data-share-act=\"copy\">${SHARE_ICON.copy}Скопировать ссылку</button>\n    </div>\n    <div class=\"share-link\" hidden><input readonly aria-label=\"Ссылка на тест\"></div>\n    <span class=\"share-ok\" hidden></span></div>`;\n}\nfunction openExternal(url){\n  const w = window.open(url, '_blank', 'noopener');\n  if (!w) location.href = url;\n}\ndocument.addEventListener('click', async (ev) => {\n  const b = ev.target.closest('[data-share-act]'); if (!b) return;\n  const box = b.closest('.share'), d = shareData(), act = b.dataset.shareAct;\n  const ok = box.querySelector('.share-ok');\n  const showOk = t => { ok.textContent = t; ok.hidden = false; setTimeout(() => ok.hidden = true, 4000); };\n  if (act === 'native'){\n    try { await navigator.share({ title: d.title, text: d.text, url: d.url }); return; }\n    catch(e){ if (e && e.name === 'AbortError') return; }\n  }\n  if (act === 'wa') return openExternal('https://wa.me/?text=' + encodeURIComponent(d.text + ' ' + d.url));\n  if (act === 'tg') return openExternal('https://t.me/share/url?url=' + encodeURIComponent(d.url) + '&text=' + encodeURIComponent(d.text));\n  try { await navigator.clipboard.writeText(d.text + ' ' + d.url); showOk('Ссылка скопирована. Вставь её в сообщение другу.'); }\n  catch(e){\n    const row = box.querySelector('.share-link'), inp = row.querySelector('input');\n    inp.value = d.url; row.hidden = false; inp.focus(); inp.select();\n    showOk('Скопируй ссылку из поля выше.');\n  }\n});\n\n/* ---------- Отрисовка общих блоков на странице ---------- */\ndocument.documentElement.dataset.brand = BRAND;\ndocument.querySelectorAll('[data-author]').forEach(el => el.innerHTML = authorHtml());\ndocument.querySelectorAll('[data-greeting]').forEach(el => el.innerHTML = greetingHtml());\ndocument.querySelectorAll('[data-testinfo]').forEach(el => el.innerHTML = testInfoHtml());\ndocument.querySelectorAll('[data-disclaimer]').forEach(el => el.innerHTML = disclaimerHtml());\n/* копирайт внизу каждой страницы сайта */\n(function(){ const w = document.querySelector('.wrap'); if (!w || w.querySelector('.copy')) return;\n  const f = document.createElement('footer'); f.className = 'copy'; f.textContent = '© ' + new Date().getFullYear() + ' Ирина Вознесенская. Все права защищены.'; w.appendChild(f); })();\ndocument.querySelectorAll('[data-share]').forEach(el => el.innerHTML = shareHtml(el.dataset.share === 'compact'));\n(function(){\n  const go = document.getElementById('svGo'); if (!go) return;\n  try { (JSON.parse(localStorage.getItem('irinaTestsSurvey') || '[]') || []).forEach(id => { const c = document.getElementById(id); if (c) c.checked = true; }); } catch(e){}\n  go.addEventListener('click', () => {\n    const a = surveyAnswers(), err = document.getElementById('svErr');\n    const miss = !a.heard.length ? 'Отметь, пожалуйста, откуда ты обо мне знаешь.' : !a.interest.length ? 'Отметь, пожалуйста, что тебе интересно.' : '';\n    err.textContent = miss; err.hidden = !miss;\n    if (miss) return;\n    try { localStorage.setItem('irinaTestsSurvey', JSON.stringify([...document.querySelectorAll('input[data-sv]:checked')].map(i => i.id))); } catch(e){}\n    document.querySelector('[data-greeting]').hidden = true;\n    document.getElementById('testStart').hidden = false;\n    window.scrollTo(0, 0);\n  });\n})();\n\n/* ---------- превью отчёта веером (стартовая страница теста) ---------- */\n(function(){\n  const host = document.querySelector('[data-reportfan]');\n  if (!host || typeof REPORT_FAN === 'undefined' || !window.RP_IMG || !RP_IMG.length) return;\n  const F = REPORT_FAN, N = Math.min(F.items.length, RP_IMG.length);\n  const calm = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;\n  host.className = 'rf';\n  host.innerHTML = `<div class=\"rf-head\"><div class=\"eyebrow\">Твой личный разбор · PDF</div><h3>${F.title}</h3><p>${F.lead}</p></div>\n    <div class=\"rf-stage stacked\" role=\"group\" aria-label=\"Страницы примера отчёта\">\n      ${F.items.slice(0, N).map((it, i) => `<button type=\"button\" class=\"rf-page\" data-i=\"${i}\" aria-label=\"Страница: ${it.t}\"><img src=\"${RP_IMG[i]}\" alt=\"Пример страницы отчёта: ${it.t}\" loading=\"lazy\" draggable=\"false\"></button>`).join('')}\n      <span class=\"rf-badge\">${F.pages}<small>страниц</small></span>\n    </div>\n    <div class=\"rf-cap\" aria-live=\"polite\"></div>\n    <div class=\"rf-nav\"><button type=\"button\" class=\"rf-arrow\" data-d=\"-1\" aria-label=\"Предыдущая страница\">‹</button><div class=\"rf-dots\">${F.items.slice(0, N).map((_, i) => `<span data-i=\"${i}\"></span>`).join('')}</div><button type=\"button\" class=\"rf-arrow\" data-d=\"1\" aria-label=\"Следующая страница\">›</button></div>\n    <p class=\"rf-hint\">Нажми на страницу в центре, чтобы рассмотреть её поближе.</p>`;\n  const stage = host.querySelector('.rf-stage'), pages = [...host.querySelectorAll('.rf-page')], dots = [...host.querySelectorAll('.rf-dots span')], cap = host.querySelector('.rf-cap');\n  let cur = 0, timer = null;\n  function lay(){\n    const w = stage.clientWidth, deg = w < 420 ? 8 : 10;\n    pages.forEach((p, i) => {\n      let o = i - cur; if (o > N / 2) o -= N; if (o < -N / 2) o += N;\n      const a = Math.abs(o);\n      p.style.transform = `translateX(-50%) rotate(${o * deg}deg) translateY(${o ? a * 4 : -16}px) scale(${o ? 1 - a * .04 : 1.03})`;\n      p.style.zIndex = 10 - a; p.classList.toggle('on', !o);\n      p.tabIndex = o ? -1 : 0;\n    });\n    dots.forEach((d, i) => d.classList.toggle('on', i === cur));\n    cap.innerHTML = `<b>${F.items[cur].t}</b><span>${F.items[cur].d}</span>`;\n  }\n  function go(i, user){ cur = (i + N) % N; lay(); if (user) stop(); }\n  function stop(){ if (timer) clearInterval(timer); timer = null; }\n  pages.forEach((p, i) => p.addEventListener('click', () => i === cur ? zoom(i) : go(i, true)));\n  dots.forEach((d, i) => d.addEventListener('click', () => go(i, true)));\n  host.querySelectorAll('.rf-arrow').forEach(b => b.addEventListener('click', () => go(cur + +b.dataset.d, true)));\n  let sx = null; stage.addEventListener('touchstart', e => { sx = e.touches[0].clientX; }, { passive: true });\n  stage.addEventListener('touchend', e => { if (sx == null) return; const dx = e.changedTouches[0].clientX - sx; if (Math.abs(dx) > 40) go(cur + (dx < 0 ? 1 : -1), true); sx = null; });\n  function zoom(i){\n    const box = document.createElement('div'); box.className = 'rf-zoom'; box.setAttribute('role', 'dialog'); box.setAttribute('aria-label', F.items[i].t);\n    box.innerHTML = `<figure><img src=\"${RP_IMG[i]}\" alt=\"Пример страницы отчёта: ${F.items[i].t}\"><figcaption>${F.items[i].t} · пример</figcaption></figure><button type=\"button\" class=\"rf-x\" aria-label=\"Закрыть\">×</button>`;\n    const close = () => { box.remove(); document.removeEventListener('keydown', esc); };\n    const esc = e => { if (e.key === 'Escape') close(); };\n    box.addEventListener('click', close); document.addEventListener('keydown', esc);\n    document.body.appendChild(box); box.querySelector('.rf-x').focus();\n  }\n  lay(); window.addEventListener('resize', lay);\n  const open = () => { stage.classList.remove('stacked'); if (!calm && !timer) timer = setInterval(() => go(cur + 1), 3800); };\n  if ('IntersectionObserver' in window && !calm) {\n    const io = new IntersectionObserver(es => { if (es.some(e => e.isIntersecting)) { setTimeout(open, 250); io.disconnect(); } }, { threshold: .35 });\n    io.observe(stage);\n  } else open();\n  host.addEventListener('pointerenter', stop);\n})();\n\n/* ---------- Бланк для записей (печатный PDF к разбору) ----------\n   Во время buildBlocks() тест записывает сюда свои вопросы и шаги:\n   wsReset(); wsAdd(заголовок, пояснение, [вопросы], строк); wsStep(текст). */\nlet WS = { sections: [], steps: [] };\nfunction wsReset(){ WS = { sections: [], steps: [] }; }\nfunction wsAdd(title, note, qs, lines = 6){ if (qs && qs.length) WS.sections.push({ title, note, qs, lines }); }\nfunction wsStep(t){ if (t) WS.steps.push(String(t).replace(/<[^>]+>/g, '')); }\nfunction liTexts(html){ const d = document.createElement('div'); d.innerHTML = html; return [...d.querySelectorAll('li')].map(x => x.textContent.replace(/\\s+/g, ' ').trim()).filter(Boolean); }\nconst wsLines = n => `<div class=\"ws-lines\">${'<i></i>'.repeat(n)}</div>`;\nfunction worksheetBlocks(opts = {}){\n  const pair = !!opts.pair, nm = opts.name ? esc(opts.name) : '';\n  const B = [];\n  B.push({ html: `<div class=\"blk ws ws-head\"><div class=\"eyebrow\">Бланк для записей · к разбору «${TEST_META.name}»</div>\n    <h1>${TEST_META.name}</h1>${TEST_META.slogan ? `<p class=\"slogan\">${TEST_META.slogan}</p>` : ''}\n    <div class=\"ws-fields\"><span>Имя<i>${nm}</i></span><span>Дата<i></i></span></div>\n    <p>Этот бланк — твоё место для честных ответов. Распечатай его, налей себе чаю и найди тихий уголок. Пиши от руки, не торопясь и без черновиков: рука часто знает больше, чем мы успеваем подумать. Здесь нет правильных ответов, и никто, кроме тебя, их не прочитает.</p>\n    <p class=\"note\">Вопросы взяты из твоего разбора. Если на какой-то вопрос сейчас нет ответа, оставь его и вернись позже. Пустая строка — тоже ответ.</p></div>` });\n  let n = 0;\n  WS.sections.forEach(s => s.qs.forEach((q, i) => {\n    n++;\n    B.push({ html: `<div class=\"blk ws ws-q\">${i === 0 ? `<div class=\"ws-sec\"><h2>${s.title}</h2>${s.note ? `<p class=\"note\">${s.note}</p>` : ''}</div>` : ''}\n      <div class=\"ws-row\"><span class=\"ws-n\">${n}</span><div><p class=\"ws-qt\">${q}</p>${wsLines(s.lines)}</div></div></div>` });\n  }));\n  const goalQ = pair\n    ? ['Какими мы хотим быть друг с другом через три месяца?', 'По каким маленьким признакам мы заметим, что движемся?', 'Что может нас остановить, и что мы сделаем тогда?']\n    : ['Чего я хочу для себя через три месяца? Опиши так, будто это уже случилось.', 'По каким маленьким признакам я пойму, что двигаюсь?', 'Что может меня остановить, и что я сделаю тогда?'];\n  goalQ.forEach((q, i) => { n++; B.push({ html: `<div class=\"blk ws ws-q\">${i === 0 ? `<div class=\"ws-sec\"><h2>${pair ? 'Наша цель' : 'Моя цель'}</h2><p class=\"note\">Цель, записанная своей рукой, становится ближе.</p></div>` : ''}\n    <div class=\"ws-row\"><span class=\"ws-n\">${n}</span><div><p class=\"ws-qt\">${q}</p>${wsLines(5)}</div></div></div>` }); });\n  if (WS.steps.length) B.push({ newPage: true, html: `<div class=\"blk ws ws-plan\"><div class=\"ws-sec\"><h2>Мои шаги на 4 недели</h2><p class=\"note\">Шаги из разбора. Отмечай каждую неделю, что получилось и что ты замечаешь. Маленькие победы тоже считаются.</p></div>\n    <div class=\"ws-steps\">${WS.steps.map(t => `<p><span class=\"ws-box\"></span>${t}</p>`).join('')}</div>\n    <div class=\"ws-weeks\">${[1,2,3,4].map(w => `<div><b>Неделя ${w}</b><small>Что получилось</small>${wsLines(3)}<small>Что я замечаю</small>${wsLines(2)}</div>`).join('')}</div></div>` });\n  B.push({ html: `<div class=\"blk ws ws-q\"><div class=\"ws-sec\"><h2>Через 4 недели</h2><p class=\"note\">Перечитай всё, что написано выше, и ответь ещё на три вопроса.</p></div>\n    ${['Что изменилось за это время?', (pair ? 'Что оказалось самым трудным, а что далось легче, чем мы думали?' : 'Что оказалось самым трудным, а что далось легче, чем я думала?'), (pair ? 'Что мы хотим взять с собой дальше?' : 'Что я хочу взять с собой дальше?')].map(q => `<p class=\"ws-qt\">${q}</p>${wsLines(4)}`).join('')}</div>` });\n  B.push({ html: `<div class=\"blk ws ws-end\"><p>Когда закончишь, пройди тест ещё раз и сравни разборы. А если захочется обсудить написанное с живым человеком, приходи на встречу-знакомство: 30 минут онлайн, бесплатно. Мы познакомимся, проговорим твой запрос и поймём, насколько я могу быть тебе полезна. Чтобы записаться, напиши мне слово «ВСТРЕЧА».</p><p class=\"ws-sign\">${AUTHOR.name}</p></div>` });\n  return B;\n}\nfunction wsNoteHtml(){\n  const url = (typeof SITE_URL !== 'undefined' && SITE_URL ? SITE_URL.replace(/\\/?$/, '/') : '') + (TEST_META.id === 'stupeni' ? 'stupeni/' : TEST_META.id + '/');\n  return `<div class=\"blk ws-note\"><div class=\"eyebrow\">Бланк для записей</div><h3>Ответь на вопросы своей рукой</h3>\n    <p>К этому разбору есть отдельный файл — бланк для записей. В нём все вопросы и шаги из разбора с линиями для ответов. Распечатай его и пиши от руки, не торопясь: так ответы становятся честнее, а шаги ближе.</p>\n    <p class=\"note\">${window.__PDF ? `Бланк скачивается вместе с этим разбором, поищи его в папке «Загрузки». Если его там нет, открой тест на <a href=\"${url}\">сайте</a>, открой свой разбор, и под формой будет кнопка «Скачать бланк».` : 'Бланк скачается вместе с PDF-разбором через форму ниже.'}</p></div>`;\n}\n", "/* =====================================================================\n   Данные и конфиденциальность — общее для всех тестов (с 02.10.2026).\n   - Ответы тестов хранятся только в браузере человека и через 90 дней удаляются сами.\n   - Кнопка «Удалить мои ответы».\n   - Страна спрашивается в мини-опросе (раньше — в анкете перед PDF).\n   - Ссылки на Политику конфиденциальности и Выходные данные в подвале.\n   Тексты на четырёх языках — здесь же (PRIV). Подключается после brand.js, до теста.\n   ===================================================================== */\nconst PAGE_LANG = (typeof LANG !== 'undefined') ? LANG : 'ru';\nconst DATA_DAYS = 90;\n\n/* Страны — коды ISO; названия показываются на языке страницы, в таблицу уходит русское название. */\nconst COUNTRY_TOP = ['CH','DE','AT','FR','IT','ES','NL','BE','GB','PL','CZ','IL','US','CA','UA','RU','BY','KZ'];\nconst COUNTRY_ALL = ['AU','AT','AZ','AL','DZ','AD','AR','AM','AF','BD','BH','BY','BE','BG','BO','BA','BR','GB','HU','VE','VN','GH','DE','HK','GR','GE','DK','DO','EG','IL','IN','ID','JO','IQ','IR','IE','IS','ES','IT','KZ','KH','CA','QA','KE','CY','KG','CN','CO','CR','CU','KW','LV','LB','LT','LI','LU','MU','MY','MV','MT','MA','MX','MD','MC','MN','ME','NP','NG','NL','NZ','NO','AE','OM','PK','PA','PY','PE','PL','PT','RU','RO','SA','MK','RS','SG','SK','SI','US','TJ','TH','TW','TN','TM','TR','UG','UZ','UA','UY','PH','FI','FR','HR','CZ','CL','CH','SE','LK','EC','EE','ZA','KR','JM','JP'];\nconst countryName = (() => { try { const d = new Intl.DisplayNames([PAGE_LANG], { type:'region' }); return c => d.of(c); } catch(e){ return c => c; } })();\nconst countryRu = (() => { try { const d = new Intl.DisplayNames(['ru'], { type:'region' }); return c => d.of(c); } catch(e){ return c => c; } })();\nconst COUNTRIES = COUNTRY_ALL.map(countryRu);\nconst OTHER_COUNTRY = 'Другая страна';\n\nconst PRIV_ALL = {\n  ru: {\n    countryQ: 'Где ты сейчас живёшь?', countryPick: 'Выбери страну', countryTop: 'Часто выбирают', countryAll: 'Все страны', countryOther: 'Другая страна',\n    countryErr: 'Выбери, пожалуйста, страну, в которой ты сейчас живёшь.',\n    countryNote: 'Страна нужна, чтобы показать в разборе подходящее приглашение и полезные ссылки.',\n    privacy: 'Политика конфиденциальности', impressum: 'Выходные данные',\n    onlyYou: 'Твои ответы остаются только у тебя. Я их не вижу.',\n    keepUntil: d => `Твои ответы и разбор хранятся только на этом устройстве, до ${d}. Потом они удалятся сами. Скачай PDF, если хочешь сохранить разбор.`,\n    del: 'Удалить мои ответы', delAsk: 'Удалить все ответы этого теста с этого устройства? Разбор тоже исчезнет. Если хочешь его сохранить, сначала скачай PDF.',\n    delYes: 'Да, удалить', delNo: 'Отмена', delDone: 'Ответы удалены с этого устройства.'\n  },\n  uk: {\n    countryQ: 'Де ти зараз живеш?', countryPick: 'Обери країну', countryTop: 'Часто обирають', countryAll: 'Усі країни', countryOther: 'Інша країна',\n    countryErr: 'Обери, будь ласка, країну, у якій ти зараз живеш.',\n    countryNote: 'Країна потрібна, щоб показати в розборі відповідне запрошення та корисні посилання.',\n    privacy: 'Політика конфіденційності', impressum: 'Вихідні дані',\n    onlyYou: 'Твої відповіді залишаються тільки в тебе. Я їх не бачу.',\n    keepUntil: d => `Твої відповіді та розбір зберігаються тільки на цьому пристрої, до ${d}. Потім вони видаляться самі. Завантаж PDF, якщо хочеш зберегти розбір.`,\n    del: 'Видалити мої відповіді', delAsk: 'Видалити всі відповіді цього тесту з цього пристрою? Розбір теж зникне. Якщо хочеш його зберегти, спочатку завантаж PDF.',\n    delYes: 'Так, видалити', delNo: 'Скасувати', delDone: 'Відповіді видалено з цього пристрою.'\n  },\n  de: {\n    countryQ: 'Wo lebst du zurzeit?', countryPick: 'Wähle ein Land', countryTop: 'Häufig gewählt', countryAll: 'Alle Länder', countryOther: 'Anderes Land',\n    countryErr: 'Wähle bitte das Land, in dem du zurzeit lebst.',\n    countryNote: 'Das Land brauche ich, um dir in der Auswertung die passende Einladung und hilfreiche Links zu zeigen.',\n    privacy: 'Datenschutzerklärung', impressum: 'Impressum',\n    onlyYou: 'Deine Antworten bleiben nur bei dir. Ich sehe sie nicht.',\n    keepUntil: d => `Deine Antworten und die Auswertung sind nur auf diesem Gerät gespeichert, bis ${d}. Danach werden sie automatisch gelöscht. Lade das PDF herunter, wenn du die Auswertung behalten möchtest.`,\n    del: 'Meine Antworten löschen', delAsk: 'Alle Antworten dieses Tests von diesem Gerät löschen? Auch die Auswertung verschwindet. Wenn du sie behalten möchtest, lade zuerst das PDF herunter.',\n    delYes: 'Ja, löschen', delNo: 'Abbrechen', delDone: 'Die Antworten wurden von diesem Gerät gelöscht.'\n  },\n  en: {\n    countryQ: 'Where do you live now?', countryPick: 'Choose a country', countryTop: 'Frequently chosen', countryAll: 'All countries', countryOther: 'Other country',\n    countryErr: 'Please choose the country where you live now.',\n    countryNote: 'I need the country to show you the right invitation and useful links in your results.',\n    privacy: 'Privacy policy', impressum: 'Legal notice',\n    onlyYou: 'Your answers stay with you only. I cannot see them.',\n    keepUntil: d => `Your answers and results are stored only on this device, until ${d}. After that they are deleted automatically. Download the PDF if you want to keep your results.`,\n    del: 'Delete my answers', delAsk: 'Delete all answers to this test from this device? Your results will disappear too. If you want to keep them, download the PDF first.',\n    delYes: 'Yes, delete', delNo: 'Cancel', delDone: 'Your answers have been deleted from this device.'\n  }\n};\nconst PRIV = PRIV_ALL[PAGE_LANG] || PRIV_ALL.ru;\n\n/* ---------- 1. Автоудаление ответов через 90 дней ---------- */\n(function purge(){\n  try {\n    const limit = Date.now() - DATA_DAYS * 864e5;\n    for (let i = localStorage.length - 1; i >= 0; i--){\n      const k = localStorage.key(i);\n      if (!k || !/^irinaTests\\./.test(k)) continue;\n      let v = null; try { v = JSON.parse(localStorage.getItem(k) || 'null'); } catch(e){}\n      const t = v && (v.t || v.startedAt);\n      if (!t || t < limit) localStorage.removeItem(k);\n    }\n    localStorage.removeItem('irinaTestsLead');   // прежняя анкета (с e-mail) больше не хранится\n  } catch(e){}\n})();\n\n/* ключ сохранённых ответов текущего теста */\nfunction answersKey(){ return (typeof TEST_META !== 'undefined') ? 'irinaTests.' + TEST_META.id + '.v1' : ''; }\nfunction answersSavedAt(){ try { const v = JSON.parse(localStorage.getItem(answersKey()) || 'null'); return v ? (v.t || v.startedAt || 0) : 0; } catch(e){ return 0; } }\nfunction retentionLine(){\n  const t = answersSavedAt() || Date.now();\n  const d = new Date(t + DATA_DAYS * 864e5).toLocaleDateString(typeof DATE_LOCALE !== 'undefined' ? DATE_LOCALE : 'ru-RU', { day:'2-digit', month:'2-digit', year:'numeric' });\n  return PRIV.keepUntil(d);\n}\n\n/* ---------- 2. Страна в мини-опросе ---------- */\nconst COUNTRY_KEY = 'irinaTestsCountry';\nfunction surveyCountry(){\n  const s = document.getElementById('svCountry');\n  if (s && s.value) return s.value;\n  try { return localStorage.getItem(COUNTRY_KEY) || ''; } catch(e){ return ''; }\n}\n// Тесты раньше брали страну из анкеты (window.__leadCountry). Теперь она всегда берётся из мини-опроса.\ntry { Object.defineProperty(window, '__leadCountry', { configurable: true, get: surveyCountry, set: () => {} }); } catch(e){}\n\nfunction countrySelectHtml(id){\n  return `<select id=\"${id}\"><option value=\"\">${PRIV.countryPick}</option></select>`;\n}\nfunction fillCountrySelect(sel, value){\n  if (!sel || sel.options.length > 1) return;\n  const g1 = document.createElement('optgroup'); g1.label = PRIV.countryTop;\n  COUNTRY_TOP.forEach(c => g1.appendChild(new Option(countryName(c), countryRu(c))));\n  const g2 = document.createElement('optgroup'); g2.label = PRIV.countryAll;\n  COUNTRY_ALL.map(c => [countryName(c), countryRu(c)]).sort((x, y) => x[0].localeCompare(y[0], PAGE_LANG)).forEach(([n, v]) => g2.appendChild(new Option(n, v)));\n  g2.appendChild(new Option(PRIV.countryOther, OTHER_COUNTRY));\n  sel.appendChild(g1); sel.appendChild(g2);\n  if (value && (COUNTRIES.includes(value) || value === OTHER_COUNTRY)) sel.value = value;\n}\n(function surveyCountryField(){\n  const box = document.querySelector('[data-greeting] .surveys'); if (!box || document.getElementById('svCountry')) return;\n  const fs = document.createElement('fieldset'); fs.className = 'survey sv-country';\n  fs.innerHTML = `<legend>${PRIV.countryQ} *</legend>${countrySelectHtml('svCountry')}<p class=\"note\">${PRIV.countryNote}</p>`;\n  box.appendChild(fs);\n  let saved = ''; try { saved = localStorage.getItem(COUNTRY_KEY) || ''; } catch(e){}\n  const sel = fs.querySelector('select'); fillCountrySelect(sel, saved);\n  sel.addEventListener('change', () => { try { localStorage.setItem(COUNTRY_KEY, sel.value); } catch(e){} });\n  // без страны тест не открывается (проверка срабатывает раньше общей кнопки «Перейти к тестированию»)\n  document.addEventListener('click', ev => {\n    const go = ev.target.closest && ev.target.closest('#svGo'); if (!go) return;\n    const a = (typeof surveyAnswers === 'function') ? surveyAnswers() : { heard: [1], interest: [1] };\n    if (!a.heard.length || !a.interest.length) return;          // об этих вопросах скажет общая проверка\n    if (!sel.value){\n      ev.stopPropagation(); ev.preventDefault();\n      const err = document.getElementById('svErr'); if (err){ err.textContent = PRIV.countryErr; err.hidden = false; }\n      sel.focus();\n    } else { try { localStorage.setItem(COUNTRY_KEY, sel.value); } catch(e){} }\n  }, true);\n})();\n\n/* ---------- 3. Удалить мои ответы ---------- */\nfunction deleteAnswersHtml(){\n  if (!answersKey()) return '';\n  return `<div class=\"del-answers\"><button type=\"button\" class=\"linkbtn\" data-del-answers>${PRIV.del}</button>\n    <div class=\"del-ask\" hidden><p>${PRIV.delAsk}</p><div class=\"row\"><button type=\"button\" class=\"btn small\" data-del-yes>${PRIV.delYes}</button><button type=\"button\" class=\"btn ghost small\" data-del-no>${PRIV.delNo}</button></div></div>\n    <p class=\"note del-done\" hidden>${PRIV.delDone}</p></div>`;\n}\ndocument.addEventListener('click', ev => {\n  const b = ev.target.closest && ev.target.closest('[data-del-answers],[data-del-yes],[data-del-no]'); if (!b) return;\n  const box = b.closest('.del-answers'), ask = box.querySelector('.del-ask');\n  if (b.hasAttribute('data-del-answers')){ ask.hidden = !ask.hidden; return; }\n  if (b.hasAttribute('data-del-no')){ ask.hidden = true; return; }\n  try {\n    const pre = 'irinaTests.' + TEST_META.id + '.';\n    for (let i = localStorage.length - 1; i >= 0; i--){ const k = localStorage.key(i); if (k && k.indexOf(pre) === 0) localStorage.removeItem(k); }\n  } catch(e){}\n  ask.hidden = true; box.querySelector('.del-done').hidden = false;\n  setTimeout(() => { location.hash = ''; location.reload(); }, 900);\n});\n\n/* ---------- 4. Подвал: правовые ссылки и удаление ответов ---------- */\nfunction legalUrl(page){\n  const root = (typeof SITE_BASE !== 'undefined') ? SITE_BASE : '../';\n  return root + page + '/';\n}\nfunction privacyLinksHtml(){\n  return `<a href=\"${legalUrl('privacy')}\">${PRIV.privacy}</a> · <a href=\"${legalUrl('impressum')}\">${PRIV.impressum}</a>`;\n}\n(function footer(){\n  const f = document.querySelector('.wrap .copy'); if (!f || f.querySelector('.legal-links')) return;\n  const p = document.createElement('span'); p.className = 'legal-links'; p.innerHTML = privacyLinksHtml();\n  f.appendChild(document.createElement('br')); f.appendChild(p);\n  if (answersKey() && document.getElementById('intro')){\n    const d = document.createElement('div'); d.innerHTML = deleteAnswersHtml(); f.appendChild(d.firstElementChild);\n  }\n})();\n/* строка «Твои ответы остаются только у тебя» на стартовой странице, рядом с кнопкой начала */\n(function startNote(){\n  const host = document.querySelector('#testStart [data-share=\"compact\"]'); if (!host || document.querySelector('.only-you')) return;\n  const p = document.createElement('p'); p.className = 'note only-you';\n  p.innerHTML = `${PRIV.onlyYou} <a href=\"${legalUrl('privacy')}\">${PRIV.privacy}</a>`;\n  host.parentNode.insertBefore(p, host);\n})();\n", "/* СГЕНЕРИРОВАНО из «Вход 1 — Путеводитель по уровням.md» скриптом tools/guide2js.py — правки вносить в md */\nconst GUIDE = {\n \"introTitle\": \"Дом, который строится заново\",\n \"intro\": \"<p>Представь: ты переехала. Чемоданы распакованы, документы поданы, у детей новая школа. А вместе с городом и квартирой ты оставила на старом месте весь свой дом. Не стены, а то невидимое, что держало тебя годами. Привычный ритм дня. Людей, которым можно позвонить ночью. Язык, на котором ты шутишь. Понятные правила. Работу, за которую тебя уважали. И тихое чувство «это моя жизнь».</p><p>На новом месте этот невидимый дом приходится строить заново. И строится он так же, как любой настоящий дом, снизу вверх. Сначала земля, на которой можно стоять. Потом очаг. Потом стены, окна, крыша. Никто не начинает с крыши: она просто не удержится.</p><p>Больше полувека назад американский психолог Клэр Грейвз много лет задавал разным людям один вопрос: «Что для тебя хорошая жизнь?» Ответы оказались похожи на лестницу. У каждого человека есть ступени, и каждая следующая вырастает из предыдущей. Позже его ученики назвали это спиральной динамикой и дали каждой ступени свой цвет. Звучит по-научному, а на деле всё очень по-человечески. Это карта того, что нужно человеку, чтобы жить, а не выживать.</p><p>Ступени не оценки. Нижняя не хуже верхней, так же как фундамент не хуже крыши. Когда холодно, правильно думать о тепле, а не о смысле жизни. Нижние держат верхние: если одна ступенька шатается, стоять выше трудно, сколько бы сил ты ни прикладывала. Поэтому начинать всегда стоит с самой нижней, которая поскрипывает.</p><p>Переезд почти всех сдвигает вниз. Дома ты могла уверенно стоять высоко, а здесь одним движением выбиты нижние ступени, и ты снова учишься спать, находить своих, говорить, разбираться в правилах. Это не откат и не слабость. Это цена переезда, которую платят все. И ещё одно: поднявшись, ты не выбрасываешь нижние ступени, ты на них стоишь. Сон и свои люди нужны и той, кто уже на самом верху.</p><p>Грейвз заметил ещё одну важную вещь: ступени — это ответ на условия жизни. Когда условия меняются, человеку приходится заново искать опору, и это нормально. Именно поэтому переезд так сильно встряхивает: условия поменялись разом все.</p><p>А его ученики Дон Бек и Кристофер Кован описали, как люди вообще меняются. Не по прямой, а по кругу. Сначала равновесие: жизнь и то, что тебе нужно, совпадают. Потом смутное беспокойство: что-то не так, но непонятно что. Потом тупик: уже ясно, что не так, но кажется, что выхода нет, и от этого злость и бессилие. Потом сдвиг: барьер назван, появляется другой путь, и вдруг становится легко. И наконец новое равновесие, уже на ступень выше. Каждое из этих состояний нормально. Важно не застрять ни в одном из них.</p><p>Бек и Кован заметили и то, что для перемены нужны условия. Нужны силы, а их нет, пока не решены нижние вопросы. Нужно ощущение «так больше не хочу». Нужна ясность, что именно не так и куда можно пойти. Нужно назвать барьер по имени. И нужна поддержка рядом, пока новое ещё непривычно. Если чего-то из этого нет, человек стоит на месте, даже если очень старается. Тест поможет увидеть, что из этого есть у тебя, а чего пока не хватает.</p><p>Читай снизу вверх, не торопясь. Где-то ты узнаешь себя сразу, где-то улыбнёшься: «это было со мной в первый год». В конце каждой ступени тебя ждут пять вопросов. Возьми ручку и ответь письменно: пять минут честности с собой иногда дают больше, чем месяц размышлений.</p><blockquote><p>Это не оценка и не проверка «нормальная ли я». Это карта. Она не говорит, какая ты, — она показывает, что тебе сейчас нужно.</p></blockquote>\",\n \"levels\": [\n  {\n   \"n\": 1,\n   \"name\": \"Земля под ногами\",\n   \"color\": \"Бежевый\",\n   \"sub\": \"ступень тела\",\n   \"teaser\": \"Когда главное — просто устоять на ногах\",\n   \"note\": \"\",\n   \"body\": \"<p>Помнишь, как сходишь на берег после долгого плавания? Земля ещё качается, ноги ватные, и пока ты не постоишь, не попьёшь воды и не выспишься, никакие красоты нового берега не радуют. С этой ступени начинается всё: просто устоять.</p><p>Это ступень тела. Сон, еда, тепло, крыша над головой и простое чувство, что завтра ничего не рухнет. Здесь нет больших планов, есть тело, которому нужно восстановиться. Взрослый человек возвращается сюда каждый раз, когда сил становится меньше, чем требует жизнь: болезнь, рождение ребёнка, горе. И переезд.</p><p>Дома почти всё шло само. Ты не думала, как дойти до магазина, что сказать в аптеке, где здесь выключатель. На новом месте ничего не идёт само. Каждое действие превращается в маленький экзамен: прочитать, понять, переспросить, догадаться. Голова весь день стоит на посту, как сторож, и к вечеру сил не остаётся совсем, хотя «ничего особенного не сделала». Это не лень. Это счёт, который тело выставляет за то, что все привычки пришлось перезагрузить разом.</p><blockquote><p>«Засыпаю под телефон и просыпаюсь в четыре утра». «Голова и спина болят, а врачи говорят, что всё в порядке». «Днём забываю поесть, а вечером заедаю». «Что будет через полгода? Посмотрим». «Хочется только, чтобы все легли и стало тихо».</p></blockquote><p>Бывает, что земли под ногами правда нет: жильё временное, денег мало, документы решают другие, и непонятно, что будет после следующего продления. Так часто бывает у тех, кто уехал от войны, и здесь первыми должны помочь социальные службы, а моя работа идёт рядом и чуть позже. А бывает наоборот: квартира, страховка и деньги в порядке, а ты не спишь и всё время как натянутая струна. Снаружи благополучие, внутри ватные ноги.</p><p>Когда эта ступень крепкая, ты просыпаешься с силами и ешь не на бегу. У тебя есть свой угол, где можно закрыть дверь и выдохнуть. Ты примерно знаешь, что будет в ближайшие месяцы, и этого достаточно, чтобы отпустить плечи.</p><p>Подарок бежевой ступени в том, что она учит слышать тело и беречь силы. Тот, кто прошёл её бережно, больше не путает усталость с ленью и умеет сказать себе: «Сегодня я сделала достаточно». А подвох в том, что из режима выживания можно забыть выйти. Опасность давно прошла, а ты всё экономишь на еде и откладываешь врача «на всякий случай». Или не разрешаешь себе отдохнуть, пока всё не устроено, а устроено не бывает никогда.</p><p>Подниматься отсюда помогает не подвиг, а ритм. Ложиться в одно и то же время. Утром постоять десять минут на свету. Сделать один уголок в доме своим: повесить что-то любимое, поставить чашку, которая радует. Нарисовать маленький горизонт из трёх колонок: что я знаю точно, что решится к какой-то дате, что от меня не зависит. Когда тело немного отдохнёт, появятся силы на людей, и ты сама шагнёшь выше.</p>\",\n   \"ask\": \"<ol class=\\\"clean\\\"><li>Когда я последний раз проснулась по-настоящему отдохнувшей?</li><li>Где в моём доме место, которое только моё?</li><li>Что я точно знаю о ближайших шести месяцах? А что от меня не зависит — и можно ли это отпустить?</li><li>Что я откладываю «на потом» для своего тела?</li><li>Кому я могу сказать: «мне сейчас тяжело»?</li></ol>\"\n  },\n  {\n   \"n\": 2,\n   \"name\": \"Очаг и свои за столом\",\n   \"color\": \"Фиолетовый\",\n   \"sub\": \"ступень «мы»\",\n   \"teaser\": \"Когда хочется, чтобы кто-то ждал тебя вечером\",\n   \"note\": \"\",\n   \"body\": \"<p>Вечер. Горит огонь, за столом сидят свои. Можно говорить на родном языке, смеяться над старыми шутками и молчать, ничего не объясняя. Тебя здесь знают, ждут и заметят, если ты не придёшь.</p><p>Человек существо стайное: в одиночку он не выживает ни в лесу, ни в чужой стране. Вторая ступень про принадлежность. Про своих людей, семью, корни, праздники, про то самое тёплое «мы». Здесь ты сильна не сама по себе, а тем, что ты с кем-то.</p><p>Дома круг собирался сам, годами: двор, школа, институт, работа. Здесь его никто не передаст по наследству. Его приходится строить заново, взрослой, когда времени мало, а первый шаг почему-то даётся так трудно. И язык не помогает: дружба начинается с болтовни ни о чём, о погоде и смешном случае в автобусе, а именно эту лёгкость чужой язык пока не даёт. А ещё появляется странное чувство «между»: дома ты уже немного чужая, а здесь ещё не своя.</p><blockquote><p>«Есть кому написать „как дела“, но некому сказать „мне плохо“». «Знакомых много, но все по обстоятельствам». «Праздники — самое тяжёлое». «Стыдно признаться, что одиноко: у нас же всё хорошо».</p></blockquote><p>К русскоязычным сообществам при этом подходить бывает боязно: споры, сравнения, разговоры о том, кто как устроился. И ты остаёшься где-то посередине, среди людей, но без своих.</p><p>Когда эта ступень крепкая, у тебя есть хотя бы один человек, которому можно позвонить поздно вечером. Есть место или компания, где тебе рады. Твои праздники живут и здесь, а связь с родными тёплая и живая.</p><p>Подарок фиолетовой ступени — тепло и защита. За твоей спиной свои. Эта ступень хранит язык, кухню, сказки и песни, всё то, что потом передаётся детям, и без неё любой успех кажется пустым. Подвох в том, что очаг может превратиться в крепость. Можно закрыться в своих и не выходить к местным: «они холодные, мы другие». Можно держаться за круг, который давно не греет, потому что страшно остаться совсем одной. Или молчать о себе, лишь бы тебя не выгнали из стаи.</p><p>Разжигать этот огонь помогает не смелость и не обаяние, а повторение. Одни и те же люди, в одно и то же время, каждую неделю. Знакомство становится знакомством со второй встречи, поэтому позвать снова не значит навязываться. Когда рядом появится хотя бы один свой человек, у тебя вырастет опора, чтобы начать действовать самой.</p>\",\n   \"ask\": \"<ol class=\\\"clean\\\"><li>Кому я позвоню, если сегодня ночью мне станет плохо?</li><li>Где за последний месяц я была «просто так», не по делу?</li><li>Какие наши традиции живут в моём доме здесь? Какие я потеряла — и хочу ли вернуть?</li><li>С кем мне недавно было тепло? Позвала ли я её снова?</li><li>Чего я боюсь, когда думаю о том, чтобы позвать кого-то первой?</li></ol>\"\n  },\n  {\n   \"n\": 3,\n   \"name\": \"Свой голос\",\n   \"color\": \"Красный\",\n   \"sub\": \"ступень силы\",\n   \"teaser\": \"Когда хочется снова почувствовать: «я могу»\",\n   \"note\": \"\",\n   \"body\": \"<p>Это дверь, которую ты открываешь сама. Без мужа рядом, без подруги-переводчицы, без ребёнка, который «скажет лучше». Ты заходишь и говоришь, может быть с ошибками и с дрожью в голосе, а выходишь с решённым делом. И внутри звучит: «Я смогла».</p><p>Третья ступень про силу, смелость и право голоса. Здесь человек выпрямляется и говорит: «я хочу», «я могу», «нет, так со мной нельзя». Крепкий голос — это не громкость и не скандалы. Это спокойное «нет» без оправданий и уверенность, что справишься, даже если будет неловко.</p><p>Чужой язык отнимает не слова, он отнимает взрослость. Женщина, у которой дома спрашивали совета, которая решала и вела за собой, здесь вдруг становится той, «которая не поняла». С ней говорят медленно и громко, как с ребёнком, а простые вещи за неё решают другие. И каждый раз, когда она промолчала, внутри откладывается маленький камешек: «я не могу». Камешков становится всё больше. Дома голос тоже стихает: «деньги не мои, значит, и требовать я не вправе».</p><blockquote><p>«Пишу сообщение, хотя быстрее позвонить, — лишь бы не говорить». «Прошу мужа записать меня к врачу». «Меня обсчитали, а я промолчала, и потом весь вечер прокручивала, что надо было сказать». «Злюсь на детей — на тех, кто не ответит».</p></blockquote><p>Когда эта ступень крепкая, ты сама звонишь, записываешься, спрашиваешь и возражаешь. Дома говоришь, что тебе нужно, и тебя слышат. Неловкость бывает, но она тебя больше не останавливает.</p><p>Подарок красной ступени — чувство «я есть». Смелость начинать, энергия рисковать, сила защищать своё и своих. Без неё не будет ни работы, ни своего дела, ни уважения: ни чужого, ни своего собственного. Подвох в том, что силу легко потерять в обе стороны. Можно перегнуть: резкость, ссоры, «я всем покажу», постоянная оборона, в которой выгораешь. А можно спрятать её совсем: снаружи улыбка и «ничего страшного», а внутри сдавленный гнев.</p><p>Голос возвращается маленькими шагами. Одно действие в день на чужом языке: поздороваться, спросить цену, позвонить. Одна фраза, которая возвращает взрослость: не «простите, мой немецкий плохой», а «говорите, пожалуйста, медленнее». И колонка «я смогла», куда ты записываешь каждую победу. Через три недели там будет двадцать одно доказательство против «я не могу». А когда сила вернётся, захочется понять, как здесь всё устроено.</p>\",\n   \"ask\": \"<ol class=\\\"clean\\\"><li>Какие мои дела сейчас делают за меня другие? Какое из них я хочу вернуть себе первым?</li><li>Когда я последний раз промолчала, хотя хотела сказать? Что бы я сказала сейчас?</li><li>Что мне нужно дома — и говорю ли я об этом вслух?</li><li>На кого я злюсь «не туда»?</li><li>Какую маленькую победу я одержала на этой неделе?</li></ol>\"\n  },\n  {\n   \"n\": 4,\n   \"name\": \"Карта и ключи\",\n   \"color\": \"Синий\",\n   \"sub\": \"ступень порядка\",\n   \"teaser\": \"Когда каждое письмо в ящике заставляет сердце биться чаще\",\n   \"note\": \"\",\n   \"body\": \"<p>Ты в большом незнакомом здании. Много дверей, на каждой табличка на чужом языке, и за какой-то из них то, что тебе нужно. А теперь представь, что у тебя в руках карта этого здания и связка ключей с подписями. Ты всё так же в незнакомом месте, но тебе уже не страшно.</p><p>Четвёртая ступень про порядок, правила и надёжность. Человеку важно понимать, как устроен мир вокруг: кто за что отвечает, что правильно, что принято, куда идти с вопросом. Порядок снаружи дарит покой внутри.</p><p>Правила здесь есть, и их много. Но никто их не объясняет: считается, что ты выросла здесь и впитала их с молоком матери. Местный человек даже не знает, что он это знает, и на вопрос «а как это работает?» пожимает плечами: «ну, обычно…». А ошибка может стоить дорого: штраф, отказ, пропущенный срок. Неписаные правила ещё хитрее писаных. Как здороваться с соседями, можно ли стирать в воскресенье, что принести в гости.</p><blockquote><p>«Письмо из общины лежит нераспечатанным уже два дня». «Не знаю, куда идти: налоги, страховка, школа, диплом». «В двадцати чатах двадцать разных советов». «О пропущенном сроке узнала, когда было уже поздно».</p></blockquote><p>Когда эта ступень крепкая, письмо в ящике остаётся просто письмом. Ты знаешь, куда идти с вопросом, бумаги лежат по папкам, сроки под контролем. Ты понимаешь, как здесь принято, и почти не боишься ошибиться.</p><p>Подарок синей ступени — спокойствие и опора. Хаос новой страны превращается в систему, в которой можно жить. Ты становишься человеком, у которого всё под контролем, и к тебе начинают приходить за советом. Подвох в том, что порядок может окаменеть. Правила становятся важнее живых людей, включая тебя саму. Страх ошибки парализует: лучше ничего не делать, чем сделать не так. А мир делится на «правильно» и «неправильно», и в одну из этих колонок попадают то они, то мы.</p><p>Чтобы подняться, не нужно знать всё. Нужно навести порядок за один вечер. Одна страничка на холодильник о том, что делать с любым письмом. Несколько папок. Три кучки: срочно, может подождать, не моё. И один надёжный проводник вместо двадцати чатов. Когда правила станут понятными, внутри появится новый вопрос: «А где здесь моё место? Чем я буду заниматься?»</p>\",\n   \"ask\": \"<ol class=\\\"clean\\\"><li>Какое письмо или дело я откладываю, потому что страшно? Что худшее может случиться — и что я тогда сделаю?</li><li>Кто мой главный источник ответов? Можно ли ему доверять?</li><li>Какие здешние правила кажутся мне странными? А если понять, зачем они, — станет легче?</li><li>Где страх ошибиться мешает мне начать?</li><li>Что в моих бумагах можно привести в порядок за один вечер?</li></ol>\"\n  },\n  {\n   \"n\": 5,\n   \"name\": \"Своя мастерская\",\n   \"color\": \"Оранжевый\",\n   \"sub\": \"ступень дела\",\n   \"teaser\": \"Когда на вопрос «чем вы занимаетесь?» внутри всё сжимается\",\n   \"note\": \"\",\n   \"body\": \"<p>У тебя есть своя мастерская. Пусть маленькая, пусть пока в углу кухни. В ней лежат твои инструменты: всё, что ты умеешь и знаешь. Ты что-то делаешь, это кому-то нужно, за это платят. И когда тебя спрашивают «чем ты занимаешься?», ты с удовольствием открываешь дверь и показываешь.</p><p>Пятая ступень про дело, рост и свою цену. Здесь хочется состояться: найти занятие по силам и по душе, расти, зарабатывать и быть признанной за то, что умеешь. Правила тут уже не стены, а инструменты: как сделать лучше, как устроить по-своему.</p><p>Переезд обнуляет сразу три сбережения, которые ты копила годами. Профессиональное: диплом здесь не признают. Репутационное: никто не знает, чего ты стоишь. И человеческое: некому за тебя поручиться. Дома всё это собиралось двадцать лет, а здесь исчезло за один день. Зовут на работу ниже прежней или не зовут совсем. «У вас нет местного опыта», а откуда ему взяться? Своих денег нет, и каждая покупка для себя превращается в маленький внутренний торг.</p><blockquote><p>«Резюме уходят в тишину, а диплом лежит в ящике». «Идей много, а с чего начать, непонятно». «Смотрю на тех, кто устроился, и чувствую себя хуже». «Кажется, здесь я никто».</p></blockquote><p>Когда эта ступень крепкая, у тебя есть своё занятие: работа, дело или проект. Есть деньги, которые ты заработала сама, пусть небольшие. И ты знаешь, чего стоишь, независимо от должности.</p><p>Подарок оранжевой ступени — вкус роста и свободы. «Я могу выбирать, кем быть». Умения превращаются в дело, дело в деньги, а деньги в голос и независимость. Подвох в том, что можно начать ценить себя только за результат: нет должности, значит, нет меня. Начинается гонка и бесконечное сравнение, ведь всегда кто-то устроился лучше. А в этой гонке легко забыть про сон с первой ступени и про своих людей со второй.</p><p>Подниматься стоит не с поиска вакансий вслепую, а с того, чтобы заглянуть в свою мастерскую. Что я умею, не по диплому, а по жизни? Что из этого нужно здесь? Поговорить с пятью людьми вместо того, чтобы гадать. Выбрать одну дорожку по силам: работа, маленькое своё дело или проект на пробу. И получить первый франк за то, что умеешь: он важнее суммы. Когда своё дело появится, придёт новый вопрос: «А ради чего всё это?»</p>\",\n   \"ask\": \"<ol class=\\\"clean\\\"><li>За что мне чаще всего говорили «спасибо»? Что из этого нужно здесь?</li><li>Какая дорожка мне сейчас по силам — работа, своё маленькое дело или проект на пробу?</li><li>Что я отвечаю на «чем ты занимаешься?» — и что хочу отвечать через год?</li><li>Что для меня значат свои деньги — сумма или свобода?</li><li>С кем я себя сравниваю? Помогает ли мне это — или только ранит?</li></ol>\"\n  },\n  {\n   \"n\": 6,\n   \"name\": \"Сад для других\",\n   \"color\": \"Зелёный\",\n   \"sub\": \"ступень вклада\",\n   \"teaser\": \"Когда своё уже есть и хочется делиться\",\n   \"note\": \"\",\n   \"body\": \"<p>Ты вырастила свой сад и вдруг замечаешь, что тебе хочется делиться. Угостить яблоками соседей, дать саженец той, что только приехала, позвать людей посидеть в тени. Сад стал не только твоим, он греет других. Но хороший садовник знает: если раздать всю воду, сад засохнет.</p><p>Шестая ступень про людей, тепло и смысл. Когда своё уже есть, хочется, чтобы сделанное было нужно кому-то за пределами семьи: поделиться опытом, сделать что-то вместе, быть частью сообщества. Здесь важно не «кто первый», а «чтобы всем было хорошо».</p><p>Тот, кто сам прошёл трудный путь, очень хорошо понимает новеньких. Хочется помочь, подсказать, обнять, и это прекрасно. Но здесь прячется ловушка. Помогать другим — самый благородный способ не заниматься своей жизнью. Это даёт тепло и ощущение нужности и может длиться годами, а свой вопрос «а я-то куда иду?» так и остаётся без ответа. Если сад растёт там, где должна была стоять своя мастерская, это не вклад, а побег.</p><blockquote><p>«Помогаю всем подряд и бесплатно, а на своё сил не остаётся». «Опекаю каждую новенькую — помню, как было мне». «Брать деньги неловко: это же просто помощь». «Дело есть, всё получается, а радости нет».</p></blockquote><p>Когда эта ступень крепкая, есть то, что ты делаешь не только для себя, и ты понимаешь, ради чего. Ты отдаёшь по выбору и не опустошаешься, а твой вклад видят и ценят.</p><p>Подарок зелёной ступени — умение слышать, сочувствовать и собирать людей вместе. Отсюда приходят те, кто встречает новеньких, создаёт сообщества и делает чужую страну чуть теплее. Подвох — спасать всех и остаться с пустыми руками. Так бояться ссор, что любой разговор превращается в бесконечное «давайте всех выслушаем». Жить чужими жизнями вместо своей.</p><p>Чтобы подняться выше, стоит честно посчитать, кому и сколько ты отдаёшь и что получаешь взамен. Выбрать, кому хочешь отдавать: тем, кто идёт следом, коллегам по делу или тому, что останется после тебя. Научиться говорить «нет» и назвать первую цену за то, что делаешь хорошо. Когда отдача стоит на твоей собственной опоре, хочется увидеть всю свою жизнь целиком.</p>\",\n   \"ask\": \"<ol class=\\\"clean\\\"><li>Что я делаю здесь не только для себя и своей семьи?</li><li>Сколько часов в месяц я отдаю другим? А сколько — себе?</li><li>Кому именно я хочу быть полезной — и в какой форме?</li><li>Где я говорю «да», хотя хочу сказать «нет»?</li><li>Если моя помощь другим исчезнет — что останется моего?</li></ol>\"\n  },\n  {\n   \"n\": 7,\n   \"name\": \"Вид с холма\",\n   \"color\": \"Жёлтый\",\n   \"sub\": \"ступень целой жизни\",\n   \"teaser\": \"Когда живёшь здесь давно, а будто всё ещё на чемоданах\",\n   \"note\": \"\",\n   \"body\": \"<p>Ты долго шла по долине, по тропинкам и мостикам, и вот поднялась на холм. Отсюда видно всё сразу: откуда ты пришла, где ты сейчас, куда ведут дороги. Прежняя жизнь и нынешняя оказываются не двумя разными берегами, а одной долиной. И ты сама выбираешь, по какой тропе идти дальше.</p><p>Седьмая ступень про взгляд на жизнь целиком. Здесь человек перестаёт жить по чужим сценариям, «как надо» и «как у всех», и собирает своё: что важно мне, зачем, как. Он видит, что у каждой ступени своя правда, и берёт из каждой то, что ему нужно.</p><p>Решение уехать почти невозможно закрыть раз и навсегда. Оно всплывает при каждой трудности: «если бы мы не уехали, этого бы не было». И пока этот вопрос открыт, жизнь остаётся черновиком. А черновик не жалко: можно не покупать мебель, не вешать картины, не учить язык всерьёз. «Вот вернёмся», «вот выучу язык», «вот дети вырастут», а годы идут.</p><blockquote><p>«Я здесь уже много лет, а всё ещё на чемоданах». «В каждом кризисе снова думаю, правильно ли мы сделали». «„Там“ и „здесь“ никак не складываются в одно». «Оглядываюсь назад и вижу годы на паузе».</p></blockquote><p>Когда эта ступень крепкая, твоя жизнь перестаёт быть залом ожидания. Ты помирилась с решением уехать. Из «там» ты взяла то, что дорого, из «здесь» то, что стало твоим. Ты знаешь, как хочешь прожить ближайшие годы, и тебя это радует.</p><p>Подарок жёлтой ступени — свобода и взрослый взгляд. Тебе больше не нужно, чтобы кто-то сказал, как правильно. Подвох — всё понимать и ничего не выбирать, когда «одного правильного ответа нет» становится удобным поводом не решать. Или смотреть на свою жизнь со стороны, как зритель. Или взобраться на холм, перепрыгнув нижние ступени: широкий взгляд, а за спиной пустой холодильник и ни одного своего человека.</p><p>Чтобы подняться выше, закрой вопрос о переезде на бумаге: что я получила, что потеряла, за что заплатила бы снова, а за что нет. Допиши до конца историю «если бы мы не уехали», честно, по годам: пока она не дописана, она возвращается в каждый трудный день. И сделай одну вещь, которую откладывала до возвращения: повесь картину, купи красивую посуду. Когда своя жизнь собрана, взгляд сам поднимается выше неё.</p>\",\n   \"ask\": \"<ol class=\\\"clean\\\"><li>Что я откладываю «до возвращения» или «до лучших времён»?</li><li>Если бы мы не уехали — какой была бы моя жизнь через десять лет? Честно, до конца.</li><li>Что из «там» я хочу взять с собой навсегда? Что из «здесь» уже стало моим?</li><li>Если бы жизнь заканчивалась завтра — о чём бы я жалела?</li><li>Какой одной фразой я опишу каждый из следующих трёх лет?</li></ol>\"\n  },\n  {\n   \"n\": 8,\n   \"name\": \"Небо над домом\",\n   \"color\": \"Бирюзовый\",\n   \"sub\": \"ступень «больше меня»\",\n   \"teaser\": \"Когда «здесь» и «там» сливаются в одну жизнь\",\n   \"note\": \"Это не ступень, которую чинят, а горизонт, к которому дорастают. В тесте она открывается, только если все семь ступеней под тобой крепкие.\",\n   \"body\": \"<p>Дом построен. Ты выходишь на крышу и видишь небо, одно и то же над всеми странами. Река внизу течёт через границы, не спрашивая разрешения. И ты вдруг понимаешь: ты не «отсюда» и не «оттуда», ты просто живёшь. А дом, который ты построила, однажды станет приютом для тех, кто придёт после.</p><p>Восьмая ступень про целое и про связи. Человек чувствует себя частью чего-то большего, чем его собственная жизнь: людей, природы, дела, которое переживёт его. Ему не нужно ничего доказывать и ни с кем соревноваться. Забота о себе и забота о мире здесь становятся одним и тем же.</p><p>После переезда это звучит так: «я больше не живу „в эмиграции“, я просто живу». Вопрос «где моя настоящая жизнь» исчез сам собой. Ты не представительница своей страны и не гостья в чужой. Под тобой крепкие ступени: есть сон, свои люди, своё дело и то, что ты отдаёшь. Внутри тихо. И есть то, что ты делаешь для тех, кто придёт после тебя.</p><blockquote><p>«Я больше не делю жизнь на „здесь“ и „там“». «Хочу, чтобы после меня что-то осталось». «Мне интересны те, кто идёт следом».</p></blockquote><p>Здесь тоже бывает непросто. Прежний круг ты переросла, а новый ещё не нашла, и не с кем говорить на своём уровне. Прежние цели больше не зовут, а новые ещё не названы. И хочется, чтобы сделанное не закончилось вместе с тобой.</p><p>Подарок этой ступени — мудрость, тишина и щедрость, которая не истощает. Отсюда приходят наставницы, ведущие встреч и авторы, те, кто открывает двери другим.</p><p>И одно важное предупреждение. Фраза «я гражданка мира, мне везде дом» бывает правдой, а бывает обезболивающим. Если под ногами шатается земля, нет сил и сна, нет своих людей, эта красивая фраза помогает не чувствовать, что дома пока нигде. Проверка простая: у настоящего неба над домом есть сам дом. Если нижние ступени крепкие, «мне везде дом» — правда. Если нет, пора спуститься и укрепить фундамент. Это не стыдно. Это честно.</p>\",\n   \"ask\": \"<ol class=\\\"clean\\\"><li>Делю ли я ещё свою жизнь на «здесь» и «там»?</li><li>Что я делаю для тех, кто придёт после меня?</li><li>С кем я могу говорить о самом важном — на своём уровне?</li><li>Что я хочу оставить после себя?</li><li>Крепкие ли подо мной нижние ступени — сон, свои люди, своё дело?</li></ol>\"\n  }\n ],\n \"end\": \"<blockquote><p>Ты прошла по всем восьми ступеням, от земли под ногами до неба над домом. Наверняка на какой-то из них ты остановилась и подумала: «Это же про меня». А может, сразу на двух.</p><p>Узнать себя — первый шаг. Второй — проверить, какие ступени под тобой крепкие, а какая поскрипывает. Тест займёт около двадцати минут и покажет, с чего начать именно тебе.</p></blockquote>\",\n \"sources\": \"<p>Clare W. Graves. <i>The Never Ending Quest.</i> ECLET Publishing, 2005 — главный труд Клэра Грейвза о том, как люди понимают «хорошую жизнь».</p><p>Don E. Beck, Christopher C. Cowan. <i>Spiral Dynamics: Mastering Values, Leadership and Change.</i> Blackwell, 1996 — книга, в которой ступени получили цвета, а изменения описаны как переходы между состояниями.</p><p>Spiral Dynamics: состояния и условия изменений — spiral-dynamics.com/faq_change.htm</p><p>Jørgen Carling, Silje Vatne Pettersen. <i>Return Migration Intentions in the Integration–Transnationalism Matrix.</i> International Migration, 2014 — о том, что решение остаться или вернуться зависит от того, насколько сильны связи здесь и там.</p><p>Путеводитель описывает ступени простыми словами и в применении к жизни после переезда. Это авторская адаптация модели для самопознания, а не научная диагностика.</p>\"\n};\n", "/* =====================================================================\n   «Ступени устойчивости» — путеводитель + тест «7 ступеней устойчивости».\n   Тексты: «Вход 1 — Путеводитель по уровням.md» (→ guide.js) и\n           «Вход 2 — Тест 7 ступеней устойчивости.md» (вопросы и разбор ниже).\n   ===================================================================== */\n\n/* ---------- ступени: палитра «Акварель с контуром · свежая» ---------- */\nconst LV = [\n  { name: 'Земля под ногами', color: 'Бежевый',    short: 'тело',           fill: '#E2DCD0', line: '#8E8470', focus: 'вернуть себе силы и землю под ногами' },\n  { name: 'Очаг и свои',      color: 'Фиолетовый', short: '«мы»',           fill: '#C4BDEA', line: '#6A5FB8', focus: 'найти своих людей в новой стране' },\n  { name: 'Свой голос',       color: 'Красный',    short: 'сила',           fill: '#EEA9B3', line: '#C25468', focus: 'вернуть себе голос и уверенность' },\n  { name: 'Карта и ключи',    color: 'Синий',      short: 'порядок',        fill: '#A6C4F0', line: '#3F6FBF', focus: 'спокойно разобраться, как здесь всё устроено' },\n  { name: 'Своя мастерская',  color: 'Оранжевый',  short: 'дело',           fill: '#F2C6A8', line: '#C97E52', focus: 'найти своё дело и свою цену' },\n  { name: 'Сад для других',   color: 'Зелёный',    short: 'вклад',          fill: '#B0DCC0', line: '#4E9A70', focus: 'отдавать из избытка, а не до опустошения' },\n  { name: 'Вид с холма',      color: 'Жёлтый',     short: 'целая жизнь',    fill: '#EEE29E', line: '#A99A2E', focus: 'перестать жить на паузе и собрать свою жизнь целиком' },\n  { name: 'Небо над домом',   color: 'Бирюзовый',  short: '«больше меня»',  fill: '#9ADDE0', line: '#2894A0', focus: 'понять, что ты хочешь оставить после себя' }\n];\nconst mix = (a, b, t) => '#' + [1, 3, 5].map(i => Math.round(parseInt(a.substr(i, 2), 16) * (1 - t) + parseInt(b.substr(i, 2), 16) * t).toString(16).padStart(2, '0')).join('');\nLV.forEach(l => l.soft = mix(l.fill, '#FFFFFF', .55));\n\nconst GR = ['Чувствую', 'Делаю', 'Вокруг меня', 'Думаю'];\nconst GR_SUB = ['что у меня внутри', 'что я реально делаю', 'что есть снаружи', 'во что я верю'];\n\n/* g: 0 чувствую · 1 делаю · 2 вокруг меня · 3 думаю; r: обратная фраза (4 − ответ) */\nconst ITEMS = [\n  [ [0,'Я просыпаюсь утром с силами.'], [0,'К вечеру я так устаю, что хочется только тишины и чтобы никто не трогал.',1],\n    [1,'Я сплю достаточно и ложусь примерно в одно время.'], [1,'Я ем на бегу или заедаю усталость по вечерам.',1],\n    [2,'У меня есть место, где я могу закрыть дверь и выдохнуть.'], [2,'Жильё и деньги на самое необходимое у меня есть, и за них не страшно.'],\n    [3,'Я знаю, что будет в ближайшие месяцы, — хотя бы в общих чертах.'], [3,'Я не разрешаю себе отдыхать, пока всё не сделано.',1] ],\n  [ [0,'Здесь мне бывает по-настоящему тепло с людьми.'], [0,'Мне одиноко, даже когда вокруг люди.',1],\n    [1,'За последний месяц у меня была живая встреча — не по делу, а просто так.'], [1,'Я сама зову людей: на кофе, в гости, на прогулку.'],\n    [2,'Есть человек, которому я могу позвонить, когда мне плохо.'], [2,'Есть место или компания, где меня ждут и узнают.'],\n    [3,'Наши традиции и праздники живут в моём доме и здесь.'], [3,'Я чувствую себя чужой и здесь, и дома.',1] ],\n  [ [0,'Я чувствую себя взрослой и уверенной, когда решаю здесь свои дела.'], [0,'Мне стыдно и неловко, когда приходится говорить на чужом языке.',1],\n    [1,'Я сама записываюсь к врачу и решаю бытовые вопросы по телефону.'], [1,'Простые вопросы за меня решает муж, подруга или ребёнок.',1],\n    [2,'Дома я говорю, что мне нужно, — и меня слышат.'], [2,'Со мной говорят на равных, а не медленно и громко.'],\n    [3,'Если со мной поступили несправедливо, я говорю об этом вслух.'], [3,'Я имею право отказать и не оправдываться.'] ],\n  [ [0,'Письмо в почтовом ящике меня не пугает.'], [0,'Я боюсь сделать что-то не так и «попасть» — на штраф, отказ, пропущенный срок.',1],\n    [1,'Мои бумаги разложены, и я знаю, где что лежит.'], [1,'Непонятные письма я откладываю и открываю не сразу.',1],\n    [2,'У меня есть надёжный источник ответов — человек или служба, а не двадцать чатов.'], [2,'Я знаю, куда идти с вопросом про страховку, налоги, школу, жильё.'],\n    [3,'Я понимаю, как здесь принято себя вести.'], [3,'Я понимаю, зачем нужны здешние правила, даже если не со всеми согласна.'] ],\n  [ [0,'Я спокойно отвечаю, когда меня спрашивают, чем я занимаюсь.'], [0,'Когда смотрю на тех, кто устроился, я чувствую себя хуже.',1],\n    [1,'У меня есть своё занятие — работа, дело или проект, который я считаю своим.'], [1,'Я делаю шаги к своей цели в работе — учусь, ищу, пробую.'],\n    [2,'У меня есть деньги, которые я заработала сама, — пусть небольшие.'], [2,'Мой опыт и умения здесь кому-то нужны и ценятся.'],\n    [3,'Я знаю, чего стою, и это не зависит от должности.'], [3,'Мне кажется, что здесь я «никто».',1] ],\n  [ [0,'То, что я делаю, приносит мне радость, а не только результат.'], [0,'После помощи другим я часто чувствую себя опустошённой.',1],\n    [1,'Есть то, что я делаю здесь не только для себя и своей семьи.'], [1,'Я говорю «нет», когда просят слишком много.'],\n    [2,'Есть круг или дело, где я соавтор, а не гостья.'], [2,'Мой вклад замечают и ценят, а не говорят «ну ты же просто подсказала».'],\n    [3,'Я понимаю, ради чего делаю то, что делаю.'], [3,'Брать деньги за то, что я делаю хорошо, мне неудобно — «это же просто помощь».',1] ],\n  [ [0,'Я чувствую, что живу свою жизнь, а не жду, когда начнётся настоящая.'], [0,'Во мне как будто две половины — «там» и «здесь», — и они не складываются.',1],\n    [1,'Я делаю то, что раньше откладывала «до лучших времён» или «до возвращения».'], [1,'Я живу как на чемоданах: не обустраиваюсь до конца, «вдруг уедем».',1],\n    [2,'Мой дом здесь ощущается моим, а не временным.'], [2,'В моей жизни есть место и для того, что я взяла «оттуда», и для того, что нашла здесь.'],\n    [3,'Я помирилась с решением уехать — оно больше не переигрывается во мне.'], [3,'Я представляю, как хочу прожить ближайшие годы, — и это меня радует.'] ]\n];\nconst SKY = [ [0,'Внутри у меня тихо: мне не нужно никому ничего доказывать.'], [1,'Я делаю что-то для тех, кто придёт после меня.'],\n  [2,'Рядом есть люди, с которыми я говорю о самом важном.'], [3,'Я больше не делю свою жизнь на «здесь» и «там».'],\n  [3,'Я чувствую себя частью чего-то большего, чем моя жизнь.'], [3,'Прежние цели больше не зовут, а новые я пока не нашла.',1] ];\n\n/* ситуации: [ступень 0–7, текст]; каждая ступень встречается ровно 6 раз */\nconst SITS = [\n  ['Вечер пятницы, неделя была тяжёлой. Чего тебе хочется больше всего?', [[0,'Лечь пораньше, тишина, никого не видеть — просто восстановиться.'],[1,'Позвать своих, наготовить, поговорить на родном языке.'],[3,'Разобрать накопившиеся бумаги и спланировать следующую неделю — тогда отпустит.'],[5,'Встретиться с подругой и поговорить по душам о том, что на самом деле чувствую.']]],\n  ['Соседи зовут тебя на апéро во дворе.', [[1,'Пойду, если пойдёт кто-то из своих, — одной неуютно.'],[2,'Пойду и сама заговорю, даже с ошибками, — хватит прятаться.'],[4,'Пойду: это шанс познакомиться с полезными людьми.'],[6,'Пойду из любопытства — посмотреть, как они живут, и взять себе то, что откликается.']]],\n  ['В регистратуре с тобой говорят медленно, громко и свысока.', [[2,'Скажу прямо: «Говорите нормально, я понимаю». Не позволю.'],[3,'Спокойно попрошу объяснить письменно и уточню, как положено.'],[5,'Попробую понять человека — может, у него тяжёлый день; ссориться не хочу.'],[7,'Отмечу про себя и отпущу: это не про меня, просто эпизод.']]],\n  ['Тебе предлагают работу ниже твоей квалификации.', [[0,'Соглашусь, если это стабильный доход и спокойствие: сейчас не до амбиций.'],[3,'Сначала разберусь с условиями: договор, страховка, испытательный срок.'],[4,'Возьму как ступеньку — но с планом, как вырасти за год.'],[6,'Подумаю, как это ляжет в мою жизнь целиком, а не только в кошелёк.']]],\n  ['Знакомая недавно переехала и просит помочь освоиться.', [[1,'Позову её в нашу компанию — пусть у неё сразу будут свои.'],[4,'Дам чёткий план: что сделать в первый месяц и куда обратиться.'],[5,'Буду рядом, выслушаю, поддержу — по себе знаю, как это тяжело.'],[7,'Помогу — и подумаю, как сделать, чтобы этот опыт пригодился и тем, кто приедет следом.']]],\n  ['Вы с мужем не можете договориться, как провести отпуск и на что потратить деньги.', [[0,'Мне главное — отдохнуть и выспаться, остальное неважно.'],[2,'Скажу, чего хочу я, — сколько можно подстраиваться.'],[5,'Важно, чтобы всем было хорошо и никто не остался обиженным.'],[6,'Поищем вариант, который соединит разное, — одного правильного ответа нет.']]],\n  ['Ты вспоминаешь, как было «там», дома.', [[1,'Скучаю по своим, по праздникам и традициям — хочу сохранить это для детей.'],[3,'Стараюсь не сравнивать: здесь свои правила, и жить надо по ним.'],[6,'Вижу обе жизни со стороны: в каждой есть ценное, и я выбираю, что взять.'],[7,'«Там» и «здесь» уже не делятся — это одна моя жизнь.']]],\n  ['Представь себя через пять лет. Что для тебя самое важное?', [[0,'Чтобы было спокойно, здоровье в порядке и не страшно за завтра.'],[2,'Чтобы я ни от кого не зависела и решала сама.'],[4,'Чтобы я состоялась в деле и мне платили по моей цене.'],[7,'Чтобы после меня что-то осталось — для тех, кто пойдёт следом.']]],\n  ['Близкий человек, который переехал с тобой, говорит: «Я хочу домой».', [[0,'Сначала пусть отдохнёт и выспится — на усталость всё кажется хуже.'],[1,'Найдём ему здесь своих: компанию, кружок, друзей.'],[4,'Поставим цель, ради которой стоит остаться, и первый шаг к ней.'],[6,'Поговорим о том, что можно не выбирать одну страну — можно держать обе.']]],\n  ['В русскоязычном чате разгорается спор о политике.', [[2,'Напишу свою позицию прямо — молчать не буду.'],[3,'Напомню о правилах чата: здесь не про это.'],[5,'Постараюсь, чтобы все услышали друг друга и никто не ушёл обиженным.'],[7,'Вижу, что за спором у всех одна боль — потерянный дом, и не втягиваюсь.']]],\n  ['У тебя целый свободный день — только для себя.', [[0,'Выспаться, ванна, никуда не спешить.'],[2,'Сделать то, на что давно не решалась, — хоть немного и страшно.'],[5,'Провести его с людьми: встреча, волонтёрство, общее дело.'],[6,'Провести его так, как хочется мне, без «надо», — и подумать, куда я иду.']]],\n  ['Тебя попросили рассказать о своей стране — в школе ребёнка или на работе.', [[1,'Расскажу о наших праздниках и приготовлю наше блюдо.'],[3,'Подготовлюсь основательно, по плану, чтобы всё было точно.'],[4,'Это шанс показать себя — сделаю ярко.'],[7,'Покажу, что нас больше объединяет, чем разделяет.']]]\n];\nconst SITS_PER_SCREEN = 3;\nconst GOAL_HINT = ['высыпаться и просыпаться с силами', 'чтобы рядом был хотя бы один близкий человек', 'самой звонить, записываться и говорить «нет»',\n  'спокойно открывать письма и знать, куда идти', 'найти своё дело и первые свои деньги', 'помогать с радостью, а не через силу', 'перестать жить на чемоданах'];\n\nconst STAY = ['Да, я решила остаться', 'Скорее да, но иногда сомневаюсь', 'Пока не знаю, думаю', 'Скорее нет: хочу вернуться или переехать дальше', 'Это решаю не только я'];\nconst STAY_SHORT = ['решила остаться', 'скорее остаться, но сомневается', 'ещё не решила', 'думает вернуться или уехать дальше', 'решение зависит не только от неё'];\nconst STAY_TXT = [\n  ['Решение принято', 'Ты решила остаться. Это одна из самых сильных опор в новой стране: силы больше не утекают в вопрос «а может, не здесь?», а идут на то, чтобы обустраиваться. Даже если какие-то ступени ещё поскрипывают, у тебя уже есть главное — направление.'],\n  ['Скорее да, но сомнение возвращается', 'Ты в основном здесь, но сомнение иногда возвращается. Это очень частое состояние. Стоит замечать, когда именно оно приходит: часто оно говорит не о стране, а о ступени, которая в этот момент поскрипывает. Усталость, одиночество, неудача на работе звучат как «может, зря мы уехали». Укрепишь ступень — сомнение станет тише.'],\n  ['Ты ещё не решила', 'Ты ещё не решила, остаться ли, и это честно. Но жизнь «между» дорого стоит: трудно вкладываться в язык, людей и дело, когда не знаешь, надолго ли ты здесь. Исследователи миграции замечают, что решение остаться или уехать складывается не из одной причины, а из того, насколько сильны связи здесь и там. Решать прямо сегодня не обязательно. Но можно решить, как жить, пока решаешь: назначить себе срок и прожить эти месяцы набело, а не на чемоданах.'],\n  ['Ты думаешь вернуться или уехать дальше', 'Ты думаешь вернуться или переехать дальше, и это нормальный выбор. Но даже временная жизнь остаётся жизнью. Сон, свои люди, голос и порядок нужны и той, кто здесь на год. А то, что ты построишь сейчас — опыт, язык, уверенность, — ты увезёшь с собой.'],\n  ['Решение зависит не только от тебя', 'Решение остаться или уехать зависит не только от тебя: от работы мужа, от документов, от обстоятельств. Это одна из самых тяжёлых форм неопределённости, потому что горизонт задают другие. Здесь помогает различать: что от меня не зависит, что я могу обсудить и на что повлиять, и что моё прямо сейчас, при любом решении.']\n];\nconst HOW = ['приехала с семьёй / с мужем', 'по работе — своей или мужа', 'вышла замуж', 'уехала от войны или опасности', 'иначе'];\nconst YEARS = ['меньше года', '1–3 года', '3–7 лет', 'больше 7 лет'];\nconst LABELS = ['совсем не про меня', 'скорее нет', 'отчасти', 'скорее да', 'точно про меня'];\nconst CHEER = ['Отвечай про последние 4 недели. Не думай долго: первый отклик обычно самый честный.',\n  'Одна ступенька позади. Дыши — идём дальше.', 'Хорошо идёшь. Ещё немного вверх.',\n  'Ты на середине лестницы. Можно сделать глоток чая.', 'Отвечай как есть — здесь никто не проверяет.',\n  'Почти наверху. Осталось чуть-чуть.', 'Последняя ступень этой части.'];\nconst STATUS = ['здесь начинаем', 'поскрипывает', 'крепкая'];\nconst STEP_LINE = [\n  ['Сил мало, и сон с отдыхом пока не восстанавливают. Телу нужна забота в первую очередь.', 'Сил хватает впритык: одна трудная неделя, и снова держишься на нервах.', 'Ты высыпаешься, у тебя есть свой угол и примерный план на ближайшие месяцы.'],\n  ['Своих людей рядом пока не хватает, и это забирает много тепла.', 'Люди есть, но больше по обстоятельствам, тёплых встреч мало.', 'У тебя есть свои: есть кому позвонить и где тебя ждут.'],\n  ['Многое пока решают за тебя, и голос звучит тише, чем хочется.', 'Ты справляешься сама, но через силу, а сложные разговоры пока обходишь.', 'Ты решаешь свои вопросы сама и умеешь сказать «нет».'],\n  ['Правила и бумаги пока пугают, и страх ошибки забирает силы.', 'В целом понятно, но письма всё ещё вызывают напряжение.', 'Ты понимаешь, как здесь всё устроено, и письмо в ящике не пугает.'],\n  ['Своего дела и своей цены здесь пока нет, и это задевает самоуважение.', 'Занятие есть, но не совсем своё, или своё, но без денег и признания.', 'У тебя есть своё дело, и ты знаешь себе цену.'],\n  ['Ты отдаёшь больше, чем остаётся себе, или пока не находишь, кому нужен твой опыт.', 'Ты помогаешь и делишься, но не всегда по выбору.', 'Ты отдаёшь из избытка и понимаешь, ради чего.'],\n  ['Жизнь пока ощущается черновиком: «там» и «здесь» не складываются.', 'Ты в основном здесь, но иногда снова «на чемоданах».', 'Это твоя жизнь целиком, и ты знаешь, куда идёшь.']\n];\nconst STATUS_LINE = ['Эта ступень просит заботы.', 'Держит, но поскрипывает. В трудную неделю может подвести.', 'Эта ступень держит. Можно на неё опереться.'];\n\n/* ---------- тексты разбора по ступеням ---------- */\nconst RES = [\n  { main: ['Сейчас главная работа — не язык, не карьера и не большие планы. Сейчас главное — ты сама, твоё тело, твой сон, твои силы.',\n           'Помнишь ощущение, когда сходишь на берег после долгого плавания и земля ещё качается? Переезд — это такое плавание. Все привычки, которые дома работали сами, пришлось включать вручную, и голова весь день стоит на посту, как сторож. Усталость, которую ты чувствуешь, — не лень и не слабость. Это честный счёт за огромную работу, которую ты делаешь каждый день и которую никто не видит.',\n           'Пока земля под ногами качается, выше строить трудно. Поэтому начнём здесь — бережно и без подвигов.'],\n    gr: ['Снаружи всё есть — крыша, деньги, страховка, — а внутри сил нет. Так бывает, когда опасность уже позади, а тело ещё не поверило. Ему нужно время и немного заботы, чтобы выдохнуть.',\n         'Ты точно знаешь, что нужно спать и есть по-человечески, — но не получается. Тут поможет не ещё один совет, а простой ритм: одно и то же время, один и тот же маленький ритуал.',\n         'Не хватает опоры снаружи — своего угла, понятного будущего, спокойных денег. Начни с того, что можно сделать за один вечер: устрой себе место, где можно закрыть дверь.',\n         'Ты не разрешаешь себе отдыхать, пока всё не сделано. Но отдых — не награда за выполненный план. Это топливо, без которого план не сдвинется.'],\n    step: 'Три вечера подряд ляг на час раньше. Утром постой десять минут на свету — у окна или на улице. И выбери в доме один уголок, который станет только твоим.',\n    product: '«Две недели, чтобы вернуть пол под ногами»', productText: 'Самостоятельная письменная мини-программа: 10 минут в день, без встреч — на них сейчас и сил может не хватить.' },\n  { main: ['Тебе не хватает своих — тех, с кем тепло, с кем можно не объясняться и кому можно позвонить поздно вечером.',\n           'Дома твой круг собирался сам, годами: двор, школа, работа. Здесь его никто не передал по наследству. Его надо строить заново — взрослой, на чужом языке, когда времени мало, а первый шаг почему-то даётся так трудно. Одиночество после переезда — не знак, что с тобой что-то не так. Это самая частая боль тех, кто уехал.',\n           'Хорошая новость: очаг разжигается не сразу костром, а с одной искры. Начнём с одного человека.'],\n    gr: ['Люди рядом есть, а тепла нет. Значит, нужна не новая компания, а чуть больше глубины с теми, кто уже рядом.',\n         'Ты ждёшь, что позовут, а сама не зовёшь. Дружба во взрослом возрасте держится не на смелости, а на повторении: одни и те же люди, одно и то же время.',\n         'Пока нет ни одного человека или места, где ты своя. Один человек — уже достаточно, чтобы огонь загорелся.',\n         'Ты чувствуешь себя чужой и здесь, и там. Твои традиции, привезённые сюда, — первый мостик: с них начинается своё и на новом месте.'],\n    step: 'Напиши первой той, с кем недавно было приятно, и позови на кофе. Не десять человек — одна. А если согласится — позови и во второй раз: знакомство становится знакомством со второй встречи.',\n    product: '«Один свой человек»', productText: 'Письменная программа на 6 недель: одно письмо и одно маленькое действие в неделю. Не про смелость, а про расписание.' },\n  { main: ['Твоя ступень сейчас — про голос и силу.',\n           'Чужой язык отнимает не слова — он отнимает взрослость. Женщина, у которой дома спрашивали совета, вдруг становится той, «которая не поняла». С ней говорят медленно и громко, за неё решают простые вещи. И каждый раз, когда ты промолчала, внутри откладывается маленький камешек: «я не могу».',\n           'Голос возвращается не словарём, а действиями — маленькими, каждый день. Каждая дверь, которую ты открыла сама, убирает один камешек.'],\n    gr: ['Делать ты можешь, но каждый раз стыдно и неловко. Стыд уходит не тогда, когда появится уверенность, а тогда, когда наберётся много раз, когда ты сделала — несмотря на него.',\n         'Многие простые дела за тебя делают другие. Верни себе одно — самое маленькое. Это будет твоя первая дверь.',\n         'С тобой пока не считаются — дома или в учреждениях. Начни с одной фразы, которая возвращает взрослость: «Говорите, пожалуйста, медленнее».',\n         'Ты сомневаешься, что имеешь право требовать своё. Имеешь. Просто пока не поверила в это до конца.'],\n    step: 'Каждый день — одно маленькое действие на чужом языке: поздороваться, спросить цену, позвонить. И каждый раз записывай в блокнот: «Я смогла».',\n    product: '«Разговорник взрослой женщины» + 21 день', productText: 'Готовые фразы для врача, звонков и сложных разговоров плюс 21 маленькое действие, по одному в день.' },\n  { main: ['Ты как будто в большом здании с десятками дверей, и на каждой табличка на чужом языке. Правила здесь есть, но их никто не объясняет: местные выросли с ними и даже не знают, что знают.',\n           'Твой страх ошибиться — не тревожность и не мнительность. Это разумная реакция на систему, где ошибка дорого стоит.',\n           'Тебе не нужно знать всё. Тебе нужна карта и связка ключей — немного порядка и один надёжный проводник.'],\n    gr: ['Ты многое знаешь, но страх ошибки громче знаний. Помогает простое правило: на любое письмо — пять вопросов, и оно перестаёт быть страшным.',\n         'Бумаги откладываются, сроки ускользают. Здесь нужна не сила воли, а система, которую можно настроить за один вечер.',\n         'Нет надёжного источника ответов. Один проводник лучше двадцати чатов.',\n         'Здешние правила пока кажутся странными, потому что непонятно, зачем они. Когда понимаешь «зачем», правила перестают давить.'],\n    step: 'Разбери почту на три кучки: срочно, может подождать, не моё. Только это — и уже станет легче дышать.',\n    product: '«Папка, которая отвечает за вас»', productText: 'Справочник и система хранения, которые настраиваются за один вечер: что делать с любым письмом, куда идти с вопросом, неписаные правила.' },\n  { main: ['Твоя ступень сейчас — про своё дело и свою цену.',\n           'Переезд разом обнулил три сбережения, которые ты копила годами: профессиональное — диплом здесь не признают, репутационное — никто не знает, чего ты стоишь, и человеческое — некому за тебя поручиться. Это случилось не потому, что ты что-то сделала не так. Это сделал переезд.',\n           'Но инструменты из твоей мастерской никуда не делись. Начнём не с поиска вакансий, а с того, чтобы открыть дверь мастерской и посмотреть, что в ней уже лежит.'],\n    gr: ['Дело есть, а внутри всё равно звучит «я никто». Твоё уважение к себе не должно ждать должности.',\n         'Идеи есть, а шагов нет. Нужна одна дорожка — по силам, а не по мечте.',\n         'Своих денег и признания пока нет. Первый заработанный франк важнее суммы: он говорит «я могу».',\n         'Ты меряешь себя чужими успехами. Но сравнивать себя с теми, кто приехал раньше, — всё равно что сравнивать росток с деревом.'],\n    step: 'Выпиши всё, что ты умеешь, — не по диплому, а по жизни. А потом отметь, что из этого может пригодиться здесь.',\n    product: '«Своя цена»', productText: 'Письменный практикум на 30 дней: банк умений, три дорожки — работа, маленькое своё дело, проект на пробу — и первый заработанный франк.' },\n  { main: ['У тебя уже есть свой сад, и тебе хочется делиться — помогать, подсказывать, быть нужной. Это прекрасно.',\n           'Только хороший садовник знает: если раздать всю воду, сад засохнет. На этой ступени очень легко отдать себя без остатка и не заметить, как стало пусто.',\n           'Начнём с меры: кому ты хочешь отдавать, сколько — и что остаётся тебе.'],\n    gr: ['После помощи другим становится пусто. Значит, ты отдаёшь больше, чем к тебе возвращается.',\n         'Трудно сказать «нет». Но «нет» — тоже забота: о себе и о том, чтобы твоя помощь оставалась живой.',\n         'Нет круга, где ты соавтор. Ищи не тех, кому помочь, а тех, с кем делать вместе.',\n         'Неудобно брать деньги за то, что ты делаешь хорошо. Цена — это не жадность, а уважение к твоему опыту.'],\n    step: 'Посчитай, сколько часов в месяц ты отдаёшь другим. И столько же запиши в календарь — для себя.',\n    product: '«Кому нужен мой опыт»', productText: 'Письменная программа на 14 дней: кому твой опыт нужен, в какой форме и на каких условиях, и отдельная часть про меру.' },\n  { main: ['Ты уже высоко — отсюда видна почти вся долина твоей жизни. Но что-то мешает сделать последний шаг на вершину холма.',\n           'Решение уехать почти никогда не закрывается само. Оно возвращается при каждой трудности: «а если бы мы не уехали…». И пока этот вопрос открыт, жизнь остаётся черновиком — а черновик не жалко.',\n           'Пора закрыть его и начать жить набело.'],\n    gr: ['«Там» и «здесь» никак не складываются в одно. Мост между ними строится из того, что ты сама выбираешь взять с каждого берега.',\n         'Ты всё ещё откладываешь «до лучших времён». Одна отложенная вещь, сделанная в этом месяце, изменит больше, чем годы размышлений.',\n         'Дом пока ощущается временным. Начни с одного гвоздя в стене — и повесь на него то, что любишь.',\n         'Решение уехать всё ещё переигрывается внутри. Допиши до конца историю «если бы мы не уехали» — честно, по годам. Дописанная, она перестанет возвращаться.'],\n    step: 'Сделай одну вещь, которую откладывала «до возвращения»: повесь картину, купи красивую посуду, запишись туда, куда давно хотелось.',\n    product: '«Это не черновик»', productText: 'Письменная программа на 21 день: закрыть решение о переезде на бумаге и перестать жить на паузе. Дальше — «Карта целой жизни».' }\n];\nconst REFUGEE = 'Часть того, что тебе сейчас нужно, — жильё, документы, деньги — решается не тобой. Это правда так, и это не твоя слабость. С этим помогают социальная служба общины, интеграционная служба кантона, Красный Крест — обратись к ним, это их работа. Коучинг их не заменяет. Он может идти рядом: помочь вернуть сон, ритм, маленький горизонт и разрешение не быть сильной каждую минуту.';\nconst FIRST_YEAR = 'Ты здесь меньше года. Первый год почти у всех проходит на нижних ступенях — земля ещё качается, как после долгого плавания. Это норма, а не диагноз.';\nconst LONG_TIME = 'Ты здесь уже много лет, а жизнь всё ещё будто на паузе. Если тебе от этого грустно, знай: это одна из самых частых историй. Ты не одна — и это можно изменить.';\nconst HEART = [\n  'Громче всего сейчас звучит забота о себе: отдых, тишина, безопасность. Сердце просит передышки — и это мудро.',\n  'Громче всего звучат свои люди, тепло и корни. Тебе важно быть частью круга.',\n  'Громче всего звучит твой голос: решать самой, не прогибаться, действовать.',\n  'Громче всего звучит порядок: делать как следует, понимать правила, быть надёжной.',\n  'Громче всего звучит дело: расти, состояться, получить свою цену.',\n  'Громче всего звучат люди и тепло между ними: чтобы всем было хорошо.',\n  'Громче всего звучит взгляд с холма: видеть целое и выбирать своё.',\n  'Громче всего звучит «больше меня»: связь со всем и забота о тех, кто придёт после.'\n];\nconst TRAPS = {\n  sky:   'Фраза «мне везде дом» красивая — и бывает правдой. Но когда некому позвонить, а утром нет сил, она иногда помогает не замечать, что дома пока нигде. Небо над домом прекрасно, когда есть сам дом. Давай начнём с фундамента — и тогда эти слова станут правдой.',\n  green: 'Ты щедрая, и помогать другим тебе легко. Но иногда помощь другим — самый благородный способ не заниматься своим вопросом «а я-то куда?». Сначала свою мастерскую — тогда и сад для других будет цвести, а не забирать последнюю воду.',\n  yellow:'Ты видишь жизнь широко и умеешь держать разные правды. Но вид с холма не заменяет сна, своих людей и своего голоса. Сначала ступени под ногами — холм никуда не денется.',\n  blue:  'Ты так стараешься делать всё правильно… Может быть, правила стали способом не рисковать и не говорить вслух «я хочу»? Иногда смелость важнее точности.'\n};\n\n/* ---------- утилиты ---------- */\nconst $ = id => document.getElementById(id);\nconst sum = a => a.reduce((x, y) => x + y, 0);\nconst esc = s => String(s).replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst shuffle = a => { a = a.slice(); for (let i = a.length - 1; i > 0; i--){ const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };\nconst lvName = k => `${k + 1} · ${LV[k].name}`;\n\n/* ---------- значки ступеней ---------- */\nfunction lvIcon(k, size = 24, col){\n  const c = col || LV[k].line, f = LV[k].fill, sw = 'stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"';\n  const p = [\n    `<circle cx=\"12\" cy=\"8\" r=\"3.2\" fill=\"${f}\" stroke=\"${c}\" ${sw}/><path d=\"M3 15c3-2 6-2 9 0s6 2 9 0M3 19.5c3-2 6-2 9 0s6 2 9 0\" fill=\"none\" stroke=\"${c}\" ${sw}/>`,\n    `<path d=\"M12 3c3 4 6.5 6 6.5 10.5a6.5 6.5 0 0 1-13 0c0-3 2-4.5 3-6.5 1 2 2 3 3 3 0-3-1-5 .5-7z\" fill=\"${f}\" stroke=\"${c}\" ${sw}/><path d=\"M9 21h6\" stroke=\"${c}\" ${sw}/>`,\n    `<rect x=\"6\" y=\"3\" width=\"12\" height=\"18\" rx=\"1.5\" fill=\"${f}\" stroke=\"${c}\" ${sw}/><circle cx=\"14.8\" cy=\"12.5\" r=\"1.2\" fill=\"${c}\"/><path d=\"M3 21h18\" stroke=\"${c}\" ${sw}/>`,\n    `<circle cx=\"8\" cy=\"12\" r=\"4.2\" fill=\"${f}\" stroke=\"${c}\" ${sw}/><path d=\"M12.2 12H21M18 12v3M21 12v3\" fill=\"none\" stroke=\"${c}\" ${sw}/>`,\n    `<path d=\"M13.5 4.5l6 6-3 3-6-6z\" fill=\"${f}\" stroke=\"${c}\" ${sw}/><path d=\"M12 9l-8 8 3 3 8-8\" fill=\"none\" stroke=\"${c}\" ${sw}/>`,\n    `<path d=\"M12 21v-9\" stroke=\"${c}\" ${sw}/><path d=\"M12 13c-4.5 0-7-3-7-7 4.5 0 7 3 7 7zM12 11c0-4.5 3-7 7.5-7 0 4.5-3 7-7.5 7z\" fill=\"${f}\" stroke=\"${c}\" ${sw}/>`,\n    `<path d=\"M2 19.5l7-9.5 4 5 3-3.5 6 8z\" fill=\"${f}\" stroke=\"${c}\" ${sw}/><circle cx=\"17\" cy=\"5.5\" r=\"2\" fill=\"none\" stroke=\"${c}\" ${sw}/>`,\n    `<path d=\"M12 3l1.9 5.6L19.5 10.5l-5.6 1.9L12 18l-1.9-5.6L4.5 10.5l5.6-1.9z\" fill=\"${f}\" stroke=\"${c}\" ${sw}/><circle cx=\"19\" cy=\"19\" r=\"1.4\" fill=\"${c}\"/><circle cx=\"5\" cy=\"19.5\" r=\"1\" fill=\"${c}\"/>`][k];\n  return `<svg viewBox=\"0 0 24 24\" width=\"${size}\" height=\"${size}\" aria-hidden=\"true\">${p}</svg>`;\n}\n\n/* ---------- стартовая страница: плитки, два входа, путеводитель ---------- */\n$('stTiles').innerHTML = LV.map((l, k) => `<div class=\"st-tile${k === 7 ? ' sky' : ''}\" style=\"--f:${l.fill};--l:${l.line};--s:${l.soft}\">\n  ${lvIcon(k, 26)}<b>${l.name}</b><span>${k + 1} · ${l.color.toLowerCase()} · ${l.short}</span></div>`).join('');\n\n$('stAB').innerHTML = abHtml();\n\nfunction renderGuide(){\n  const levels = GUIDE.levels.map((g, k) => {\n    const l = LV[k];\n    return `<details class=\"st-lv${k === 7 ? ' sky' : ''}\" id=\"guide-${k + 1}\" style=\"--f:${l.fill};--l:${l.line};--s:${l.soft}\">\n      <summary><span class=\"st-ico\">${lvIcon(k, 30)}</span><span class=\"st-sum\"><span class=\"st-n\">Ступень ${g.n} · ${g.color.toLowerCase()}</span><b>${g.name}</b><span class=\"st-sub\">${g.teaser}</span></span><span class=\"st-plus\" aria-hidden=\"true\"></span></summary>\n      <div class=\"st-body\">\n        ${g.note ? `<p class=\"note\">${g.note}</p>` : ''}\n        <div class=\"st-story\">${g.body}</div>\n        <div class=\"st-ask\"><h4>Возьми ручку: пять вопросов себе</h4>${g.ask}</div>\n        ${k === 3 ? `<div class=\"st-swiss\"><b>Если ты живёшь в Швейцарии</b><p>Мой бесплатный Telegram-бот «Гайд по Швейцарии — Swiss Guide» на русском: документы, страховки, налоги, школа, жильё, письма из общины и неписаные правила. Карта и ключи в одном месте.</p><a href=\"https://t.me/swisscompass_bot\" target=\"_blank\" rel=\"noopener\">Открыть бот: @swisscompass_bot</a></div>` : ''}\n        ${k < 7 ? `<div><button type=\"button\" class=\"btn ghost st-totest\">Проверить, держит ли эта ступень → тест</button></div>` : ''}\n      </div></details>`;\n  }).join('');\n  $('guide').innerHTML = `<div id=\"backRes\" hidden><button type=\"button\" class=\"btn ghost\" id=\"backResBtn\">← Вернуться к моему разбору</button></div><div class=\"blk st-guide-intro\"><div class=\"eyebrow\">Путеводитель по ступеням</div><h2>${GUIDE.introTitle}</h2><div class=\"st-story\">${GUIDE.intro}</div></div>\n    <div class=\"row\" style=\"justify-content:space-between\"><h2 style=\"margin:0\">Восемь ступеней</h2>\n      <button type=\"button\" class=\"btn ghost\" id=\"openAll\" style=\"padding:8px 16px\">Раскрыть все</button></div>\n    <div class=\"stack\" style=\"gap:12px\">${levels}</div>\n    <div class=\"blk st-guide-end\"><div class=\"st-story\">${GUIDE.end}</div><div><button type=\"button\" class=\"btn st-totest\">Пройти тест «7 ступеней устойчивости»</button></div></div>\n    ${GUIDE.sources ? `<details class=\"st-sources\"><summary>Источники</summary>${GUIDE.sources}</details>` : ''}`;\n  $('openAll').addEventListener('click', () => {\n    const all = [...document.querySelectorAll('.st-lv')], open = all.some(d => !d.open);\n    all.forEach(d => d.open = open); $('openAll').textContent = open ? 'Свернуть все' : 'Раскрыть все';\n  });\n}\nrenderGuide();\nfunction showPart(id){\n  $('guide').hidden = id !== 'guide'; $('testPrep').hidden = id !== 'testPrep';\n  $('goGuide').setAttribute('aria-pressed', id === 'guide'); $('goTest').setAttribute('aria-pressed', id === 'testPrep');\n}\nfunction openGuide(n){\n  const fromResult = !$('result').hidden;\n  $('result').hidden = true; $('quiz').hidden = true; $('intro').hidden = false;\n  $('backRes').hidden = !(fromResult || finished);\n  showPart('guide');\n  const d = n ? $('guide-' + n) : null;\n  if (d){ d.open = true; setTimeout(() => d.scrollIntoView({ behavior: 'smooth', block: 'start' }), 30); }\n  else $('guide').scrollIntoView({ behavior: 'smooth', block: 'start' });\n}\n$('goGuide').addEventListener('click', () => openGuide());\n$('backResBtn').addEventListener('click', () => { const v = loadSaved(); if (v && v.finished){ restore(v); showResult(); } else { $('intro').hidden = true; $('result').hidden = false; window.scrollTo(0, 0); } });\n$('goTest').addEventListener('click', () => { showPart('testPrep'); $('testPrep').scrollIntoView({ behavior: 'smooth', block: 'start' }); });\ndocument.addEventListener('click', ev => {\n  if (ev.target.closest('.st-totest')){ showPart('testPrep'); $('testPrep').scrollIntoView({ behavior: 'smooth', block: 'start' }); return; }\n  const a = ev.target.closest('[data-guide]');\n  if (a && !a.closest('.pdf-page')){ ev.preventDefault(); openGuide(+a.dataset.guide); }\n});\nif (/guide-(\\d)/.test(location.hash)) { /* ссылка из PDF: открыть путеводитель после приветствия */\n  window.__guideFromHash = +location.hash.match(/guide-(\\d)/)[1];\n}\n(function(){ const go = $('svGo'); if (go && window.__guideFromHash) go.addEventListener('click', () => setTimeout(() => { if (!$('testStart').hidden) openGuide(window.__guideFromHash); }, 0)); })();\n\n/* ---------- состояние теста ---------- */\nlet ctx, ans, sky, pts, goals, goalText, order, sitOrder, steps, step = 0, myName = '', last = null, finished = false, startedAt = 0;\n\n/* ---------- память: ответы сохраняются в этом браузере после каждого клика ---------- */\nconst SAVE_KEY = 'irinaTests.stupeni.v1';\nfunction save(){\n  try { localStorage.setItem(SAVE_KEY, JSON.stringify({ ctx, ans, sky, pts, goals, goalText, order, sitOrder, step, myName, finished, startedAt, t: Date.now() })); } catch(e){}\n}\nfunction loadSaved(){ try { const v = JSON.parse(localStorage.getItem(SAVE_KEY) || 'null'); return v && v.ans && v.pts ? v : null; } catch(e){ return null; } }\nfunction forget(){ try { localStorage.removeItem(SAVE_KEY); } catch(e){} }\nfunction restore(v){\n  ({ ctx, ans, sky, pts, order, sitOrder, myName, finished } = v); startedAt = v.startedAt || v.t;\n  if (ctx.stay === undefined) ctx.stay = null;\n  goals = v.goals || ITEMS.map(() => null); goalText = v.goalText || ITEMS.map(() => '');\n  buildSteps(); step = Math.min(v.step || 0, steps.length - 1);\n  $('nameMe').value = myName || '';\n}\nfunction reset(){\n  finished = false; startedAt = Date.now();\n  ctx = { how: null, years: null, stay: null };\n  ans = ITEMS.map(() => Array(8).fill(null));\n  sky = Array(6).fill(null);\n  pts = SITS.map(() => [0, 0, 0, 0]);\n  goals = ITEMS.map(() => null); goalText = ITEMS.map(() => '');\n  order = ITEMS.map(() => shuffle([0,1,2,3,4,5,6,7]));\n  sitOrder = SITS.map(() => shuffle([0,1,2,3]));\n}\nconst val = (it, v) => it[2] ? 4 - v : v;\nconst stageScore = k => sum(ans[k].map((v, i) => val(ITEMS[k][i], v)));\nconst stagePct = k => Math.round(stageScore(k) / 32 * 100);\nconst statusOf = p => p >= 75 ? 2 : p >= 50 ? 1 : 0;\nconst allHold = () => ans.every(a => a.every(v => v !== null)) && ITEMS.every((_, k) => statusOf(stagePct(k)) === 2);\nfunction buildSteps(){\n  steps = [{ t: 'about' }];\n  ITEMS.forEach((_, k) => steps.push({ t: 'stage', k }));\n  if (allHold()) steps.push({ t: 'sky' });\n  for (let i = 0; i < SITS.length; i += SITS_PER_SCREEN) steps.push({ t: 'sit', ids: SITS.slice(i, i + SITS_PER_SCREEN).map((_, j) => i + j) });\n  steps.push({ t: 'goal' });\n}\nconst totalCount = () => 3 + 56 + (steps.some(s => s.t === 'sky') ? 6 : 0) + SITS.length + 7;\nfunction doneCount(){\n  return (ctx.how !== null) + (ctx.years !== null) + (ctx.stay != null) + ans.flat().filter(v => v !== null).length\n    + (steps.some(s => s.t === 'sky') ? sky.filter(v => v !== null).length : 0) + pts.filter(p => sum(p) === 10).length + goals.filter(g => g !== null).length;\n}\n\n$('startBtn').addEventListener('click', () => {\n  myName = $('nameMe').value.trim();\n  resetInvite(); window.__leadCountry = '';\n  reset(); buildSteps(); step = 0;\n  $('intro').hidden = true; $('quiz').hidden = false; renderStep(); window.scrollTo(0, 0);\n});\n\nfunction choiceGroup(title, opts, key){\n  const wrap = document.createElement('div'); wrap.className = 'q';\n  wrap.innerHTML = `<p>${title}</p><div class=\"choices1\" role=\"group\"></div>`;\n  const g = wrap.querySelector('.choices1');\n  opts.forEach((o, i) => {\n    const b = document.createElement('button'); b.className = 'opt1'; b.type = 'button'; b.textContent = o;\n    b.setAttribute('aria-pressed', ctx[key] === i ? 'true' : 'false');\n    b.addEventListener('click', () => { ctx[key] = i; g.querySelectorAll('.opt1').forEach((x, n) => x.setAttribute('aria-pressed', n === i ? 'true' : 'false')); update(); });\n    g.appendChild(b);\n  });\n  return wrap;\n}\nfunction scaleItem(text, num, arr, i){\n  const q = document.createElement('div'); q.className = 'q';\n  q.innerHTML = `<p><span class=\"n\">${num}.</span>${text}</p><div class=\"opts\" role=\"group\" aria-label=\"Насколько это про тебя\"></div>`;\n  const opts = q.querySelector('.opts');\n  for (let v = 0; v <= 4; v++){\n    const o = document.createElement('button'); o.className = 'opt'; o.type = 'button';\n    o.setAttribute('aria-pressed', arr[i] === v ? 'true' : 'false');\n    o.innerHTML = `<b>${v}</b><small>${LABELS[v]}</small>`;\n    o.addEventListener('click', () => { arr[i] = v; opts.querySelectorAll('.opt').forEach((x, n) => x.setAttribute('aria-pressed', n === v ? 'true' : 'false')); update(); });\n    opts.appendChild(o);\n  }\n  return q;\n}\nfunction sitItem(s, num){\n  const q = document.createElement('div'); q.className = 'q st-sit';\n  const left = () => 10 - sum(pts[s]);\n  q.innerHTML = `<p><span class=\"n\">${num}.</span>${SITS[s][0]}</p><div class=\"st-pts\"></div><div class=\"st-left\"></div>`;\n  const box = q.querySelector('.st-pts'), leftEl = q.querySelector('.st-left');\n  const paint = () => {\n    const l = left();\n    leftEl.textContent = l === 0 ? 'Все 10 баллов распределены ✓' : `Осталось баллов: ${l}`;\n    leftEl.classList.toggle('done', l === 0);\n    box.querySelectorAll('.st-row').forEach(r => {\n      const o = +r.dataset.o, v = pts[s][o];\n      r.querySelector('.st-v').textContent = v;\n      r.querySelector('.minus').disabled = v === 0;\n      r.querySelector('.plus').disabled = l === 0;\n      r.querySelector('.st-dots').innerHTML = '<i></i>'.repeat(v);\n      r.classList.toggle('on', v > 0);\n    });\n    update();\n  };\n  sitOrder[s].forEach(o => {\n    const r = document.createElement('div'); r.className = 'st-row'; r.dataset.o = o;\n    r.innerHTML = `<div class=\"st-t\"><span>${SITS[s][1][o][1]}</span><span class=\"st-dots\"></span></div>\n      <div class=\"st-ctl\"><button type=\"button\" class=\"minus\" aria-label=\"Убрать балл\">−</button><span class=\"st-v\">0</span><button type=\"button\" class=\"plus\" aria-label=\"Добавить балл\">+</button></div>`;\n    r.querySelector('.minus').addEventListener('click', () => { if (pts[s][o] > 0){ pts[s][o]--; paint(); } });\n    r.querySelector('.plus').addEventListener('click', () => { if (left() > 0){ pts[s][o]++; paint(); } });\n    r.querySelector('.st-t').addEventListener('click', () => { if (left() > 0){ pts[s][o]++; paint(); } });\n    box.appendChild(r);\n  });\n  paint();\n  return q;\n}\n\nfunction renderStep(){\n  const list = $('qlist'), S = steps[step]; list.innerHTML = '';\n  $('stepLabel').textContent = `Шаг ${step + 1} из ${steps.length}`;\n  document.documentElement.style.setProperty('--accent', 'var(--plum)');\n  $('roleTitle').style.color = 'var(--plum)';\n  if (S.t === 'about'){\n    $('partTag').textContent = 'О тебе';\n    $('roleTitle').textContent = 'Твоя история';\n    $('roleSub').textContent = 'Три вопроса о твоей истории. В подсчёт ступеней они не идут, но помогут мне сказать тебе точнее, куда ты движешься.';\n    list.appendChild(choiceGroup('Как ты здесь оказалась?', HOW, 'how'));\n    list.appendChild(choiceGroup('Сколько ты уже живёшь в новой стране?', YEARS, 'years'));\n    list.appendChild(choiceGroup('Ты хочешь остаться здесь жить?', STAY, 'stay'));\n  } else if (S.t === 'stage'){\n    $('partTag').textContent = 'Часть 1 · Опора · за последние 4 недели';\n    $('roleTitle').textContent = `Ступень ${S.k + 1} из 7`;\n    $('roleSub').textContent = CHEER[S.k];\n    let n = S.k * 8;\n    order[S.k].forEach(i => list.appendChild(scaleItem(ITEMS[S.k][i][1], ++n, ans[S.k], i)));\n  } else if (S.t === 'sky'){\n    $('partTag').textContent = 'Небо над домом · бонус';\n    $('roleTitle').textContent = 'Все семь ступеней под тобой держат';\n    $('roleTitle').style.color = LV[7].line;\n    $('roleSub').textContent = 'Это редкость — и это твоя заслуга. Над домом есть ещё небо: не ступень, которую нужно чинить, а горизонт, к которому растут. Шесть фраз — посмотрим, где ты относительно него.';\n    let n = 56;\n    SKY.forEach((it, i) => list.appendChild(scaleItem(it[1], ++n, sky, i)));\n  } else if (S.t === 'goal'){\n    $('partTag').textContent = 'Часть 3 · Твоя цель';\n    $('roleTitle').textContent = 'Куда тебе хочется';\n    $('roleSub').textContent = 'Представь себя через три–шесть месяцев. Насколько крепкой ты хочешь видеть каждую ступень? 0 — сейчас это не важно, 10 — опора, на которую можно встать всем весом. Если хочется, допиши в одну строку, что бы ты хотела здесь изменить: так цель станет твоей, а не общей.';\n    ITEMS.forEach((_, k) => list.appendChild(goalItem(k)));\n  } else {\n    const first = S.ids[0] === 0;\n    $('partTag').textContent = 'Часть 2 · Ситуации';\n    $('roleTitle').textContent = first ? 'Двенадцать сценок из жизни' : `Ситуации ${S.ids[0] + 1}–${S.ids[S.ids.length - 1] + 1} из 12`;\n    $('roleSub').textContent = first\n      ? 'В каждой сценке четыре варианта. У тебя есть 10 баллов: отдай больше тому, что ближе тебе. Можно все 10 одному варианту, можно разделить. Все варианты нормальные, просто разные. Выбирай не как правильно, а как ты на самом деле.'\n      : 'Распредели 10 баллов в каждой сценке: больше — тому, что ближе тебе.';\n    S.ids.forEach(s => list.appendChild(sitItem(s, s + 1)));\n  }\n  $('next').textContent = step === steps.length - 1 ? 'Показать разбор' : 'Дальше';\n  update();\n}\nfunction goalItem(k){\n  const l = LV[k], q = document.createElement('div'); q.className = 'q st-goal'; q.style.cssText = `--l:${l.line};--f:${l.fill};--s:${l.soft}`;\n  q.innerHTML = `<div class=\"st-gh\"><span class=\"st-ico\">${lvIcon(k, 22)}</span><b>${k + 1} · ${l.name}</b><span class=\"st-gv\"></span></div>\n    <input type=\"range\" min=\"0\" max=\"10\" step=\"1\" aria-label=\"Насколько крепкой ты хочешь видеть ступень «${l.name}»\" value=\"${goals[k] ?? 5}\">\n    <div class=\"st-gscale\"><span>0 · не важно сейчас</span><span>10 · крепкая опора</span></div>\n    <textarea class=\"st-gtext\" rows=\"2\" maxlength=\"160\" placeholder=\"Моя цель здесь (по желанию). Например: ${GOAL_HINT[k]}\">${esc(goalText[k] || '')}</textarea>`;\n  const r = q.querySelector('input[type=range]'), v = q.querySelector('.st-gv');\n  const paint = () => { v.textContent = goals[k] === null ? 'отметь' : goals[k] + ' из 10'; q.classList.toggle('set', goals[k] !== null); r.style.setProperty('--p', ((goals[k] ?? 5) * 10) + '%'); };\n  r.addEventListener('input', () => { goals[k] = +r.value; paint(); update(); });\n  r.addEventListener('pointerdown', () => { if (goals[k] === null){ goals[k] = +r.value; paint(); update(); } });\n  q.querySelector('.st-gtext').addEventListener('input', e => { goalText[k] = e.target.value; save(); });\n  paint();\n  return q;\n}\nfunction stepComplete(){\n  const S = steps[step];\n  if (S.t === 'goal') return goals.every(g => g !== null);\n  if (S.t === 'about') return ctx.how !== null && ctx.years !== null && ctx.stay != null;\n  if (S.t === 'stage') return ans[S.k].every(v => v !== null);\n  if (S.t === 'sky') return sky.every(v => v !== null);\n  return S.ids.every(s => sum(pts[s]) === 10);\n}\nfunction update(){\n  save();\n  const d = doneCount(), T = totalCount();\n  $('countLabel').textContent = `${d} из ${T}`;\n  $('prog').style.width = (d / T * 100) + '%';\n  $('next').disabled = !stepComplete();\n}\n$('next').addEventListener('click', () => {\n  if (steps[step].t === 'stage' && steps[step].k === 6) buildSteps();   // бонус появляется, если все 7 ступеней крепкие\n  if (step < steps.length - 1){ step++; renderStep(); window.scrollTo(0, 0); } else showResult();\n});\n$('back').addEventListener('click', () => {\n  if (step > 0){ step--; renderStep(); window.scrollTo(0, 0); }\n  else { $('quiz').hidden = true; $('intro').hidden = false; }\n});\n\n/* ---------- подсчёт ---------- */\nfunction compute(){\n  const pct = ITEMS.map((_, k) => stagePct(k));\n  const st = pct.map(statusOf);\n  const hasSky = steps.some(s => s.t === 'sky');\n  const skySum = hasSky ? sum(sky.map((v, i) => val(SKY[i], v))) : null;\n  let o = st.indexOf(0);                           // самая нижняя «здесь начинаем»\n  if (o < 0) o = st.indexOf(1);                    // иначе самая нижняя «поскрипывает»\n  let top = null;\n  if (o < 0){ o = 6; top = skySum >= 18 ? 'horizon' : 'edge'; }\n  const oLevel = top === 'horizon' ? 8 : o + 1;    // 1–8\n  const gr = [0,1,2,3].map(g => sum(ITEMS[o].map((it, i) => it[0] === g ? val(it, ans[o][i]) : 0)));\n  const weak = [2,1,0,3].reduce((b, g) => gr[g] < gr[b] ? g : b, 2);\n  const extra = st.findIndex((s, k) => k > o && s === 0);\n  const heart = LV.map(() => 0);\n  SITS.forEach((s, i) => s[1].forEach(([lv], j) => heart[lv] += pts[i][j]));\n  const hp = heart.map(v => Math.round(v / 60 * 100));\n  const rank = heart.map((v, k) => [v, k]).sort((a, b) => b[0] - a[0]);\n  const c = rank[0][1], c2 = rank[0][0] - rank[1][0] < 4 ? rank[1][1] : null;\n  const quiet = rank[rank.length - 1][1];\n  const cLevel = c + 1;\n  const combo = cLevel === oLevel || cLevel === oLevel + 1 ? 'same' : cLevel > oLevel ? 'above' : 'below';\n  const trap = cLevel === 8 && (st[0] === 0 || st[1] === 0) ? 'sky'\n    : cLevel === 6 && st[4] === 0 ? 'green'\n    : cLevel === 7 && (st[0] === 0 || st[1] === 0 || st[2] === 0) ? 'yellow'\n    : cLevel === 4 && st[2] === 0 ? 'blue' : null;\n  return { pct, st, skySum, o, top, oLevel, gr, weak, extra, heart, hp, c, c2, quiet, combo, trap };\n}\n\n/* ---------- картинки разбора ---------- */\nconst INK = '#2F2924', MUTED = '#8C7F71';\nconst tx = (x, y, t, o = {}) => `<text x=\"${x}\" y=\"${y}\" text-anchor=\"${o.a || 'start'}\" font-family=\"${o.serif ? 'Forum, Georgia, serif' : 'Manrope, sans-serif'}\" font-size=\"${o.s || 13}\" font-weight=\"${o.w || 400}\" fill=\"${o.c || INK}\">${t}</text>`;\nlet svgN = 0;\nfunction wcFilter(){ const id = 'wc' + (++svgN); return [id, `<defs><filter id=\"${id}\" x=\"-5%\" y=\"-20%\" width=\"110%\" height=\"140%\"><feTurbulence type=\"fractalNoise\" baseFrequency=\".035\" numOctaves=\"2\" seed=\"${svgN % 7 + 2}\"/><feDisplacementMap in=\"SourceGraphic\" scale=\"4\"/></filter></defs>`]; }\n\n/* Лестница: 7 ступеней снизу вверх + небо пунктиром (ширина рассчитана на телефон) */\nfunction ladderSVG(r){\n  const W = 400, stepH = 40, gap = 7, x0 = 2, dx = 17, bw = 280, top = 50, H = top + 7 * (stepH + gap);\n  const [fid, defs] = wcFilter();\n  let s = `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Лестница из семи ступеней\">${defs}`;\n  const row = (k, x, y, p, me, dashed) => {\n    const l = LV[k]; let t = '';\n    t += `<rect x=\"${x}\" y=\"${y}\" width=\"${bw}\" height=\"${stepH}\" rx=\"10\" fill=\"#FFFFFF\" fill-opacity=\".6\"/>`;\n    if (p > 0) t += `<rect x=\"${x + 2}\" y=\"${y + 2}\" width=\"${(bw - 4) * p / 100}\" height=\"${stepH - 4}\" rx=\"8\" fill=\"${l.fill}\" filter=\"url(#${fid})\"/>`;\n    t += `<rect x=\"${x}\" y=\"${y}\" width=\"${bw}\" height=\"${stepH}\" rx=\"10\" fill=\"none\" stroke=\"${l.line}\" stroke-width=\"${me ? 2.8 : 1.2}\" ${dashed ? 'stroke-dasharray=\"5 4\"' : ''}/>`;\n    t += `<g transform=\"translate(${x + 8} ${y + 9})\">${lvIcon(k, 22).replace(/^<svg[^>]*>|<\\/svg>$/g, '')}</g>`;\n    t += tx(x + 36, y + 26, `${k + 1} · ${l.name}`, { serif: true, s: 16, c: l.line });\n    return t;\n  };\n  const skyOn = r.top === 'horizon', sx = x0 + 7 * dx;\n  s += row(7, sx, 4, skyOn ? 100 : 0, skyOn, !skyOn);\n  s += tx(sx + bw - 10, 30, skyOn ? 'ты здесь' : 'горизонт', { a: 'end', s: 12, c: LV[7].line, w: skyOn ? 800 : 500 });\n  for (let k = 0; k < 7; k++){\n    const y = top + (6 - k) * (stepH + gap), x = x0 + k * dx, l = LV[k], p = r.pct[k], me = r.o === k && r.top !== 'horizon';\n    s += row(k, x, y, p, me, false);\n    s += tx(x + bw - 10, y + 26, (me ? (r.top === 'edge' ? 'у края · ' : 'ты здесь · ') : '') + p + '%', { a: 'end', s: me ? 13 : 12.5, w: 800, c: l.line });\n  }\n  return s + '</svg>';\n}\n/* Профиль сердца: 8 дорожек */\nfunction heartSVG(r){\n  const W = 400, rowH = 36, H = 6 + rowH * 8, x0 = 150, x1 = 352;\n  const [fid, defs] = wcFilter();\n  let s = `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Профиль сердца\">${defs}`;\n  r.hp.forEach((v, k) => {\n    const y = 6 + k * rowH, l = LV[k], hi = k === r.c || k === r.c2;\n    s += `<g transform=\"translate(0 ${y + 6})\">${lvIcon(k, 20).replace(/^<svg[^>]*>|<\\/svg>$/g, '')}</g>`;\n    s += tx(26, y + 21, l.name, { s: 13.5, w: hi ? 800 : 500, c: l.line });\n    s += `<rect x=\"${x0}\" y=\"${y + 7}\" width=\"${x1 - x0}\" height=\"20\" rx=\"10\" fill=\"${l.soft}\" stroke=\"${l.line}\" stroke-width=\"${hi ? 1.8 : .7}\"/>`;\n    if (v > 0) s += `<rect x=\"${x0 + 2}\" y=\"${y + 9}\" width=\"${(x1 - x0 - 4) * v / 100}\" height=\"16\" rx=\"8\" fill=\"${l.fill}\" filter=\"url(#${fid})\"/>`;\n    s += tx(W - 2, y + 22, v + '%', { a: 'end', s: 13, w: hi ? 800 : 500, c: l.line });\n  });\n  return s + '</svg>';\n}\nconst WHEEL_LABEL = ['Тело', 'Свои', 'Голос', 'Порядок', 'Дело', 'Вклад', 'Целое'];\nconst wheelSVG = (fill, outline, size) => petalWheelSVG(ITEMS.map((_, k) => ({ label: (k + 1) + ' ' + WHEEL_LABEL[k], fill: LV[k].fill, line: LV[k].line })), fill, outline, size);\nfunction graniHtml(r){\n  const l = LV[r.o];\n  return `<div class=\"st-grani\">${GR.map((g, i) => `<div class=\"${i === r.weak ? 'weak' : ''}\"><span><b>${g}</b> · ${GR_SUB[i]}</span>\n    <div class=\"bar\" style=\"background:${l.soft}\"><i style=\"width:${r.gr[i] / 8 * 100}%;background:${l.line}\"></i></div><small>${r.gr[i]} из 8</small></div>`).join('')}</div>`;\n}\n\nconst HOLD = [\n  'Когда земля под ногами качается, почти все силы уходят на то, чтобы держаться. На движение их просто не остаётся, и это не лень, а усталость тела.',\n  'Без своих людей любое движение даётся вдвое тяжелее: не с кем разделить радость и не на кого опереться, когда страшно.',\n  'Пока голос не вернулся, любая цель упирается в «я не смогу»: позвонить, спросить, настоять. И цель откладывается, чтобы не встречаться с этим чувством.',\n  'Когда неясно, как здесь всё устроено, страх ошибиться оказывается сильнее желания. Кажется безопаснее подождать, чем сделать не так.',\n  'Когда своё дело и своя цена ещё не найдены, легко жить чужими целями: «надо найти работу», «надо выучить язык». А чужие цели не дают сил.',\n  'Когда отдаёшь другим больше, чем остаётся себе, на своё просто не хватает времени и воды.',\n  'Пока решение о переезде не закрыто, жизнь кажется черновиком. А зачем ставить цели в черновике?'\n];\nconst STATES = {\n  alpha: ['Равновесие', 'Сейчас твоя жизнь в относительном равновесии: то, как ты живёшь, и то, что тебе нужно, в основном совпадают. Это хорошее время, чтобы беречь то, что уже есть, и спокойно присматриваться к следующей ступени, без спешки и подвигов.'],\n  beta:  ['Смутное беспокойство', 'Сейчас ты скорее в состоянии смутного беспокойства: чувствуешь, что что-то не так, но трудно назвать, что именно и куда двигаться. Это нормальный и даже нужный этап: именно с него начинаются перемены. Важно не застрять в нём надолго, а превратить «что-то не так» в ясный вопрос.'],\n  gamma: ['Тупик', 'Сейчас ты, похоже, в тупике: уже понятно, что не так, но кажется, что выхода нет. Хочется, а не получается; стараешься, а сдвигов нет. Отсюда раздражение, бессилие, желание всё бросить. Это самое трудное место на пути, и одной из него выбираться тяжелее всего. Обычно выход начинается с того, что барьер называют по имени.'],\n  delta: ['Сдвиг', 'Сейчас ты, похоже, на пороге сдвига: желание, внимание и опора смотрят в одну сторону. Это время, когда маленькие шаги дают заметный результат. Важно поддержать этот момент, чтобы энергия не рассеялась.']\n};\nfunction moveState(r, gaps, G){\n  const fails = r.st.filter(x => x === 0).length, maxGap = Math.max(...gaps), stay = ctx.stay;\n  const cLevel = r.c + 1, oLevel = r.top === 'horizon' ? 8 : r.o + 1;\n  if (fails === 0 && maxGap <= 15 && stay === 0) return 'alpha';\n  if (fails <= 1 && !r.top && G === r.o && cLevel <= oLevel + 1 && cLevel >= oLevel - 1 && (stay === 0 || stay === 1)) return 'delta';\n  if (fails >= 1 && (maxGap >= 30 || r.trap)) return 'gamma';\n  return 'beta';\n}\nfunction stopsAndDrives(r, gaps, G){\n  const stops = [], drives = [];\n  const lowFail = r.st.findIndex(x => x === 0);\n  if (lowFail >= 0 && lowFail <= 1) stops.push(['Силы уходят на нижние ступени', `Ступень «${LV[lowFail].name}» просит заботы, а пока она не держит, почти все силы уходят на то, чтобы держаться. Прежде чем идти выше, телу и сердцу нужна опора.`]);\n  if (Math.max(...gaps) <= 10) stops.push(['Нет ясной цели', 'То, куда тебе хочется, почти совпадает с тем, что есть. Без ощущения «хочу иначе» перемены не начинаются. Иногда это усталость, а иногда тихий запрет хотеть. Ясную цель можно найти, и с этого стоит начать.']);\n  else if (!goalText.some(t => t && t.trim())) stops.push(['Цель пока размыта', 'Ты отметила, насколько хочешь укрепить ступени, но не описала словами, как это будет выглядеть. Когда непонятно, как выглядит «получилось», трудно сделать первый шаг.']);\n  if (!r.top){\n    const w = r.weak;\n    stops.push([['Барьер внутри: чувства', 'Барьер внутри: что-то не так в делах', 'Барьер снаружи: обстоятельства', 'Барьер в мыслях: убеждения'][w],\n      ['Главный барьер на твоей ступени — чувства: стыд, страх, усталость. Ты многое знаешь и умеешь, но внутри что-то тормозит. Здесь помогает не ещё одна инструкция, а бережное внимание к себе.',\n       'Главный барьер на твоей ступени — в делах: знаешь, что нужно, но шагов пока нет. Помогают очень маленькие, регулярные действия и кто-то рядом, кто напомнит.',\n       'Главный барьер на твоей ступени — снаружи: не хватает людей, условий, ресурсов. Это не твоя вина. Здесь важно отделить, что можно изменить, а что пока придётся обойти.',\n       'Главный барьер на твоей ступени — в мыслях: «я не имею права», «я не смогу», «уже поздно». Такие убеждения звучат как правда, но это только привычные мысли, и их можно пересмотреть.'][w]]);\n  }\n  if (ctx.stay === 2 || ctx.stay === 4) stops.push(['Горизонт не ясен', ctx.stay === 2 ? 'Ты ещё не решила, остаться ли. Пока вопрос открыт, трудно вкладываться в долгие цели: язык, дело, друзей.' : 'Решение остаться или уехать зависит не только от тебя. Неопределённость, которую задают другие, отнимает много сил.']);\n  if (r.st[1] < 2) stops.push(['Мало поддержки', 'Перемены требуют опоры: людей, которые поддержат, когда страшно или не получается. Когда своих мало, даже хорошая цель гаснет на полпути.']);\n  r.st.forEach((x, k) => { if (x === 2 && drives.length < 2) drives.push(LV[k].name); });\n  return { stops: stops.slice(0, 3), drives };\n}\nfunction pathBlocks(r, A, PDF){\n  const { cur, goal, gaps, G } = A, maxGap = gaps[G];\n  const texts = goalText.map((t, k) => [k, (t || '').trim()]).filter(x => x[1]);\n  const allTen = goals.every(g => g === 10), noRise = maxGap <= 10;\n  let gapTxt;\n  if (noRise) gapTxt = 'Похоже, сейчас тебе трудно сказать, куда хочется. Цели почти совпадают с тем, что есть. Так бывает, когда сил хватает только на сегодня, или когда хотеть кажется опасным: вдруг не получится. Это тоже важная находка. Ясная цель не появляется сама, её можно найти, и это первое, чем мы могли бы заняться вместе.';\n  else gapTxt = `Самое большое расстояние на ступени «${LV[G].name}»: сейчас ${cur[G]}%, а хочется ${goal[G]}%.`\n    + (G === r.o && !r.top ? ' И это та же ступень, с которой стоит начать. Желание и опора смотрят в одну сторону, а это очень хороший знак: силы пойдут туда, где они нужнее всего.'\n      : G > r.o && !r.top ? ` Но под ней пока просит заботы ступень «${LV[r.o].name}». Часто именно поэтому движение не получается: хочется наверх, а силы уходят на то, чтобы удержаться внизу.`\n      : ' Эта ступень ниже той, на которой ты стоишь, и это мудро: ты чувствуешь, что опору стоит укрепить.');\n  { const big = gaps.map((g, k) => [g, k]).filter(([g]) => g >= 20).sort((a, b) => b[0] - a[0]);\n    if (big.length > 1) gapTxt += ' Заметно укрепить тебе хочется ' + joinRu(big.slice(0, 3).map(([g, k]) => `${nm(k)} (с ${cur[k]} до ${goal[k]}%)`)) + '.';\n    const lower = gaps.map((g, k) => [g, k]).filter(([g]) => g <= -20);\n    if (lower.length) gapTxt += ` А ступень ${joinRu(lower.map(([g, k]) => nm(k)))} сейчас крепче, чем тебе нужно: возможно, на неё уходит больше сил, чем хочется, и их можно освободить для другого.`;\n    const ownGoal = !r.top && goalText[r.o] && goalText[r.o].trim();\n    if (ownGoal) gapTxt += ` На своей ступени ты сама написала: «${esc(goalText[r.o].trim())}». Сохрани эти слова, с них удобно начать.`; }\n  if (allTen) gapTxt += ' А ещё тебе хочется, чтобы все ступени были крепкими на десять. Это очень понятное желание, но всё сразу почти никогда не получается. Хорошая цель — одна, и она достижима за несколько месяцев.';\n  const B = [];\n  const goalsBox = texts.length ? `<div class=\"st-goals\"><b>Твои слова о цели</b>${texts.map(([k, t]) => `<p style=\"--l:${LV[k].line}\"><span>${LV[k].name}</span>${esc(t)}</p>`).join('')}</div>` : '';\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Где ты сейчас и куда хочется</div><h2>Три колеса твоей жизни</h2>\n    <p>Те же семь ступеней по кругу. Чем длиннее лепесток, тем крепче ступень. Первое колесо — где ты сейчас, по ответам теста. Второе — куда тебе хочется, по твоим целям. Третье показывает оба сразу: расстояние между закрашенным лепестком и пунктиром и есть твой путь.</p>\n    <div class=\"st-wheels3\"><figure class=\"both\">${wheelSVG(cur, goal)}<figcaption>Вместе: сейчас и хочется</figcaption></figure><figure>${wheelSVG(cur)}<figcaption>Где ты сейчас</figcaption></figure><figure>${wheelSVG(goal)}<figcaption>Куда хочется</figcaption></figure></div>\n    ${WHEEL_LEGEND}</div>` });\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Твой путь</div><h2>Разница между «сейчас» и «хочется»</h2><p>${gapTxt}</p>${goalsBox}</div>` });\n  const ms = A.ms;\n  const sd = stopsAndDrives(r, gaps, G), ST = STAY_TXT[ctx.stay ?? 2];\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Остаться или нет</div><h2>${ST[0]}</h2><p>${ST[1]}</p>\n    ${(ctx.stay === 1 || ctx.stay === 2) && r.st[6] < 2 ? `<p class=\"st-soft\">Это перекликается с твоей седьмой ступенью «Вид с холма»: пока решение не закрыто, жизнь легко остаётся черновиком. Часто помогает не решить окончательно, а записать честно, что держит здесь и что тянет туда.</p>` : ''}</div>` });\n  B.push({ html: `<div class=\"blk st-hold\"><div class=\"eyebrow\">Куда ты движешься</div><h2>Сейчас твоё состояние: ${STATES[ms][0].toLowerCase()}</h2>\n    <p>${STATES[ms][1]}</p>\n    <div class=\"st-states\">${['alpha','beta','gamma','delta'].map(k => `<span class=\"${k === ms ? 'on' : ''}\">${STATES[k][0]}</span>`).join('<i>→</i>')}</div>\n    <p class=\"note\">Создатели спиральной динамики Дон Бек и Кристофер Кован описали, что люди меняются не по прямой, а по кругу: от равновесия через смутное беспокойство и тупик к сдвигу и новому равновесию, уже на ступень выше. Каждое состояние нормально, важно не застрять.</p>\n    ${sd.drives.length ? `<p><b>Что тебя уже держит и двигает:</b> ${sd.drives.map(n => `ступень «${n}»`).join(' и ')}${ctx.stay === 0 ? ', и твоё решение остаться' : ''}. На это можно опираться.</p>` : ''}\n    <h3>Что тебя сейчас останавливает</h3>\n    <div class=\"st-stops\">${sd.stops.map(([h, t]) => `<div><b>${h}</b><p>${t}</p></div>`).join('')}</div>\n    <p>Всё это не приговор. По Беку и Ковану, перемена случается, когда есть силы, ощущение «так больше не хочу», ясность, куда идти, названный барьер и поддержка рядом. Каждое из этих условий можно создать, и работать с ними можно бережно.</p></div>` });\n  B.push({ html: `<div class=\"blk st-together\"><div class=\"eyebrow\">Путь, который можно пройти вместе</div><h2>${myName ? esc(myName) + ', это' : 'Это'} твой путь от одного колеса к другому</h2>\n    <p>Его можно пройти одной. А можно вместе, в партнёрстве. В коучинге я не даю советов и не решаю за тебя. Я работаю на глубине, через эмоциональный интеллект. Мы вместе находим, что держит именно тебя, превращаем «хочу, чтобы было хорошо» в ясную цель, которая по-настоящему твоя, и идём к ней маленькими шагами в твоём темпе, опираясь на ступени, которые у тебя уже крепкие.</p>\n    <p>На встрече-знакомстве, 30 минут онлайн, мы познакомимся, вместе посмотрим на твои колёса, проговорим твой запрос и поймём, насколько я могу быть тебе полезна. Как записаться — сразу ниже.</p></div>` });\n  return B;\n}\nfunction swissHtml(r, country){\n  if (country && country !== 'Швейцария') return '';\n  const head = country ? 'Для жизни в Швейцарии' : 'Если ты живёшь в Швейцарии';\n  const lead = !r.top && r.o === 3 ? 'Сейчас больше всего сил забирает ступень «Карта и ключи». Часть этой нагрузки можно снять прямо сегодня.' : 'Маленькая опора для ступени «Карта и ключи».';\n  return `<div class=\"blk swiss-guide\"><div class=\"eyebrow\">${head}</div><h2>Гайд по Швейцарии — Swiss Guide</h2>\n    <p>${lead} Это мой бесплатный Telegram-бот на русском. В нём собраны ответы на практические вопросы о жизни в Швейцарии: документы и разрешения, страховки, налоги, школа, жильё, письма из общины и неписаные правила. Чтобы силы оставались на то, что важно именно тебе.</p>\n    <div class=\"invite-links\"><a href=\"https://t.me/swisscompass_bot\" target=\"_blank\" rel=\"noopener\">Открыть бот: @swisscompass_bot</a></div></div>`;\n}\n\n/* ---------- индивидуальные интерпретации ---------- */\nconst GR_DESC = [\n  ['силы и самочувствие', 'сон, еда и режим', 'свой угол и спокойные деньги', 'разрешение себе отдыхать'],\n  ['тепло с людьми', 'умение звать и встречаться', 'свои люди рядом', 'чувство «я своя»'],\n  ['уверенность внутри', 'самостоятельные действия', 'уважение окружающих', 'право на своё'],\n  ['спокойствие перед письмами', 'порядок в бумагах', 'надёжный источник ответов', 'понимание здешних правил'],\n  ['спокойствие, когда говоришь о себе', 'шаги к своему делу', 'свои деньги и признание', 'знание своей цены'],\n  ['радость от отдачи', 'умение говорить «нет»', 'круг, где ты соавтор', 'понимание, ради чего'],\n  ['чувство, что живёшь свою жизнь', 'смелость не откладывать «на потом»', 'дом, который ощущается твоим', 'мир с решением уехать']\n];\nconst nm = k => `«${LV[k].name}»`;\nconst joinRu = a => a.length < 2 ? a.join('') : a.slice(0, -1).join(', ') + ' и ' + a[a.length - 1];\nfunction ladderPattern(r){\n  const st = r.st, fails = st.map((x, k) => x === 0 ? k : -1).filter(k => k >= 0), holds = st.map((x, k) => x === 2 ? k : -1).filter(k => k >= 0), shaky = st.map((x, k) => x === 1 ? k : -1).filter(k => k >= 0);\n  if (!fails.length && !shaky.length) return 'Все семь ступеней под тобой держат. Это редкая и очень взрослая картина: у тебя есть силы, свои люди, голос, порядок, дело, отдача и ощущение, что это твоя жизнь. Теперь вопрос уже не в ремонте, а в том, куда расти дальше.';\n  if (fails.some(k => k <= 2) && holds.filter(k => k >= 4).length >= 2) return `У твоей лестницы необычная форма: наверху многое держится (${joinRu(holds.filter(k => k >= 4).map(nm))}), а внизу просит заботы ${joinRu(fails.filter(k => k <= 2).map(nm))}. Так часто бывает у сильных женщин, которые тащат на себе дело, семью и чужие заботы, а про свою базу забывают. Снаружи ты справляешься, но этот успех стоит на тонком полу, и рано или поздно тело или одиночество напоминают о себе. Укрепить низ — не шаг назад, а способ сохранить всё, что ты уже построила.`;\n  if (fails.length >= 4) return `Сейчас заботы просит сразу многое: ${joinRu(fails.map(nm))}. Если тебе тяжело, это объяснимо: переезд выбил сразу несколько опор, и держаться приходится почти без пола под ногами. Важно не пытаться чинить всё одновременно. Одна нижняя ступень, укреплённая по-настоящему, даст силы на следующую.`;\n  if (fails.length === 1) return `Почти вся твоя лестница держит, и только одна ступень, ${nm(fails[0])}, просит заботы${shaky.length ? `, а ${joinRu(shaky.map(nm))} немного ${shaky.length > 1 ? 'поскрипывают' : 'поскрипывает'}` : ''}. Это хорошая новость: у тебя много опоры, и на неё можно встать, чтобы подтянуть ту самую ступень.`;\n  if (!fails.length) return `Ни одна ступень у тебя не рушится, но ${joinRu(shaky.map(nm))} держатся, что называется, на честном слове. В обычную неделю ты справляешься, а в трудную именно эти ступени подводят первыми. Сейчас хорошее время укрепить их без спешки, пока нет кризиса.`;\n  return `Две-три ступени у тебя просят заботы: ${joinRu(fails.map(nm))}${holds.length ? `, зато ${joinRu(holds.map(nm))} крепко держат` : ''}. Начинать стоит с самой нижней из них — так каждая следующая встанет на крепкое.`;\n}\nfunction contextLines(r){\n  const o = r.top ? -1 : r.o, L = [];\n  if (o >= 0){\n    if (ctx.years === 0 && o >= 4) L.push('Ты здесь меньше года, а нижние ступени уже держат. Это большая работа, и её стоит признать.');\n    if (ctx.years === 1 && o <= 2) L.push(`Ты здесь уже больше года, а ступень ${nm(o)} всё ещё просит заботы. Так часто бывает на втором-третьем году: первая волна сил прошла, а новая опора ещё не выросла.`);\n    if (ctx.years >= 2 && o <= 3) L.push(`Ты здесь уже несколько лет, и всё же ступень ${nm(o)} не держит. Значит, дело не во времени: время само её не укрепит, нужен другой подход, и его можно найти.`);\n    if (ctx.how === 2 && o === 2) L.push('Когда переезжаешь к мужу, легко оказаться в роли той, за кого решают: язык, деньги, связи сначала у него. Голос возвращается, когда появляются дела, которые ты делаешь сама.');\n    if (ctx.how === 0 && o === 4) L.push('Когда переезд случился ради работы мужа или ради семьи, своё дело часто откладывается «на потом». Это понятно, но «потом» само не наступает.');\n    if (ctx.how === 1 && o === 1) L.push('Когда переезжаешь по работе, день заполнен, а своих людей нет: коллеги есть, близких нет. Это очень частая история, и круг здесь собирается не на работе.');\n    if ((ctx.stay === 2 || ctx.stay === 4) && o <= 3) L.push('Ты ещё не знаешь, надолго ли ты здесь, и это делает нижние ступени особенно шаткими: трудно обустраиваться, когда не уверена, стоит ли.');\n  }\n  return L;\n}\nfunction itemsOf(k){ return ITEMS[k].map((it, i) => ({ k, i, t: it[1], rev: !!it[2], a: ans[k][i], v: val(it, ans[k][i]) })); }\nfunction yourWords(r){\n  if (r.top) return '';\n  const own = itemsOf(r.o), low = [...own].sort((a, b) => a.v - b.v).slice(0, 2), high = [...own].sort((a, b) => b.v - a.v).filter(x => x.v >= 3).slice(0, 2);\n  const all = ITEMS.flatMap((_, k) => k === r.o ? [] : itemsOf(k)).filter(x => x.v === 4 && !x.rev);\n  const strong = all.sort((a, b) => a.k - b.k).filter((x, j, arr) => arr.findIndex(y => y.k === x.k) === j).slice(0, 3);\n  const q = x => `<div class=\"st-quote\" style=\"--l:${LV[x.k].line};--s:${LV[x.k].soft}\"><p>«${x.t.replace(/\\.$/, '')}»</p><span>твой ответ: ${LABELS[x.a]}</span></div>`;\n  return `<div class=\"blk\"><div class=\"eyebrow\">Твои собственные ответы</div><h2>Что ты сама о себе сказала</h2>\n    <p>Самые тихие места ступени ${nm(r.o)} — в этих фразах. Перечитай их: часто именно здесь прячется первый шаг.</p>\n    <div class=\"st-quotes\">${low.map(q).join('')}</div>\n    ${high.length ? `<p>А вот что на этой ступени у тебя уже получается, и на это можно опереться:</p><div class=\"st-quotes\">${high.map(q).join('')}</div>` : ''}\n    ${strong.length ? `<p>И твои сильные стороны на других ступенях:</p><div class=\"st-quotes\">${strong.map(q).join('')}</div>` : ''}</div>`;\n}\nfunction heartExample(r){\n  let best = null;\n  SITS.forEach((s, i) => s[1].forEach(([lv, t], j) => { if (lv === r.c && (!best || pts[i][j] > best.p)) best = { q: s[0], t, p: pts[i][j] }; }));\n  return best && best.p >= 4 ? `Например, в сценке «${best.q.replace(/[.?]$/, '')}» ты отдала ${best.p} из 10 баллов варианту «${best.t.replace(/\\.$/, '')}». Так звучит эта нота в твоей жизни.` : '';\n}\nfunction portrait(r, A){\n  const N = myName ? esc(myName) + ', с' : 'С';\n  const holds = r.st.map((x, k) => x === 2 ? k : -1).filter(k => k >= 0);\n  const parts = [];\n  parts.push(holds.length === 7 ? `${N}ейчас твоя опора — вся лестница, все семь ступеней.` : holds.length ? `${N}ейчас твоя опора — ${joinRu(holds.slice(0, 3).map(nm))}.` : `${N}ейчас ни одна ступень не держит в полную силу, и это честная точка, с которой можно начать.`);\n  if (!r.top) parts.push(`Начинать стоит со ступени ${nm(r.o)}: тише всего здесь ${GR_DESC[r.o][r.weak]}.`);\n  parts.push(r.c === r.o && !r.top ? `Твоё сердце звучит из этой же ступени.` : !r.top && r.c > r.o ? `Сердце уже смотрит выше, в ступень ${nm(r.c)}.` : `Сердце сейчас звучит из ступени ${nm(r.c)}.`);\n  if (A.gaps[A.G] > 10) parts.push(`Больше всего хочется укрепить ${nm(A.G)}.`);\n  const SP = ['Ты решила остаться', 'Ты скорее остаёшься, но иногда сомневаешься', 'Ты ещё не решила, остаться ли', 'Ты думаешь вернуться или уехать дальше', 'Решение остаться зависит не только от тебя'];\n  parts.push(`${ctx.stay != null ? SP[ctx.stay] + ', а с' : 'С'}ейчас ты ближе всего к состоянию «${STATES[A.ms][0].toLowerCase()}».`);\n  return parts.join(' ');\n}\nfunction guidePart(k){\n  const d = document.createElement('div'); d.innerHTML = GUIDE.levels[k].body;\n  const ps = [...d.children].filter(x => x.tagName === 'P');\n  const q = d.querySelector('blockquote');\n  return { voice: q ? q.innerHTML : '', rise: ps.length ? ps[ps.length - 1].innerHTML : '', gift: ps.length > 2 ? ps[ps.length - 2].innerHTML : '', ask: GUIDE.levels[k].ask };\n}\nfunction analysis(r){\n  const cur = r.pct, goal = goals.map(g => (g ?? 0) * 10);\n  const gaps = cur.map((v, k) => goal[k] - v), G = gaps.indexOf(Math.max(...gaps));\n  return { cur, goal, gaps, G, ms: moveState(r, gaps, G) };\n}\n\n/* ---------- разбор ---------- */\nfunction buildBlocks(){\n  const r = compute(); last = r;\n  const PDF = !!window.__PDF;\n  const N = esc(myName), date = new Date().toLocaleDateString(DATE_LOCALE, { day: 'numeric', month: 'long', year: 'numeric' });\n  const sk = r.top === 'horizon' ? 7 : r.o, L = LV[sk];\n  const country = window.__leadCountry || ((typeof loadLead === 'function' && loadLead()) || {}).country || '';\n  const guideHref = n => (typeof SITE_URL !== 'undefined' && SITE_URL ? SITE_URL.replace(/\\/?$/, '/') + 'stupeni/' : '') + '#guide-' + n;\n  const A = analysis(r); r.moveState = STATES[A.ms][0];\n  const B = []; wsReset();\n  const title = r.top === 'horizon' ? 'Небо над домом' : r.top === 'edge' ? `${r.o + 1} · ${LV[r.o].name}, у края неба` : lvName(r.o);\n  const tile = (lab, val, col) => `<div class=\"st-tile2\" style=\"--l:${col}\"><span>${lab}</span><b>${val}</b></div>`;\n\n  /* 1. Обложка: главное коротко */\n  B.push({ html: `<div class=\"blk st-cover\" style=\"--f:${L.fill};--l:${L.line};--s:${L.soft}\">\n      <div class=\"st-cover-top\"><div><div class=\"eyebrow\">Ступени устойчивости · разбор</div><div class=\"cover-slogan\">${TEST_META.slogan}</div>${N ? `<div class=\"names\">${N}</div>` : ''}\n        <p class=\"note\">${date} · в стране ${YEARS[ctx.years]} · ${STAY_SHORT[ctx.stay] || ''}</p></div>\n        <div class=\"st-cover-ico\">${lvIcon(sk, 64)}</div></div>\n      <p class=\"st-now\">Твоя ступень сейчас</p><h1 style=\"color:${L.line}\">${title}</h1>\n      <p class=\"st-portrait\">${portrait(r, A)}</p>\n      <div class=\"st-tiles2\">\n        ${r.top ? '' : tile('Самая тихая грань', GR[r.weak], L.line)}\n        ${tile('Громче всего в сердце', LV[r.c].name, LV[r.c].line)}\n        ${tile('Больше всего хочется', A.gaps[A.G] > 10 ? LV[A.G].name : 'пока не ясно', LV[A.G].line)}\n        ${tile('Состояние', STATES[A.ms][0], '#6E4F3C')}\n      </div></div>` });\n\n  /* 2. Лестница */\n  const yearLine = ctx.years === 0 && r.st.slice(0, 4).some(x => x === 0) ? FIRST_YEAR\n    : ctx.years === 3 && r.st[6] < 2 ? LONG_TIME : '';\n  B.push({ html: `<div class=\"blk st-ladder-blk\"><div class=\"eyebrow\">Твоя лестница</div>\n      <div class=\"st-two\"><div class=\"st-ladder\">${ladderSVG(r)}</div>\n      <div class=\"stack\" style=\"gap:10px\"><h2>${N ? N + ', вот' : 'Вот'} твоя лестница</h2>\n      <p>${ladderPattern(r)}</p>\n      <p class=\"note\"><b>Крепкая</b> — от 75%, <b>поскрипывает</b> — 50–74%, <b>здесь начинаем</b> — ниже 50%. Твоя ступень — самая нижняя, которая просит заботы: выше построить не получится.</p>\n      ${yearLine ? `<p class=\"st-soft\">${yearLine}</p>` : ''}</div></div></div>` });\n\n  /* 3. Твоя ступень подробно */\n  if (r.top){\n    const txt = r.top === 'horizon'\n      ? ['Все семь ступеней под тобой крепкие — и ты смотришь дальше своей жизни. Здесь нечего чинить: дом построен, и над ним небо.',\n         'Отсюда приходят те, кто потом открывает двери другим — наставницы, ведущие встреч, авторы. Если тебе откликается мысль «хочу, чтобы после меня что-то осталось», — давай поговорим.']\n      : ['Твоя лестница крепкая — все семь ступеней держат. Это много, и это твоя заслуга.',\n         'Следующий вопрос уже не про ремонт, а про высоту: что ты хочешь оставить после себя?'];\n    B.push({ html: `<div class=\"blk role-blk\" style=\"--c:${L.line};--cs:${L.soft}\">\n      <div class=\"role-head\"><div class=\"ico\">${lvIcon(sk, 26)}</div><h3>${title}</h3></div>\n      ${txt.map(p => `<p>${p}</p>`).join('')}\n      <div class=\"st-next\"><b>Что дальше</b><p>Здесь мини-продукта нет — и не должно быть. Дальше — разговор: «Карта целой жизни», личная программа «Ясный путь», наставничество.</p></div></div>` });\n  } else {\n    const R = RES[r.o], g = guidePart(r.o);\n    B.push({ html: `<div class=\"blk role-blk\" style=\"--c:${L.line};--cs:${L.soft}\">\n      <div class=\"role-head\"><div class=\"ico\">${lvIcon(r.o, 26)}</div><h3>Ступень ${title}</h3><span class=\"pill\" style=\"background:${L.line}\">${STATUS[r.st[r.o]]}</span><span class=\"sc\">${r.pct[r.o]}%</span></div>\n      ${R.main.map(p => `<p>${p}</p>`).join('')}\n      ${contextLines(r).map(t => `<p class=\"st-ctx\">${t}</p>`).join('')}\n      ${g.voice ? `<div class=\"st-voice\" style=\"--s:${L.soft}\"><span>Узнаёшь себя?</span>${g.voice}</div>` : ''}\n      ${r.o === 0 && ctx.how === 3 ? `<div class=\"st-soft\"><b class=\"st-h\">Если тебе пришлось уехать от войны или опасности</b><p>${REFUGEE}</p></div>` : ''}\n      </div>` });\n    B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Четыре грани ступени</div><h2>Где именно трещина</h2>\n      <p class=\"note\">У каждой ступени четыре грани: что ты чувствуешь, что делаешь, что есть вокруг тебя и во что ты веришь. Самая тихая грань подсказывает, откуда начать.</p>\n      ${graniHtml(r)}\n      <p>${(() => { const strong = [0,1,2,3].reduce((b, x) => r.gr[x] > r.gr[b] ? x : b, 0); return strong === r.weak || r.gr[strong] === r.gr[r.weak] ? `Все четыре грани у тебя звучат примерно одинаково: ступень просит заботы целиком, а не в одном месте.` : `Сильнее всего на этой ступени у тебя ${GR_DESC[r.o][strong]} (${GR[strong].toLowerCase()}), а тише всего ${GR_DESC[r.o][r.weak]} (${GR[r.weak].toLowerCase()}). Значит, опираться стоит на первое, чтобы подтянуть второе.`; })()}</p>\n      <div class=\"callout st-co\" style=\"--c:${L.line};border-color:${L.line};background:${L.soft}\"><h3>Самая тихая грань: ${GR[r.weak].toLowerCase()}</h3><p>${R.gr[r.weak]}</p></div>\n      ${r.extra >= 0 ? `<p class=\"st-soft\">Есть ещё одна ступень, которая просит заботы, — <b style=\"color:${LV[r.extra].line}\">«${LV[r.extra].name}»</b>. Мы до неё дойдём. Но начинать всё равно лучше снизу: так каждая следующая ступень встанет на крепкое.</p>` : ''}\n      </div>` });\n    B.push({ html: yourWords(r) });\n    B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Как подняться выше</div><h2>Что поможет на этой ступени</h2>\n      <p>${g.rise}</p>\n      <div class=\"steps\">\n      <div><span class=\"num\" style=\"background:${L.line}\">1</span><div><b>Шаг на эту неделю</b><p>${R.step}</p></div></div>\n      <div><span class=\"num\" style=\"background:${L.line}\">2</span><div><b>Что дальше: ${R.product}</b><p>${R.productText}</p></div></div>\n      <div><span class=\"num\" style=\"background:${L.line}\">3</span><div><b>Через 4–6 недель</b><p>Пройди тест снова и посмотри, как изменилась твоя лестница.</p></div></div>\n      </div></div>` });\n    wsStep(R.step); wsStep('Что дальше: ' + R.product + '. ' + R.productText);\n    wsAdd('Пять вопросов себе', 'Ступень «' + LV[r.o].name + '»', liTexts(g.ask), 6);\n    B.push({ html: `<div class=\"blk st-askblk\" style=\"--l:${L.line}\"><div class=\"eyebrow\">Возьми ручку</div><h2>Пять вопросов себе</h2>\n      <p class=\"note\">Ответь письменно, не торопясь. Ещё больше про ступень «${LV[r.o].name}» — в путеводителе. <button type=\"button\" class=\"linkbtn screen-only\" data-guide=\"${r.o + 1}\">Открыть путеводитель →</button><a class=\"pdf-only\" href=\"${guideHref(r.o + 1)}\">Путеводитель на сайте →</a></p>\n      <div class=\"st-ask\">${g.ask}</div></div>` });\n    B.push({ html: wsNoteHtml() });\n  }\n\n  { const sw = swissHtml(r, country); if (sw) B.push({ float: true, html: sw }); }\n\n  /* 4. Все ступени: описание каждой */\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Все семь ступеней</div><h2>Как держит каждая ступень</h2>\n    <div class=\"st-list\">${ITEMS.map((_, k) => `<div class=\"st-li${k === r.o && !r.top ? ' me' : ''}\" style=\"--l:${LV[k].line};--s:${LV[k].soft}\">\n      <span class=\"st-ico\">${lvIcon(k, 22)}</span><div><b>${lvName(k)} <small>· ${STATUS[r.st[k]]}</small></b><span>${STEP_LINE[k][r.st[k]]}</span></div><em>${r.pct[k]}%</em></div>`).join('')}</div></div>` });\n\n  /* 5. Сердце */\n  const C = LV[r.c], comboTxt = {\n    same: 'Ты думаешь и решаешь из той ступени, на которой стоишь, — или уже заглядываешь на следующую. Это самый естественный рост: ноги и взгляд идут вместе.',\n    above: `Твоё сердце уже наверху — там, где «${C.name}». А ступень «${LV[Math.min(r.oLevel, 8) - 1].name}» под ногами пока просит заботы. Это не противоречие, а подсказка: укрепи ступень — и верх станет твоим по-настоящему, а не через силу.`,\n    below: `Опора у тебя крепче, чем тебе кажется: ступени до «${LV[Math.min(r.oLevel, 8) - 1].name}» держат. А сердце сейчас вернулось вниз — к ступени «${C.name}». Так бывает после трудного периода, болезни, большой усталости. Это не откат, а сигнал: позаботься о себе.`\n  }[r.combo];\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Откуда звучит твоё сердце</div><h2>Профиль сердца</h2>\n    <p>Первая часть показала, на чём ты стоишь. Ситуации показывают другое: из какой ступени ты сейчас думаешь, решаешь и мечтаешь. Это как музыка: звучат все восемь нот, но одна сейчас громче остальных.</p>\n    <div class=\"st-two st-two-heart\"><div class=\"st-heart\">${heartSVG(r)}</div>\n    <div class=\"stack\" style=\"gap:10px\"><div class=\"callout st-co\" style=\"--c:${C.line};border-color:${C.line};background:${C.soft}\"><h3>Громче всего: ${C.name.toLowerCase()}${r.c2 !== null ? ` и ${LV[r.c2].name.toLowerCase()}` : ''}</h3>\n      <p>${r.c2 !== null ? `Сейчас в тебе почти одинаково звучат «${C.name}» и «${LV[r.c2].name}». Ты как будто между двумя нотами — так бывает, когда что-то меняется.` : HEART[r.c]}</p></div>\n    <p>${comboTxt}</p>${heartExample(r) ? `<p class=\"st-ctx\">${heartExample(r)}</p>` : ''}</div></div>\n    <p class=\"note\">Тише всего сейчас звучит «${LV[r.quiet].name}». Это не плохо и не хорошо — просто эта нота пока почти не слышна в твоих решениях. Иногда стоит спросить себя, не скучаешь ли ты по ней.</p>\n    ${r.trap ? `<div class=\"st-soft\"><b class=\"st-h\">Бережное наблюдение</b><p>${TRAPS[r.trap]}</p></div>` : ''}</div>` });\n\n  /* 6. Цель, колёса, остаться, движение, путь вместе */\n  pathBlocks(r, A, PDF).forEach(b => B.push(b));\n\n  B.push({ html: inviteHtml({ name: myName, country: window.__leadCountry || '', interest: surveyAnswers().interest,\n                              focus: { coach: LV[sk].focus, psy: 'в отношениях стало больше тепла и понимания' } }) });\n  B.push({ float: true, html: channelHtml(window.__leadCountry || country) });\n  B.push({ html: `<div class=\"blk st-final\" style=\"--s:${L.soft}\"><h2>${N ? N + ', запомни' : 'Запомни'} главное</h2>\n    <p>Лестница, которую ты видишь, — не приговор и не оценка. Это снимок сегодняшнего дня. Через месяц он будет другим, через год — совсем другим. Каждая ступень, которую ты укрепишь, сделает крепче всё, что выше.</p>\n    <p>Ты уже прошла больше, чем тебе кажется. Дом строится. И ты в нём — хозяйка.</p></div>` });\n  B.push({ float: true, html: `<div class=\"blk testinfo\"><div class=\"eyebrow\">Об этом опроснике</div><p>${TEST_INFO.why}</p>${PDF ? '' : abHtml()}</div>` });\n  B.push({ float: true, html: moreTestsHtml(TEST_META.id) });\n  B.push({ html: authorHtml() });\n  B.push({ html: disclaimerHtml() });\n  r.title = title;\n  if (!WS.sections.length) { wsAdd('Пять вопросов себе', 'Ступень «' + LV[sk].name + '»', liTexts(guidePart(sk).ask), 6); B.splice(Math.max(1, B.length - 3), 0, { float: true, html: wsNoteHtml() }); }\n  return B;\n}\nfunction showResult(){\n  finished = true; save(); renderResume();\n  $('report').innerHTML = buildBlocks().map(b => b.html).join('');\n  $('quiz').hidden = true; $('result').hidden = false; window.scrollTo(0, 0);\n}\n\n/* ---------- связь с общей анкетой ---------- */\nconst LEAD_HOOKS = {\n  personName: () => myName,\n  fileBase: () => 'Vosem_stupenej',\n  fileNames: () => myName ? [myName] : [],\n  payload: () => {\n    const r = last, scores = {};\n    ITEMS.forEach((_, k) => scores[`${k + 1} ${LV[k].name}, %`] = r.pct[k]);\n    if (r.skySum !== null) scores['8 Небо (бонус, из 24)'] = r.skySum;\n    LV.forEach((l, k) => scores[`Сердце: ${l.name}, %`] = r.hp[k]);\n    ITEMS.forEach((_, k) => scores[`Цель ${k + 1} ${LV[k].name} (0–10)`] = goals[k]);\n    return { result: r.title,\n      scores,\n      notes: `как приехала: ${HOW[ctx.how]}; остаться: ${STAY_SHORT[ctx.stay] || '—'}; состояние: ${last.moveState || '—'}; в стране: ${YEARS[ctx.years]}; слабая грань: ${r.top ? '—' : GR[r.weak]}; сердце: ${LV[r.c].name}${r.c2 !== null ? ' + ' + LV[r.c2].name : ''}; сочетание: ${r.combo}; ловушка: ${r.trap || 'нет'}; цели: ${goalText.map((t, k) => t && t.trim() ? LV[k].name + ' — ' + t.trim() : '').filter(Boolean).join(' | ') || '—'}` };\n  }\n};\n\n/* ---------- «продолжить с того места» ---------- */\nfunction renderResume(){\n  const box = $('stResume'); if (!box) return;\n  const v = loadSaved();\n  if (!v){ box.hidden = true; box.innerHTML = ''; return; }\n  const when = new Date(v.t).toLocaleDateString(DATE_LOCALE, { day: 'numeric', month: 'long' });\n  const answered = (v.ctx.how !== null) + (v.ctx.years !== null) + (v.ctx.stay != null) + v.ans.flat().filter(x => x !== null).length + v.pts.filter(p => sum(p) === 10).length;\n  box.hidden = false;\n  box.innerHTML = v.finished\n    ? `<div><b>${v.myName ? esc(v.myName) + ', т' : 'Т'}вой разбор от ${when} сохранён</b><p>Можно открыть его снова или пройти тест заново, например через несколько недель, чтобы увидеть, как изменилась лестница.</p></div>\n       <div class=\"st-resume-btns\"><button type=\"button\" class=\"btn\" id=\"resOpen\">Открыть мой разбор</button><button type=\"button\" class=\"btn ghost\" id=\"resNew\">Пройти заново</button></div>`\n    : `<div><b>${v.myName ? esc(v.myName) + ', т' : 'Т'}ы уже начинала тест ${when}</b><p>Твои ответы сохранились: отвечено ${answered} из ${3 + 56 + SITS.length + 7}. Можно продолжить с того места, где ты остановилась.</p></div>\n       <div class=\"st-resume-btns\"><button type=\"button\" class=\"btn\" id=\"resGo\">Продолжить</button><button type=\"button\" class=\"btn ghost\" id=\"resNew\">Начать заново</button></div>`;\n  const go = $('resGo'), open = $('resOpen');\n  if (go) go.addEventListener('click', () => { restore(loadSaved()); resetInvite(); $('intro').hidden = true; $('quiz').hidden = false; renderStep(); window.scrollTo(0, 0); });\n  if (open) open.addEventListener('click', () => { restore(loadSaved()); resetInvite(); showResult(); });\n  $('resNew').addEventListener('click', () => { forget(); renderResume(); showPart('testPrep'); $('testPrep').scrollIntoView({ behavior: 'smooth', block: 'start' }); });\n}\nrenderResume();\n\n/* полоса сверху страниц PDF — в цветах ступеней */\ndocument.documentElement.style.setProperty('--pdf-strip', 'linear-gradient(90deg,' + LV.map(l => l.fill).join(',') + ')');\n", "/* =====================================================================\n   PDF разбора и бланка, форма «Хочешь получать мои материалы?», отправка в Google Таблицу.\n   С 02.10.2026: PDF скачивается сразу, без анкеты. Результаты теста в таблицу НЕ уходят.\n   В таблицу уходят: анонимная запись при скачивании PDF (тест, дата, язык, страна, источник, мини-опрос)\n   и — только если человек сам заполнил форму — его контакты (без результатов).\n   Тест задаёт: TEST_META {id, name}, buildBlocks(), showResult(), LEAD_HOOKS.\n   Страны и PAGE_LANG — в privacy.js. Тексты на четырёх языках — здесь же (LT).\n   ===================================================================== */\nconst LT_ALL = {\n  ru: {\n    dlTitle1: 'Скачать разбор', dlText1: 'Красивый PDF с разбором без вопросов теста: картинки, описания, рекомендации, план на 4 недели и вопросы для размышления.', dlBtn1: 'Скачать разбор',\n    dlTitle: 'Скачать разбор и бланк для записей',\n    dlText: 'Красивый PDF с разбором без вопросов теста: картинки, описания, рекомендации, план на 4 недели и вопросы для размышления. Вместе с ним скачается бланк для записей со всеми вопросами из разбора, чтобы распечатать его и ответить своей рукой.',\n    dlBtn: 'Скачать разбор и бланк', again: 'Пройти заново',\n    wsTitle: 'Бланк для записей', wsText: 'Все вопросы и шаги из твоего разбора с местом для ответов. Его можно распечатать и заполнить от руки.', wsBtn: 'Скачать бланк',\n    matEyebrow: 'По желанию', matTitle: 'Хочешь получать мои материалы?',\n    matText: 'Оставь имя и e-mail, и я буду присылать полезные материалы и рассказывать о новых тестах. Твои ответы на тест остаются только у тебя: мне придут лишь данные из этой формы.',\n    name: 'Имя *', email: 'E-mail *', contact: 'Telegram или WhatsApp', contactPh: '@username или +41 …',\n    consent: link => `Я соглашаюсь, что Ирина Вознесенская получит данные из этой формы, как описано в ${link} *`, consentLink: 'Политике конфиденциальности',\n    news: 'Хочу получать письма с полезными материалами. Отписаться можно в любой момент.',\n    adult: 'Мне есть 18 лет *', send: 'Отправить',\n    errName: 'Напиши, пожалуйста, своё имя.', errEmail: 'Проверь e-mail: похоже, в нём ошибка.', errConsent: 'Чтобы отправить форму, нужно согласие.', errAdult: 'Этот тест предназначен для людей от 18 лет.',\n    sent: 'Спасибо! Данные отправлены.', sendFail: 'Не получилось отправить. Проверь интернет и попробуй ещё раз.',\n    noLib: 'Не получилось загрузить модуль PDF. Проверь интернет и обнови страницу.',\n    making: 'Готовлю PDF…', madeMain: 'Разбор сохранён. Готовлю бланк для записей…',\n    madeBoth: 'Готово! Сохранены два файла: разбор и бланк для записей. Если они не открылись, загляни в папку «Загрузки».',\n    madeOne: 'Разбор сохранён. Если он не открылся, загляни в папку «Загрузки».',\n    madeWsLater: 'Разбор сохранён. Бланк для записей можно скачать кнопкой ниже.',\n    wsMaking: 'Готовлю бланк…', wsDone: 'Бланк сохранён. Распечатай его и пиши от руки.', wsFail: 'Не получилось подготовить бланк. Попробуй ещё раз.',\n    cancel: 'Сохранение отменено.', fail: 'Не получилось подготовить PDF. Попробуй ещё раз.',\n    wsFile: 'Бланк для записей', wsFoot: ' · бланк для записей'\n  },\n  uk: {\n    dlTitle1: 'Завантажити розбір', dlText1: 'Гарний PDF із розбором без питань тесту: малюнки, описи, рекомендації, план на 4 тижні та питання для роздумів.', dlBtn1: 'Завантажити розбір',\n    dlTitle: 'Завантажити розбір і бланк для записів',\n    dlText: 'Гарний PDF із розбором без питань тесту: малюнки, описи, рекомендації, план на 4 тижні та питання для роздумів. Разом із ним завантажиться бланк для записів з усіма питаннями з розбору, щоб роздрукувати його й відповісти від руки.',\n    dlBtn: 'Завантажити розбір і бланк', again: 'Пройти знову',\n    wsTitle: 'Бланк для записів', wsText: 'Усі питання та кроки з твого розбору з місцем для відповідей. Його можна роздрукувати й заповнити від руки.', wsBtn: 'Завантажити бланк',\n    matEyebrow: 'За бажанням', matTitle: 'Хочеш отримувати мої матеріали?',\n    matText: 'Залиш ім’я та e-mail, і я надсилатиму корисні матеріали та розповідатиму про нові тести. Твої відповіді на тест залишаються тільки в тебе: мені прийдуть лише дані з цієї форми.',\n    name: 'Ім’я *', email: 'E-mail *', contact: 'Telegram або WhatsApp', contactPh: '@username або +380 …',\n    consent: link => `Я погоджуюся, що Ірина Вознесенська отримає дані з цієї форми, як описано в ${link} *`, consentLink: 'Політиці конфіденційності',\n    news: 'Хочу отримувати листи з корисними матеріалами. Відписатися можна будь-коли.',\n    adult: 'Мені є 18 років *', send: 'Надіслати',\n    errName: 'Напиши, будь ласка, своє ім’я.', errEmail: 'Перевір e-mail: схоже, у ньому помилка.', errConsent: 'Щоб надіслати форму, потрібна згода.', errAdult: 'Цей тест призначений для людей від 18 років.',\n    sent: 'Дякую! Дані надіслано.', sendFail: 'Не вдалося надіслати. Перевір інтернет і спробуй ще раз.',\n    noLib: 'Не вдалося завантажити модуль PDF. Перевір інтернет і онови сторінку.',\n    making: 'Готую PDF…', madeMain: 'Розбір збережено. Готую бланк для записів…',\n    madeBoth: 'Готово! Збережено два файли: розбір і бланк для записів. Якщо вони не відкрилися, зазирни в папку «Завантаження».',\n    madeOne: 'Розбір збережено. Якщо він не відкрився, зазирни в папку «Завантаження».',\n    madeWsLater: 'Розбір збережено. Бланк для записів можна завантажити кнопкою нижче.',\n    wsMaking: 'Готую бланк…', wsDone: 'Бланк збережено. Роздрукуй його й пиши від руки.', wsFail: 'Не вдалося підготувати бланк. Спробуй ще раз.',\n    cancel: 'Збереження скасовано.', fail: 'Не вдалося підготувати PDF. Спробуй ще раз.',\n    wsFile: 'Бланк для записів', wsFoot: ' · бланк для записів'\n  },\n  de: {\n    dlTitle1: 'Auswertung herunterladen', dlText1: 'Ein schönes PDF mit deiner Auswertung, ohne die Testfragen: Bilder, Beschreibungen, Empfehlungen, ein Plan für 4 Wochen und Fragen zum Nachdenken.', dlBtn1: 'Auswertung herunterladen',\n    dlTitle: 'Auswertung und Notizblatt herunterladen',\n    dlText: 'Ein schönes PDF mit deiner Auswertung, ohne die Testfragen: Bilder, Beschreibungen, Empfehlungen, ein Plan für 4 Wochen und Fragen zum Nachdenken. Dazu wird ein Notizblatt mit allen Fragen aus der Auswertung heruntergeladen, zum Ausdrucken und Ausfüllen von Hand.',\n    dlBtn: 'Auswertung und Notizblatt herunterladen', again: 'Noch einmal machen',\n    wsTitle: 'Notizblatt', wsText: 'Alle Fragen und Schritte aus deiner Auswertung mit Platz für deine Antworten. Zum Ausdrucken und Ausfüllen von Hand.', wsBtn: 'Notizblatt herunterladen',\n    matEyebrow: 'Freiwillig', matTitle: 'Möchtest du meine Materialien erhalten?',\n    matText: 'Hinterlasse deinen Namen und deine E-Mail, dann schicke ich dir hilfreiche Materialien und erzähle dir von neuen Tests. Deine Antworten im Test bleiben nur bei dir: Ich erhalte nur die Angaben aus diesem Formular.',\n    name: 'Name *', email: 'E-Mail *', contact: 'Telegram oder WhatsApp', contactPh: '@username oder +41 …',\n    consent: link => `Ich bin einverstanden, dass Iryna Voznesenskaya die Angaben aus diesem Formular erhält, wie in der ${link} beschrieben *`, consentLink: 'Datenschutzerklärung',\n    news: 'Ich möchte E-Mails mit hilfreichen Materialien erhalten. Abmelden ist jederzeit möglich.',\n    adult: 'Ich bin mindestens 18 Jahre alt *', send: 'Senden',\n    errName: 'Bitte gib deinen Namen ein.', errEmail: 'Bitte prüfe deine E-Mail-Adresse.', errConsent: 'Zum Senden brauche ich dein Einverständnis.', errAdult: 'Dieser Test ist für Personen ab 18 Jahren.',\n    sent: 'Danke! Deine Angaben wurden gesendet.', sendFail: 'Das Senden hat nicht geklappt. Prüfe deine Internetverbindung und versuche es noch einmal.',\n    noLib: 'Das PDF-Modul konnte nicht geladen werden. Prüfe deine Internetverbindung und lade die Seite neu.',\n    making: 'PDF wird erstellt…', madeMain: 'Auswertung gespeichert. Das Notizblatt wird erstellt…',\n    madeBoth: 'Fertig! Zwei Dateien wurden gespeichert: die Auswertung und das Notizblatt. Falls sie sich nicht geöffnet haben, schau im Ordner «Downloads» nach.',\n    madeOne: 'Auswertung gespeichert. Falls sie sich nicht geöffnet hat, schau im Ordner «Downloads» nach.',\n    madeWsLater: 'Auswertung gespeichert. Das Notizblatt kannst du unten herunterladen.',\n    wsMaking: 'Notizblatt wird erstellt…', wsDone: 'Notizblatt gespeichert. Druck es aus und schreib von Hand.', wsFail: 'Das Notizblatt konnte nicht erstellt werden. Versuche es noch einmal.',\n    cancel: 'Speichern abgebrochen.', fail: 'Das PDF konnte nicht erstellt werden. Versuche es noch einmal.',\n    wsFile: 'Notizblatt', wsFoot: ' · Notizblatt'\n  },\n  en: {\n    dlTitle1: 'Download your results', dlText1: 'A beautiful PDF with your results, without the test questions: pictures, descriptions, recommendations, a 4-week plan and questions to reflect on.', dlBtn1: 'Download results',\n    dlTitle: 'Download your results and notes sheet',\n    dlText: 'A beautiful PDF with your results, without the test questions: pictures, descriptions, recommendations, a 4-week plan and questions to reflect on. A notes sheet with all the questions from your results is downloaded with it, to print out and answer by hand.',\n    dlBtn: 'Download results and notes sheet', again: 'Take it again',\n    wsTitle: 'Notes sheet', wsText: 'All the questions and steps from your results with space for your answers. Print it out and fill it in by hand.', wsBtn: 'Download notes sheet',\n    matEyebrow: 'Optional', matTitle: 'Would you like to receive my materials?',\n    matText: 'Leave your name and e-mail, and I will send you useful materials and tell you about new tests. Your test answers stay with you only: I only receive the details from this form.',\n    name: 'Name *', email: 'E-mail *', contact: 'Telegram or WhatsApp', contactPh: '@username or +41 …',\n    consent: link => `I agree that Iryna Voznesenskaya receives the details from this form, as described in the ${link} *`, consentLink: 'Privacy policy',\n    news: 'I would like to receive e-mails with useful materials. I can unsubscribe at any time.',\n    adult: 'I am 18 or older *', send: 'Send',\n    errName: 'Please enter your name.', errEmail: 'Please check your e-mail address.', errConsent: 'Your consent is needed to send the form.', errAdult: 'This test is for people aged 18 and over.',\n    sent: 'Thank you! Your details have been sent.', sendFail: 'Sending failed. Check your internet connection and try again.',\n    noLib: 'The PDF module could not be loaded. Check your internet connection and reload the page.',\n    making: 'Preparing the PDF…', madeMain: 'Results saved. Preparing the notes sheet…',\n    madeBoth: 'Done! Two files have been saved: your results and the notes sheet. If they did not open, look in your Downloads folder.',\n    madeOne: 'Results saved. If the file did not open, look in your Downloads folder.',\n    madeWsLater: 'Results saved. You can download the notes sheet with the button below.',\n    wsMaking: 'Preparing the notes sheet…', wsDone: 'Notes sheet saved. Print it out and write by hand.', wsFail: 'The notes sheet could not be prepared. Please try again.',\n    cancel: 'Saving cancelled.', fail: 'The PDF could not be prepared. Please try again.',\n    wsFile: 'Notes sheet', wsFoot: ' · notes sheet'\n  }\n};\nconst L = LT_ALL[PAGE_LANG] || LT_ALL.ru;\nconst HAS_WS = typeof worksheetBlocks === 'function';\nconst ASK_ADULT = (typeof BRAND !== 'undefined' && BRAND === 'psy');   // тесты о паре — только для взрослых\n\nfunction leadFormHtml(){\n  return `<div class=\"blk actions dl-box\" style=\"margin-top:18px\">\n    <h3>${HAS_WS ? L.dlTitle : L.dlTitle1}</h3>\n    <p>${HAS_WS ? L.dlText : L.dlText1}</p>\n    <p class=\"err\" id=\"formErr\" hidden></p>\n    <div class=\"row\">\n      <button class=\"btn\" type=\"button\" id=\"pdfBtn\">${HAS_WS ? L.dlBtn : L.dlBtn1}</button>\n      <button class=\"btn ghost\" type=\"button\" id=\"again\">${L.again}</button>\n    </div>\n    ${HAS_WS ? `<div class=\"ws-offer\" id=\"wsOffer\" hidden><b>${L.wsTitle}</b><span>${L.wsText}</span><button class=\"btn\" type=\"button\" id=\"wsBtn\">${L.wsBtn}</button></div>` : ''}\n    <span class=\"status\" id=\"status\" hidden></span>\n    <p class=\"note keep\" id=\"keepLine\"></p>\n    ${deleteAnswersHtml()}\n  </div>\n  <div class=\"blk mat-box\">\n    <div class=\"eyebrow\">${L.matEyebrow}</div><h3>${L.matTitle}</h3>\n    <p>${L.matText}</p>\n    <form id=\"lead\" class=\"stack\" style=\"gap:12px\" novalidate>\n      <div class=\"row\" style=\"align-items:stretch\">\n        <div class=\"field\"><label for=\"fName\">${L.name}</label><input id=\"fName\" maxlength=\"40\" autocomplete=\"given-name\"></div>\n        <div class=\"field\"><label for=\"fEmail\">${L.email}</label><input id=\"fEmail\" type=\"email\" maxlength=\"80\" autocomplete=\"email\"></div>\n      </div>\n      <div class=\"field\"><label for=\"fContact\">${L.contact}</label><input id=\"fContact\" maxlength=\"60\" placeholder=\"${L.contactPh}\"></div>\n      <label class=\"check\"><input type=\"checkbox\" id=\"fConsent\"> <span>${L.consent(`<a href=\"${legalUrl('privacy')}\" target=\"_blank\" rel=\"noopener\">${L.consentLink}</a>`)}</span></label>\n      <label class=\"check\"><input type=\"checkbox\" id=\"fNews\"> <span>${L.news}</span></label>\n      ${ASK_ADULT ? `<label class=\"check\"><input type=\"checkbox\" id=\"fAdult\"> <span>${L.adult}</span></label>` : ''}\n      <p class=\"err\" id=\"matErr\" hidden></p>\n      <div class=\"row\"><button class=\"btn\" type=\"submit\" id=\"matBtn\">${L.send}</button></div>\n      <p class=\"note\" id=\"matOk\" hidden></p>\n    </form>\n  </div>`;\n}\ndocument.querySelectorAll('[data-lead]').forEach(el => el.innerHTML = leadFormHtml());\n\nconst el = id => document.getElementById(id);\nfunction setStatus(t){ el('status').textContent = t; el('status').hidden = !t; }\nfunction setErr(t){ el('formErr').textContent = t; el('formErr').hidden = !t; }\nel('again').addEventListener('click', () => { el('result').hidden = true; el('intro').hidden = false; window.scrollTo(0,0); });\n\n/* прежняя анкета хранила контакты; теперь браузер помнит только страну (в мини-опросе) */\nfunction loadLead(){ return { country: surveyCountry(), name: (LEAD_HOOKS.personName && LEAD_HOOKS.personName()) || '' }; }\n\nconst _showResult = showResult;\nshowResult = function(){\n  _showResult();\n  setErr(''); setStatus('');\n  if (el('wsOffer')) el('wsOffer').hidden = true;\n  el('keepLine').textContent = retentionLine();\n  if (!el('fName').value) el('fName').value = (LEAD_HOOKS.personName && LEAD_HOOKS.personName()) || '';\n};\n\n// Чёткость PDF: 3 = около 290 точек на дюйм (хорошо для печати). На слабых телефонах — 2.5.\nconst PDF_SCALE = (/iPhone|iPad|Android/i.test(navigator.userAgent) && (navigator.deviceMemory || 4) < 4) ? 2.5 : 3;\nasync function buildPdf(getBlocks = buildBlocks, foot = null){\n  const stage = el('stage'); stage.innerHTML = '';\n  window.__PDF = true; let blocks; try { blocks = getBlocks(); } finally { window.__PDF = false; }\n  const footText = foot || footerLine();\n  const pages = [];\n  const newPage = () => {\n    const p = document.createElement('div'); p.className = 'pdf-page';\n    p.innerHTML = `<div class=\"strip\"></div><div class=\"pbody\"></div><div class=\"pfoot\"><span>${footText}</span><span class=\"pn\"></span></div>`;\n    stage.appendChild(p); pages.push(p); return p.querySelector('.pbody');\n  };\n  let body = newPage();\n  const mk = b => { const h = document.createElement('div'); h.innerHTML = b.html; return h.firstElementChild; };\n  const over = () => body.scrollHeight > body.clientHeight + 1;\n  const used = new Set();\n  for (let i = 0; i < blocks.length; i++){\n    const b = blocks[i];\n    if (!b.html || used.has(i)) continue;\n    if (b.newPage && body.children.length) body = newPage();\n    const node = mk(b);\n    body.appendChild(node);\n    if (over() && body.children.length > 1){\n      node.remove();\n      // свободное место внизу страницы заполняем небольшими «плавающими» блоками, которые идут дальше (float: true)\n      for (let j = i + 1; j < blocks.length; j++){\n        if (!blocks[j].float || used.has(j) || !blocks[j].html) continue;\n        const f = mk(blocks[j]); body.appendChild(f);\n        if (over()) f.remove(); else used.add(j);\n      }\n      body = newPage(); body.appendChild(node);\n    }\n    if (body.scrollHeight > body.clientHeight + 1 && body.children.length === 1){   // один блок выше страницы — уменьшаем, чтобы ничего не обрезалось\n      const k = body.clientHeight / node.scrollHeight;\n      node.style.transformOrigin = 'top left'; node.style.transform = `scale(${k})`; node.style.width = (100 / k) + '%';\n    }\n  }\n  pages.forEach((p, i) => p.querySelector('.pn').textContent = `${i+1} / ${pages.length}`);\n  if (document.fonts && document.fonts.ready) await document.fonts.ready;\n  const { jsPDF } = window.jspdf;\n  const pdf = new jsPDF({ unit:'pt', format:'a4', compress:true });\n  for (let i = 0; i < pages.length; i++){\n    const canvas = await html2canvas(pages[i], { scale:PDF_SCALE, backgroundColor:'#FFFFFF', useCORS:true, logging:false });\n    if (i) pdf.addPage();\n    pdf.addImage(canvas.toDataURL('image/jpeg', 0.95), 'JPEG', 0, 0, 595.28, 841.89, undefined, 'FAST');\n    const pr = pages[i].getBoundingClientRect(), k = 595.28 / pr.width;\n    pages[i].querySelectorAll('a[href]').forEach(a => {\n      if (!/^https?:/.test(a.href)) return;\n      const r = a.getBoundingClientRect();\n      pdf.link((r.left - pr.left) * k, (r.top - pr.top) * k, r.width * k, r.height * k, { url: a.href });\n    });\n  }\n  stage.innerHTML = '';\n  return pdf.output('blob');\n}\n\nlet downloadsCap = null;\n(async () => { try { if (window.claude && window.claude.use) downloadsCap = await window.claude.use('downloads'); } catch(e){ downloadsCap = null; } })();\nasync function saveBlob(blob, filename){\n  if (downloadsCap){ await downloadsCap.save({ filename, data: blob }); return; }\n  const url = URL.createObjectURL(blob);\n  const a = document.createElement('a');\n  a.href = url; a.download = filename; a.rel = 'noopener'; document.body.appendChild(a); a.click(); setTimeout(() => a.remove(), 1000);\n  setTimeout(() => URL.revokeObjectURL(url), 60000);\n}\nconst cleanName = s => s.replace(/[\\\\/:*?\"<>|]+/g, ' ').replace(/\\s+/g, ' ').trim();\n\n/* ---------- отправка в таблицу: без результатов теста ---------- */\nfunction basePayload(){\n  const src = new URLSearchParams(location.search);\n  const sv = (typeof surveyAnswers === 'function') ? surveyAnswers() : { heard: [], interest: [] };\n  return {\n    testId: TEST_META.id, testName: TEST_META.name, lang: PAGE_LANG, country: surveyCountry(),\n    heard: sv.heard.join(', '), interest: sv.interest.join(', '),\n    source: src.get('utm_source') || src.get('src') || document.referrer || 'прямой заход'\n  };\n}\nasync function post(payload){\n  if (!ENDPOINT) return;\n  await fetch(ENDPOINT, { method:'POST', mode:'no-cors', headers:{ 'Content-Type':'text/plain;charset=utf-8' }, body: JSON.stringify(payload) });\n}\nlet statSent = false;\nasync function sendStat(){       // анонимно: без имени, e-mail и результатов; один раз за открытие разбора\n  if (statSent) return; statSent = true;\n  try { await post({ kind: 'stat', ...basePayload() }); } catch(e){}\n}\n\n/* ---------- скачать разбор и бланк ---------- */\nel('pdfBtn').addEventListener('click', async () => {\n  setErr('');\n  if (!window.jspdf || !window.html2canvas) return setErr(L.noLib);\n  const btn = el('pdfBtn'); btn.disabled = true; setStatus(L.making);\n  try {\n    sendStat();\n    const blob = await buildPdf();\n    const fname = cleanName([TEST_META.name, ...LEAD_HOOKS.fileNames(), new Date().toLocaleDateString(DATE_LOCALE)].filter(Boolean).join(' — '));\n    await saveBlob(blob, fname + '.pdf');\n    if (!HAS_WS){ setStatus(L.madeOne); return; }\n    el('wsOffer').hidden = false;\n    setStatus(L.madeMain);\n    try { await downloadWorksheet(); setStatus(L.madeBoth); }\n    catch(e2){ setStatus(L.madeWsLater); }\n  } catch(e){\n    setStatus('');\n    setErr(e && e.code === 'declined' ? L.cancel : L.fail);\n  } finally { btn.disabled = false; }\n});\nasync function downloadWorksheet(){\n  const nm = (LEAD_HOOKS.personName && LEAD_HOOKS.personName()) || '';\n  const pair = (typeof WS_PAIR !== 'undefined') ? WS_PAIR : TEST_META.id === 'roza-lyubvi';\n  const blob = await buildPdf(() => { buildBlocks(); return worksheetBlocks({ name: nm, pair }); }, footerLine() + L.wsFoot);\n  const fname = cleanName([L.wsFile, TEST_META.name, nm, new Date().toLocaleDateString(DATE_LOCALE)].filter(Boolean).join(' — '));\n  await saveBlob(blob, fname + '.pdf');\n}\nif (el('wsBtn')) el('wsBtn').addEventListener('click', async () => {\n  const b = el('wsBtn'); b.disabled = true; setErr(''); setStatus(L.wsMaking);\n  try { await downloadWorksheet(); setStatus(L.wsDone); }\n  catch(e){ setStatus(''); setErr(e && e.code === 'declined' ? L.cancel : L.wsFail); }\n  finally { b.disabled = false; }\n});\n\n/* ---------- форма «Хочешь получать мои материалы?» (по желанию) ---------- */\nel('lead').addEventListener('submit', async (ev) => {\n  ev.preventDefault();\n  const err = t => { el('matErr').textContent = t; el('matErr').hidden = !t; };\n  err(''); el('matOk').hidden = true;\n  const lead = { name: el('fName').value.trim(), email: el('fEmail').value.trim(), contact: el('fContact').value.trim(),\n                 marketing: el('fNews').checked, consent: el('fConsent').checked, adult: ASK_ADULT ? el('fAdult').checked : null };\n  if (!lead.name) return err(L.errName);\n  if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$/.test(lead.email)) return err(L.errEmail);\n  if (!lead.consent) return err(L.errConsent);\n  if (ASK_ADULT && !lead.adult) return err(L.errAdult);\n  const b = el('matBtn'); b.disabled = true;\n  try {\n    await post({ kind: 'lead', ...basePayload(), ...lead });\n    el('matOk').textContent = L.sent; el('matOk').hidden = false;\n    el('lead').querySelectorAll('input').forEach(i => { if (i.type === 'checkbox') i.checked = false; else if (i.id !== 'fName') i.value = ''; });\n  } catch(e){ err(L.sendFail); }\n  finally { b.disabled = false; }\n});\nwindow.__buildPdf = buildPdf;\n"]};
